OWN_FOLDER_RE = re.compile(r"/items/[^/\s']+/(?:attempt_\d+/)?")      # a path inside a kit-wave item folder is the job's own
MISSING_ABS_RE = re.compile(r"No such file or directory: '(/(?:srv|home)/[^']+)'")


def kit_not_self_contained(text):
    """the first missing absolute /srv or /home path that is NOT inside an item (job) folder, or '' (KIT_NOT_SELF_CONTAINED)"""
    for m in MISSING_ABS_RE.finditer(text or ""):
        if not OWN_FOLDER_RE.search(m.group(1)):
            return m.group(1)[:200]
    return ""


SELFCONT_PY = r"""
import os, re, sys, shutil, hashlib
K, W = os.path.realpath(sys.argv[1]), sys.argv[2]
MODE = sys.argv[3] if len(sys.argv) > 3 else "list"
MAXF, MAXD = 600 * 2**20, 200 * 2**20          # copy a file up to 600 MB, a directory up to 200 MB
pat = re.compile(r"(?<![\w./-])(/(?:srv|home)/[^\s'\"\\);:,<>|$]+)")
skip = {"run", "results", "logs", "objects", "_ext"}
EXT = os.path.join(K, "_ext")
copied = {}                                        # outside path -> in-kit path
rows = []

def dsize(p):
    n = 0
    for r, _, fs in os.walk(p):
        for f in fs:
            try: n += os.path.getsize(os.path.join(r, f))
            except OSError: pass
            if n > MAXD: return n
    return n

def copy_in(a):
    if a in copied: return copied[a]
    if not os.path.exists(a): return None
    h = hashlib.sha1(a.encode()).hexdigest()[:8]
    dst = os.path.join(EXT, h + "_" + os.path.basename(a))
    try:
        if os.path.isdir(a):
            if dsize(a) > MAXD: return "BIGDIR"
            if not os.path.exists(dst): shutil.copytree(a, dst, symlinks=False)
        else:
            if os.path.getsize(a) > MAXF: return "BIGFILE"
            os.makedirs(EXT, exist_ok=True)
            if not os.path.exists(dst): shutil.copy2(a, dst)
    except OSError as e:
        return "ERR " + str(e)[:80]
    copied[a] = dst
    return dst

for root, dirs, files in os.walk(K):
    dirs[:] = [d for d in dirs if d not in skip]
    for f in files:
        if not (f.endswith((".mk", ".sh", ".tcl", ".f", ".sdc", ".py")) or f == "config.mk"):
            continue
        p = os.path.join(root, f)
        try:
            if os.path.getsize(p) > 2_000_000: continue
            txt = open(p, errors="replace").read()
        except OSError:
            continue
        new, changed = txt, False
        # a path that is only named in a comment is not read (pg_pair_cap.tcl line 1 named drt0255-proof/... and failed 6 QC kits):
        # whole-line # comments and trailing "  # ..." comments are not scanned (.mk .sh .tcl .sdc .py; .f has none)
        code = "\n".join("" if ln.lstrip().startswith("#") else re.split(r"(?:\s|;)#", ln, 1)[0] for ln in txt.splitlines())
        for m in sorted(set(pat.findall(code)), key=len, reverse=True):
            a = m.rstrip("/")
            if a.startswith(K.rstrip("/")) or a.startswith(W.rstrip("/")): continue
            if re.search(r"[*?\[]", a) or re.fullmatch(r"/(?:srv|home)/[^/]+(?:/claude)?", a) or a.rstrip("/").endswith("/claude"): continue   # globs / roots of the script's own search, not files
            if MODE != "copy":
                rows.append((os.path.relpath(p, K), "OUTSIDE", a)); continue
            r = copy_in(a)
            if r is None:
                rows.append((os.path.relpath(p, K), "MISSING", a))
            elif r in ("BIGDIR", "BIGFILE") or r.startswith("ERR"):
                rows.append((os.path.relpath(p, K), "IMPOSSIBLE " + r, a))
            else:
                new = new.replace(m, r + ("/" if m.endswith("/") else "")); changed = True
                rows.append((os.path.relpath(p, K), "COPIED", a + " -> " + r))
        if changed:
            tmp = p + ".sc"
            open(tmp, "w").write(new); shutil.copystat(p, tmp); os.replace(tmp, p)
seen = set()
for f, st, a in rows:
    if (f, st, a) in seen: continue
    seen.add((f, st, a)); print("SELFCONT\t%s\t%s\t%s" % (f, st, a))
bad = sum(1 for f, st, a in seen if st == "MISSING" or st.startswith("IMPOSSIBLE"))
print("SELFCONT_COUNT %d BAD %d" % (len(seen), bad))
"""
# KW-FIX-45 11-11 (COORD 23:5x): the hub-guard --exclude-hosts flag made ot-run print its usage text and NOT RUN; 29 attempts of
# 12 QC rows were charged to RETRY-INFRA although no command ran.  An ot-run / ot-heavy 'NOT RUN' (admission refusal, usage text,
# held host) means the command never started: such an attempt is no attempt.  The row waits NO_HOST_RETRY_S and is relaunched;
# NOT_RUN_FREE_MAX bounds the free tries of one row, then the budget is charged as before (a permanent tool fault still ends).
NOT_RUN_LINE = re.compile(r"(?m)^NOT-RUN\b|^\s*(?:ot-run|ot-heavy|ot-job): NOT RUN\b|^\s*(?:usage|Usage): ot-run\b|ot-run: unknown option|ot-run: unrecognized")
NOT_RUN_FREE_MAX = 8
# FLOW-OPS-1300 item 9: ot-run's own NOT-RUN lines (disk-ETA hold, no host with --dir has N GB, KW_PLACE_RC=78 = ot-run EX_CONFIG refusal) and a restaged unstarted waiter
INFRA_RETRY_RE = re.compile(r"(?m)^NOT-RUN\b[^\n]*|ot-run: NOT RUN: no host with --dir has[^\n]*|NOT-RUN disk-ETA hold[^\n]*|^KW_PLACE_RC=78\b|restaged: unstarted ot-run waiter[^\n]*")
INFRA_RETRY_BACKOFF_S = (900, 1800, 3600)


def infra_retry_kind(rec):
    """-> 'not-run' | 'restage' | '' for a FAIL row whose attempt never started its heavy command (FLOW-OPS-1300 item 9)"""
    if rec.get("status") != "FAIL":
        return ""
    d = Path(rec.get("dir") or "/nonexistent")
    txt = str(rec.get("reason") or "")
    for f in ("place.log", f"{rec.get('stage') or 'place'}.log"):
        try:
            txt += "\n" + "\n".join((d / f).read_text(errors="replace").splitlines()[-40:])
        except OSError:
            pass
    ms = list(INFRA_RETRY_RE.finditer(txt))
    if ms and "ot-run: RAN on" not in txt[ms[-1].end():]:
        return "not-run"
    if int(rec.get("restage_n") or 0) > 0 and not (d / "result.json").exists():
        return "restage"                      # moved between hosts while unstarted, its stopped unit then read as a failure
    return ""


def infra_retry_sweep(AP, cfg, st, now=None, write=True):
    """FLOW-OPS-1300 item 9: every current-event FAIL row whose attempt never started (NOT-RUN / restage) -> RETRY-INFRA, not charged (infra_base +1), paced by an
    exponential backoff (no_host_at + INFRA_RETRY_BACKOFF_S[n]); NOT_RUN_FREE_MAX free requeues per row.  -> [(key, kind)]"""
    now = time.time() if now is None else now
    out = []
    for key, r in (st.get("items") or {}).items():
        d = (cfg.get("dies") or {}).get(r.get("die")) or {}
        if d.get("event") and r.get("event") and str(r.get("event")) != str(d.get("event")):
            continue
        kind = infra_retry_kind(r)
        n = int(r.get("notrun_free") or 0)
        if not kind or n >= NOT_RUN_FREE_MAX or r.get("blocked"):
            continue
        out.append((key, kind))
        if write:
            back = INFRA_RETRY_BACKOFF_S[min(n, len(INFRA_RETRY_BACKOFF_S) - 1)]
            r.update(status="RETRY-INFRA", **{"class": "INFRA"}, infra_base=int(r.get("infra_base") or 0) + 1, notrun_free=n + 1,
                     no_host_at=now - NO_HOST_RETRY_S + back, updated=now, infra_retry=kind,
                     reason=f"INFRA-RETRY ({kind}: the command never started; requeued in {back // 60} min, not an attempt): {str(r.get('reason') or '')[:200]}")
            AP.log(f"KIT-WAVE INFRA-RETRY {r.get('die')}/{r.get('item')}@{r.get('attempt')} ({kind}): requeued, backoff {back // 60} min, free requeue {n + 1}/{NOT_RUN_FREE_MAX}")
    return out


def tool_not_run(text):
    """True when the output shows ot-run / ot-heavy refusing to start the command and no 'ot-run: RAN on' line (it never ran)"""
    t = text or ""
    return bool(NOT_RUN_LINE.search(t)) and "ot-run: RAN on" not in t


def free_not_run(rec, text, now=None):
    """charge-free requeue of a tool-side NOT RUN: infra_base +1 (the attempt does not count), paced by no_host_at.  True when applied"""
    if rec.get("class") != "INFRA" or not tool_not_run(text) or int(rec.get("notrun_free") or 0) >= NOT_RUN_FREE_MAX:
        return False
    rec["infra_base"] = int(rec.get("infra_base") or 0) + 1
    rec["notrun_free"] = int(rec.get("notrun_free") or 0) + 1
    rec["no_host_at"] = now if now is not None else time.time()
    rec["status"] = "RETRY-INFRA"
    return True
COPYBACK_FREE_MAX = 3


def is_place_no_odb(why):
    return str(why or "").startswith(PLACE_NO_ODB_WHY)


def free_place_no_odb(rec, now=None):
    """WAVE-COPYBACK-1115: a place that ended RC=0 with its odb elsewhere is no attempt: infra_used -> 0 (the next attempt resumes from
    the odb through resume_source's RAN-host candidate), bounded by COPYBACK_FREE_MAX per row, then the infra budget is charged as
    before.  True when applied"""
    if not is_place_no_odb(rec.get("reason")) or int(rec.get("copyback_free") or 0) >= COPYBACK_FREE_MAX:
        return False
    rec["copyback_free"] = int(rec.get("copyback_free") or 0) + 1
    rec["infra_base"] = max(int(rec.get("infra_base") or 0), int(rec.get("attempt") or 0))
    rec["no_host_at"] = 0
    rec["status"] = "RETRY-INFRA"
    return True


def place_log_rc0(d, tail_bytes=16384):
    """True when the last KW_PLACE_RC line in the tail of <d>/place.log is 0"""
    try:
        with open(Path(d) / "place.log", "rb") as f:
            f.seek(0, 2)
            f.seek(max(0, f.tell() - tail_bytes))
            t = f.read().decode("utf-8", "replace")
    except OSError:
        return False
    rcs = re.findall(r"(?m)^KW_PLACE_RC=(\d+)\s*$", t)
    return bool(rcs) and rcs[-1] == "0"


def rejudge_place_nodb(st, now=None, max_age_h=36.0):
    """WAVE-COPYBACK-1115 (FABLE-FLOW-1000 class 1): every tick, with the CURRENT code, re-judge each place FAIL whose log ended RC=0.  Run-items
    keep the tool tree of their launch, so a unit launched before the fix still probes the wrong host and writes the false FAIL; the tick
    (rt/current) turns it into an uncharged RETRY-INFRA that resumes from the odb.  One judgement per attempt (copyback_att).  -> [keys]"""
    now = now if now is not None else time.time()
    out = []
    for key, rec in (st.get("items") or {}).items():
        if rec.get("status") != "FAIL" or rec.get("stage") != "place" or not rec.get("dir"):
            continue
        if now - float(rec.get("updated") or 0) > max_age_h * 3600 or rec.get("copyback_att") == rec.get("attempt"):
            continue
        if not place_log_rc0(rec["dir"]):
            continue
        rec["copyback_att"] = rec.get("attempt")
        rec.update(**{"class": "INFRA"}, reason=f"{PLACE_NO_ODB_WHY} @place: KW_PLACE_RC=0, 3_place.odb not found by the probe", reclassified=now_s())
        if free_place_no_odb(rec):
            out.append(key)
    return out


STATE_FILE = "kit_wave_state.json"
LOAD_CAP_FACTOR = 1.5                                    # = ot-heavy LOAD_CAP_FACTOR (read here, set there)


def place_retry_sh(inner, log):
    """KW-FIX-17 11-05 (QC sle_stm_v1 a6 INFRA 15:12): the async PLACE service ran its ot-run client ONCE, so a gen-host
    sshd drop during ot-run's probe ('NOT RUN: no host qualifies (... epyc4: SSH probe exit 255 ...)') failed the
    attempt as INFRA; run() already retries such a drop.  Same rule here: a try whose own output says 'ot-run: NOT RUN'
    and has no 'ot-run: RAN on' (the command never started) is rerun up to SSH_RETRIES more times; rc in $rc."""
    lq = shlex.quote(log)
    return (f"for i in $(seq 0 {SSH_RETRIES}); do echo KW_PLACE_TRY $i; {inner}; rc=$?; [ $rc -eq 0 ] && break; "
            f"[ $rc -eq 143 ] || [ $rc -eq 130 ] || [ $rc -eq 129 ] && break; "     # FLOW-NOADV-R4: a cancelled (signalled) client is final, never retried
            f"t=$(sed -n \"/^KW_PLACE_TRY $i\\$/,\\$p\" {lq}); "
            f"printf '%s' \"$t\" | grep -q 'ot-run: RAN on' && break; "
            f"printf '%s' \"$t\" | grep -q 'ot-run: NOT RUN' || break; [ $i -lt {SSH_RETRIES} ] || break; "
            f"echo \"KW_SSH_RETRY place try $((i+2)) (ot-run NOT RUN before the command ran)\"; "
            f"sleep $((20*(i+1)+RANDOM%20)); done")


def place_cancelled(AP, rec):
    """FLOW-NOADV-R4 (COORD, S81-DIE-R5: `ot-run --cancel` of a wave place stage was read as 'ot-run never started' and placement restarted from scratch
    on 5 of 8 D8i svc_rs rows): the signals.log line of an explicit `ot-run --cancel` naming this attempt's place kit, at or after its service started
    -> the line, else None.  A cancel is final: no retry, the row is CANCELLED."""
    try:
        svc = json.loads((Path(rec["dir"]) / "place_service.json").read_text())
        return AP.signals_cancel({"path": svc["kit"], "started": float(svc.get("started") or 0)})
    except (OSError, ValueError, KeyError, TypeError):
        return None


def now_s():
    return time.strftime("%Y-%m-%d %H:%M %Z")


# ------------------------------------------------------------------------------------------------ config + gating
def load_config(text):
    try:
        cfg = json.loads(text) if text and text.strip() else {}
    except ValueError as e:
        return {"error": f"kit_wave.json unreadable: {e}", "dies": {}}
    cfg.setdefault("dies", {})
    normalize_retry_fix(cfg)
    compile_hold_records(cfg)
    apply_hold_release_on(cfg)
    return cfg


RETRY_FIX_RE = re.compile(r"^(?P<ia>[^@\s:]+@\d+):fix=(?P<fix>\S+)$")


def normalize_retry_fix(cfg):
    """FLOW-FIX-0100 (FABLE-FLOW-2350 d): a retry key is `item@N:fix=<sha or row>`.  Every consumer of dies.<die>.retry reads the plain `item@N`, so the
    fix text moves into the in-memory die field `_retry_fix` {item@N: fix} and the list keeps the plain key.  A plain `item@N` has no fix and is
    honoured only for an INFRA failure (retry_key_allowed)."""
    for d in (cfg.get("dies") or {}).values():
        if not isinstance(d, dict) or not isinstance(d.get("retry"), list):
            continue
        fx = d.setdefault("_retry_fix", {})
        out = []
        for ia in d["retry"]:
            m = RETRY_FIX_RE.match(str(ia).strip())
            if m:
                fx[m["ia"]] = m["fix"]
                ia = m["ia"]
            if ia not in out:
                out.append(ia)
        d["retry"] = out


_TREE_CACHE = {}
_TREE_LOGGED = set()


_TREE_SYNC = False        # tests: run the background verifies inline


def _src_manifest_hosts(hosts, tree, expect, links_only):
    """r284 (COORD): `src_manifest.py hosts TREE --hosts h1,h2 --expect HASH [--links-only]` from this tool tree -> (rc, text).  The full
    hash verify (switch time) can take minutes on a 300k-file tree; --links-only is the stat-only shared-inode check of later ticks."""
    cmd = [sys.executable, "-I", os.path.join(os.path.dirname(os.path.abspath(__file__)), "src_manifest.py"), "hosts", tree,
           "--hosts", ",".join(hosts)] + (["--links-only"] if links_only else ["--expect", expect])
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=1800)
    except (OSError, subprocess.SubprocessError) as e:
        return 1, f"{type(e).__name__}: {e}"
    return r.returncode, (r.stdout + r.stderr).strip()


def tree_gate(AP, cfg):
    """HOLDGEN-1115 (FABLE-FLOW-0445 class 4, r284): -> (tree_fn, marker_fn) for the typed term tree_ready:<die>:<tree>.
    marker_fn(die) = lanes/handoff/tree_switch_<die>.json of the coord tree (written by the tree builder, coord-committed):
    {"tree": path, "manifest_hash": ..., "smoke": "PASS", "die_gen_env": {...}, "config": {die keys, dicts merged}}.
    tree_fn(die, tree): the marker names the tree with smoke PASS, and on every gen host of the die (die.gen_hosts, else cfg hosts,
    minus retired_hosts) <tree>/.src-manifest.sha256 equals the marker hash (cheap).  Then, once per tree, `src_manifest hosts --expect
    <hash>` verifies the files on all those hosts in an independent user unit (the answer stays False until it passes).
    Completed publication receipts may supply the existing content verification, with current immutable metadata rechecked.
    Results survive oneshot tick exit; `hosts --links-only` rechecks every 600 s. Failed checks keep their attempt evidence."""
    import hold_records as _HR
    import tree_check as _TC
    retired = cfg.get("retired_hosts") or []
    hub = AP.HUB_NAME
    check_root = Path(getattr(AP, "AP_DIR", cfg.get("_ap_dir") or os.path.expanduser("~/.local/state/opentallas"))) / "tree_checks"
    checker = os.path.join(os.path.dirname(os.path.abspath(__file__)), "src_manifest.py")

    def hosts_of(die):
        d = (cfg.get("dies") or {}).get(die) or {}
        return [h for h in (d.get("gen_hosts") or cfg.get("hosts") or []) if h not in retired]

    def marker(die):
        try:
            m = json.loads(AP.read_coord(_HR.tree_marker_rel(die)) or "null")
        except ValueError:
            return None
        if not isinstance(m, dict):
            return None
        # Published-tree markers use src_manifest_sha; older hold markers call
        # the same digest manifest_hash. Normalize the existing contract.
        if not m.get("manifest_hash") and m.get("src_manifest_sha"):
            m["manifest_hash"] = m["src_manifest_sha"]
        # Only a completed manifest verification supplies identity. Never trust
        # a private field copied into a hand-written marker or its tools_sha.
        m.pop("_validated_main_sha", None)
        key = (die, m.get("tree"), str(m.get("manifest_hash") or ""), tuple(hosts_of(die)))
        ent = _TREE_CACHE.get(key) or {}
        if ent.get("state") == "ok" and ent.get("main_sha"):
            m["_validated_main_sha"] = ent["main_sha"]
        return m

    def host_has(h, tree, want):
        # Read the base identity alongside the existing cheap hash probe. The
        # full manifest check below validates it before marker() exposes it.
        script = ("import json, pathlib, sys; p=pathlib.Path(sys.argv[1]); "
                  "print((p / '.src-manifest.sha256').read_text().strip()); "
                  "f=p / '.src-manifest.json'; "
                  "print(json.loads(f.read_text()).get('main_sha', '') if f.is_file() else '')")
        cmd = ["python3", "-I", "-c", script, tree]
        try:
            if h in ("localhost", hub):
                r = subprocess.run(cmd, capture_output=True, text=True, timeout=20)
            else:
                r = subprocess.run(_ssh(h, hub) + [" ".join(shlex.quote(x) for x in cmd)], capture_output=True, text=True, timeout=30)
            lines = r.stdout.splitlines()
            ok = r.returncode == 0 and bool(lines) and lines[0].strip() == want
            main = lines[1].strip() if len(lines) > 1 else ""
            return ok, main if re.fullmatch(r"[0-9a-f]{40}", main) else ""
        except (OSError, subprocess.SubprocessError):
            return False, ""

    def run_bg(ent, hosts, tree, want, links_only):
        if not _TREE_SYNC:
            # A separate user unit survives this oneshot tick's cgroup. Its
            # pinned checker and durable result are shared by subsequent ticks.
            ent.update(_TC.launch(check_root, ent["_identity"], checker, ent.get("main_sha", ""), links_only))
            return
        def job():
            rc, txt = _src_manifest_hosts(hosts, tree, want, links_only)
            if rc != 0 and links_only and "unrecognized arguments" in txt:
                rc = 0                                   # rt without r284 yet: no links check available, not a failure
            ent["t"] = time.time()
            if rc == 0:
                ent.update(state="ok", links_t=time.time())
            else:
                ent.update(state="bad", why=txt[-300:])
                AP.log(f"KIT-WAVE TREE-CHECK {'links' if links_only else 'verify'} FAILED {tree}: {txt[-200:]}")
            ent["running"] = False
        ent["running"] = True
        job()                                                 # deterministic inline mode used by unit tests

    def ready(die, tree):
        m = marker(die)
        want = str((m or {}).get("manifest_hash") or "")
        hosts = hosts_of(die)
        if not m or m.get("tree") != tree or str(m.get("smoke") or "").upper() != "PASS" or not want or not hosts:
            return False
        key, now = (die, tree, want, tuple(hosts)), time.time()
        ident = _TC.identity(die, tree, want, hosts, checker)
        if not _TREE_SYNC:
            saved = _TC.read(check_root, ident)
            if saved:
                _TREE_CACHE[key] = saved
        ent = _TREE_CACHE.get(key)
        if ent is not None:
            ent["_identity"] = ident
        if ent is not None and ent.get("running"):
            return ent.get("state") == "ok"
        if ent is not None and ent.get("state") == "ok":
            if now - ent.get("links_t", 0) > 600:
                run_bg(ent, hosts, tree, want, True)             # later ticks: stat-only shared-inode check
            return ent.get("state") == "ok"
        if ent is not None and ent.get("full_ok") and ent.get("state") == "bad":
            if now - ent.get("t", 0) >= 300:
                run_bg(ent, hosts, tree, want, True)             # retry the failed stat check, not the completed content hash
            return False
        if ent is not None and now - ent.get("t", 0) < (300 if ent.get("state") == "bad" else 60):
            return False
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=len(hosts)) as ex:
            probes = list(ex.map(lambda h: host_has(h, tree, want), hosts))
        have = all(ok for ok, _main in probes)
        mains = {main for ok, main in probes if ok and main}
        ent = _TREE_CACHE[key] = {"t": now, "state": "cheap" if have else "absent", "running": False,
                                  "main_sha": next(iter(mains)) if len(mains) == 1 else "", "_identity": ident}
        if have:
            run_bg(ent, hosts, tree, want, False)                # switch time: src_manifest hosts --expect <hash>
        return ent.get("state") == "ok"
    return ready, marker



def verified_source_probes(AP, cfg, st, die, tree_fn, marker_fn, read_check=None):
    """Feed exact durable source verification into source-only probe lifecycle.
    This never judges snapshot, circuit, lint or physical classes. Failed attempts
    stay on disk and FG.close retains its normal probation/history semantics.
    """
    import tree_check as TC
    d = (cfg.get("dies") or {}).get(die) or {}
    tree = d.get("src")
    inp = breaker_inputs(cfg, die)
    probes = [e for e in ((st.get("flow_guard") or {}).get("open") or {}).values()
              if e.get("die") == die and not e.get("kind") and e.get("stage") == "src_manifest"
              and e.get("state") == "probe"]
    if not tree or not inp or not probes or not tree_fn(die, tree):
        return []
    marker = marker_fn(die) or {}
    want = marker.get("manifest_hash") or marker.get("src_manifest_sha")
    if marker.get("tree") != tree or str(marker.get("smoke") or "").upper() != "PASS" or not want:
        return []
    hosts = [h for h in (d.get("gen_hosts") or cfg.get("hosts") or [])
             if h not in (cfg.get("retired_hosts") or [])]
    if not hosts:
        return []
    root = Path(getattr(AP, "AP_DIR", cfg.get("_ap_dir") or os.path.expanduser("~/.local/state/opentallas"))) / "tree_checks"
    ident = TC.identity(die, tree, want, hosts, str(Path(__file__).with_name("src_manifest.py")))
    proof = (read_check or TC.read)(root, ident)
    if (not proof or proof.get("identity") != ident or proof.get("state") != "ok"
            or not proof.get("full_ok") or proof.get("running")
            or not proof.get("links_t") or time.time() - proof["links_t"] > 600
            or not proof.get("details")
            or {x.get("host") for x in proof["details"]} != set(hosts)
            or any(x.get("rc") != 0 for x in {x.get("host"): x for x in proof["details"]}.values())):
        return []
    evidence = str(TC.location(root, ident) / "result.json")
    def active(item):
        if not item:
            return False
        if live_attempt_elsewhere(st, die, item, None):
            return True
        terminal = {"FAIL", "CANCELLED", "PASS", "DONE", "REJECTED", "DISCARDED"}
        return any(r.get("die") == die and r.get("item") == item and
                   (r.get("enqueue_pending") or r.get("status") not in terminal)
                   for r in (st.get("items") or {}).values())
    eligible = []
    for key, e in list(((st.get("flow_guard") or {}).get("open") or {}).items()):
        if e in probes and FG.refresh_verified_source_probe(st, key, inp, evidence, active(FG.probe_item(e))):
            eligible.append(e)
    out = []
    for item in sorted({FG.probe_item(e) for e in eligible}):
        # An empty claim is also source-proven: no hardware launch is needed to
        # establish the exact same die-wide source files verified on every host.
        out.extend(FG.probe_result(st, die, item, "src_manifest", passed=True,
                                  required_stage="src_manifest", required_input=inp))
    for key, why in out:
        AP.log(f"KIT-WAVE FLOW-GUARD VERIFIED-SOURCE '{key}': {why}; proof {evidence}")
    return out


PILOT_PASS_STATUS = ("PASS", "ENQUEUED", "ROUTE-HELD", "SIGNED")


GEN_PILOT_STAGES = ("gen", "gen_kit", "gen_lint", "preflight")


def publish_gen_pilot_receipt(spec_path, spec_sha256, stages):
    """Publish source proof before PLACE, only for actual zero-exit GEN/preflight.
    Failure to write evidence never fails a build; it simply earns no early credit.
    """
    try:
        if any(stages.get(stage) != 0 for stage in GEN_PILOT_STAGES):
            return False
        if stages.get("kit_topology", 0) != 0:
            return False
        if stages.get("kit_rtl", 0) != 0:        # WAVE-PILOT-FIX 11-17: the kit_rtl canary; a pilot whose kit_rtl failed proves nothing
            return False
        spec_path = Path(spec_path)
        raw = spec_path.read_bytes()
        sp = json.loads(raw)
        if not isinstance(sp, dict) or sp.get("dry_gen"):
            return False
        sha = str(sp.get("src_manifest_hash") or "").lower()
        if (hashlib.sha256(raw).hexdigest() != spec_sha256
                or not re.fullmatch(r"[0-9a-f]{64}", sha)
                or not sp.get("die") or not sp.get("item") or not sp.get("src")):
            return False
        receipt = dict(schema="opentallas.gen_pilot.v1", stage="gen_preflight", verdict="PASS",
                       die=sp["die"], item=sp["item"], source=sp["src"], src_manifest_hash=sha,
                       spec_sha256=spec_sha256,
                       stages={stage: stages[stage] for stage in GEN_PILOT_STAGES})
        if "kit_topology" in stages:
            receipt["stages"]["kit_topology"] = stages["kit_topology"]
        if "kit_rtl" in stages:
            receipt["stages"]["kit_rtl"] = stages["kit_rtl"]
        receipt["canary"] = "kit_rtl_v1"          # receipts with this mark carry the kit_rtl verdict (older receipts are grandfathered)
        target = spec_path.with_name("gen_pilot.json")
        temp = target.with_name(target.name + "." + str(os.getpid()) + ".tmp")
        temp.write_text(json.dumps(receipt, sort_keys=True) + "\n")
        try:
            os.link(temp, target)                  # atomic, never replace a prior verdict
        except FileExistsError:
            return json.loads(target.read_text()) == receipt
        finally:
            temp.unlink(missing_ok=True)
        return True
    except (OSError, ValueError, TypeError, KeyError):
        return False


def kit_rtl_canary_ok(rec, spec):
    """WAVE-PILOT-FIX 11-17 (FABLE-FLOW-0900 B): no tree goes live without a pilot whose kit_rtl stage passed.  A stage rc recorded in the
    receipt must be 0; a receipt with the kit_rtl_v1 canary mark of a die whose recipe runs kit_rtl (mode bind or a script) must carry the
    stage.  Receipts written before the mark existed are grandfathered (they have no kit_rtl verdict to read)."""
    stages = rec.get("stages") or {}
    if "kit_rtl" in stages:
        return stages["kit_rtl"] == 0
    kr = spec.get("kit_rtl") if isinstance(spec, dict) else None
    runs = isinstance(kr, dict) and (kr.get("mode") == "bind" or bool(kr.get("script")))
    return not (rec.get("canary") == "kit_rtl_v1" and runs)


def gen_pilot_receipt_pass(path, die, item, spec, raw_spec):
    """An early proof is tied to the exact immutable attempt spec and source."""
    try:
        rec = json.loads((Path(path) / "gen_pilot.json").read_text())
        if not isinstance(rec, dict):
            return False
        return (rec.get("schema") == "opentallas.gen_pilot.v1"
                and rec.get("stage") == "gen_preflight" and rec.get("verdict") == "PASS"
                and not spec.get("dry_gen")
                and rec.get("die") == die == spec.get("die")
                and rec.get("item") == item == spec.get("item")
                and rec.get("source") == spec.get("src")
                and rec.get("src_manifest_hash") == spec.get("src_manifest_hash")
                and bool(re.fullmatch(r"[0-9a-f]{64}", str(rec.get("src_manifest_hash") or "")))
                and rec.get("spec_sha256") == hashlib.sha256(raw_spec).hexdigest()
                and all((rec.get("stages") or {}).get(stage) == 0 for stage in GEN_PILOT_STAGES)
                and (rec.get("stages") or {}).get("kit_topology", 0) == 0
                and kit_rtl_canary_ok(rec, spec))
    except (OSError, ValueError, TypeError):
        return False


def pilot_passed_map(st, cfg):
    """Source-specific pilot passes, including retained successful prior attempts.

    A mutable item row can point to a later running/failed attempt after its
    pilot passed. Its earlier immutable PASS result and matching spec still
    prove that source; another attempt never changes the source it proved.
    """
    out = {}
    for die, d in (cfg.get("dies") or {}).items():
        for record in d.get("hold_records") or []:
            if not record.get("auto_pilot") or not record.get("published_gen_proof"):
                continue
            try:
                import published_gen_origin as PGO
                for pilot in record.get("pilot_items") or []:
                    proved, _ = PGO.validate_reference(record["published_gen_proof"], cfg, die, pilot, sys.modules[__name__])
                    if proved:
                        out.setdefault(die, set()).add(proved[:12])
            except (ImportError, AssertionError, OSError, ValueError, TypeError, KeyError, AttributeError):
                pass                            # an unqualified import always leaves normal GEN available
        pilots = {i for r in d.get("hold_records") or [] if r.get("auto_pilot") for i in r.get("pilot_items") or []}
        if not pilots:
            continue
        for r in (st.get("items") or {}).values():
            if r.get("die") != die or r.get("item") not in pilots:
                continue
            attempt = Path(r.get("dir") or "")
            candidates = [(attempt, r.get("status") in PILOT_PASS_STATUS)]
            if re.fullmatch(r"a[0-9]+", attempt.name):
                try:
                    candidates.extend((p, False) for p in attempt.parent.iterdir()
                                      if p != attempt and re.fullmatch(r"a[0-9]+", p.name) and p.is_dir())
                except OSError:
                    pass
            for path, row_pass in candidates:
                try:
                    raw_spec = (path / "spec.json").read_bytes()
                    sp = json.loads(raw_spec)
                    if not row_pass and not gen_pilot_receipt_pass(path, die, r["item"], sp, raw_spec):
                        result = json.loads((path / "result.json").read_text())
                        if (result.get("verdict") != "PASS" or result.get("stage") != "geom"
                                or result.get("die") != die or result.get("item") != r["item"]
                                or sp.get("die") != die or sp.get("item") != r["item"]):
                            continue
                except (OSError, ValueError, KeyError, TypeError):
                    continue
                sha = str(sp.get("src_manifest_hash") or "")[:12].lower()
                if re.fullmatch(r"[0-9a-f]{12}", sha):
                    out.setdefault(die, set()).add(sha)
    return {die: sorted(shas) for die, shas in out.items()}


def release_pilot_passed(rows, die, item, t0, cfg=None):
    """A post-release selected attempt passed GEN, or reached a legacy PASS state.
    The early path reads only the immutable LIVE receipt, not imported/dry or
    prior-attempt evidence. It changes no physical result or hold.
    """
    for row in rows or []:
        try:
            if (row.get("die") != die or row.get("item") != item
                    or float(row.get("started") or 0) < float(t0)):
                continue
            if row.get("status") in PILOT_PASS_STATUS:
                return True
            if cfg is None or not row.get("dir"):
                continue
            path = Path(row["dir"])
            raw = (path / "spec.json").read_bytes()
            spec = json.loads(raw)
            if not isinstance(spec, dict) or (path / "gen_pilot.json").stat().st_mtime < float(t0):
                continue
            d = (cfg.get("dies") or {}).get(die) or {}
            ii = (d.get("item_inputs") or {}).get(item) or {}
            expected = {"src": ii.get("src") or d.get("src"),
                        "src_manifest_hash": ii.get("src_manifest_hash") or d.get("src_manifest_hash"),
                        "plan": ii.get("plan") or d.get("plan")}
            if any(not value or spec.get(key) != value for key, value in expected.items()):
                continue
            args = list(d.get("gen_args") or []) + list((d.get("type_args") or {}).get(item) or [])
            if item in (d.get("hard_wrappers") or []):
                args += ["--hard-wrappers", item]
            env = ({"OT_FLOW_TAG": str(d["flow_tag"])} if d.get("flow_tag") else {}) | item_env(d, item)
            if spec.get("gen_args", []) != args or spec.get("gen_env", {}) != env:
                continue
            if gen_pilot_receipt_pass(path, die, item, spec, raw):
                return True
        except (OSError, ValueError, TypeError, KeyError):
            continue
    return False


def release_pilot_failed(rows, die, item, t0):
    """WAVE-PILOT-FIX 11-17: True when the pilot's attempt started after the release T0 has FAILed and the failure is not a shared design class
    (infra / flow / per-instance): such a pilot never keeps the family held"""
    last = None
    for row in rows or []:
        try:
            if row.get("die") == die and row.get("item") == item and float(row.get("started") or 0) >= float(t0):
                if last is None or float(row.get("started") or 0) >= float(last.get("started") or 0):
                    last = row
        except (TypeError, ValueError):
            continue
    if last is None:
        return False
    failed = last.get("status") == "FAIL" or (last.get("status") == "ENQUEUED" and last.get("q_status") == "FAIL")
    return bool(failed) and pilot_fail_scope(last) != "shared"


def tree_has_term(cfg, die, token):
    """WAVE-FLOW-R2 11-17 (FABLE-FLOW-1700 item 2): tree_has:<rNNN> / tree_has_sha:<sha> is true only when the die's CURRENT tree tools contain that ruling / commit
    (tools_lag ancestry against the tree's tools base: tools_sha, marker main_sha, src_sha); unknown / unreadable = False (the hold stays)"""
    try:
        spec = _ilu.spec_from_file_location("tools_lag", str(Path(__file__).resolve().parents[1] / "tools_lag.py"))
        TL = _ilu.module_from_spec(spec)
        spec.loader.exec_module(TL)
        d = (cfg.get("dies") or {}).get(die) or {}
        pin = TL.pin_of(d)
        return bool(pin) and TL.tree_has(cfg.get("tools_lag_repo") or TL.DEFAULT_REPO, pin, token, main_ref=cfg.get("tools_lag_main") or "main")
    except Exception:
        return False


def hold_ctx(cfg, is_merged=None, tree_fn=None, marker_fn=None):
    import hold_records as HR
    cells = cfg.get("_item_cells") or {}
    proofs = cfg.get("_proof_lines") or []
    return HR.Ctx(is_merged=is_merged or _git_is_merged, event_met=_hold_term_met, digest_fn=input_digest,
                  kit_snap_fn=lambda c, die: bool(opt(c, die, "kit_snap")),
                  cells_fn=lambda die, item: cells.get((die, item)),
                  proof_fn=proof_pass_fn(proofs),
                  tree_has_fn=lambda die, token: tree_has_term(cfg, die, token),
                  tree_fn=tree_fn, marker_fn=marker_fn, result_fn=result_pass_fn(cfg.get("_result_lines") or []), lint_fn=lambda die, item: lint_clean_item(cfg, die, item),
                  pilot_fn=lambda die, sha12: sha12 in ((cfg.get("_pilot_passed") or {}).get(die) or []),
                  release_pilot_fn=lambda die, item, t0: release_pilot_passed(cfg.get("_item_rows") or [], die, item, t0, cfg),
                  release_pilot_failed_fn=lambda die, item, t0: release_pilot_failed(cfg.get("_item_rows") or [], die, item, t0))


RESULT_POST = r"^\s*-?\s*\d{4}-\d\d-\d\d\s+\S+\s+[A-Za-z]{2,4}\s+RESULT\s*\["        # a post OF TYPE RESULT: "- 2026-11-16 07:18 PST RESULT [LANE ->"


def result_posts(lines):
    """the queue lines that are posts of type RESULT (the type word sits right after the timestamp).  A RULING / READY / ASK line that
    quotes 'RESULT [LANE -> COORD] tag PASS' as an instruction is NOT a result (r297 did, and released 14 svc keys + hd_serdes at 07:32)."""
    rx = re.compile(RESULT_POST)
    return [ln for ln in lines if rx.match(ln)]


def result_pass_fn(lines):
    """result:<lane>:<tag>: true when a RESULT post sent by the lane (header 'RESULT [LANE ->' or 'RESULT [LANE]': S81-DIE-R3 / S81-TYPES-R3 posted without the arrow and 213 col keys stayed held) carries '<tag>' followed within 60
    characters by PASS (a lane that writes 'svc-ready NOT yet, FAIL' does not release; a post that only cc's the lane does not)."""
    posts = result_posts(lines)

    def f(lane, tag):
        pat = re.compile(RESULT_POST + re.escape(lane) + r"\s*(?:->|\])[^\n]*?(?<![\w.-])" + re.escape(tag) + r"(?![\w.-])[^\n]{0,60}?\bPASS\b")
        return any(pat.match(ln) for ln in posts)
    return f


def proof_pass_fn(lines):
    """proof:<name>: a RESULT post (any lane) with '<name>' followed within 60 characters by PASS."""
    posts = result_posts(lines)

    def f(name):
        pat = re.compile(r"(?<![\w.-])" + re.escape(name) + r"(?![\w.-])[^\n]{0,60}?\bPASS\b")
        return any(pat.search(ln) for ln in posts)
    return f


def lint_clean_item(cfg, die, item):
    """lint_clean:<die> for one hold key: no row of the die (item, or any item the glob key covers) has its latest attempt failed in
    sdc_lint.  cfg['_lint_fail'][die] = items whose latest row is a FAIL naming sdc_lint (filled each tick from the wave state);
    an item never linted is clean (the term gates on a known failure, as the release of 'lint decides per item' needs)."""
    bad = (cfg.get("_lint_fail") or {}).get(die) or ()
    if any(ch in str(item) for ch in "*?["):
        return not any(fnmatch.fnmatchcase(b, str(item)) for b in bad)
    return str(item) not in bad



def lint_failures(cfg, rows, read_spec=None):
    """Latest SDC verdict per item in the adopted plan/source context.
    Known different contexts cannot block this release. Missing legacy identity
    remains conservative and is never evidence that a failure was repaired.
    """
    def spec_of(row):
        if read_spec is not None:
            return read_spec(row) or {}
        try:
            return json.loads((Path(row.get("dir") or ".") / "spec.json").read_text())
        except (OSError, ValueError):
            return {}
    out = {}
    for row in sorted(rows, key=lambda r: float(r.get("started") or 0)):
        die, item = row.get("die"), row.get("item")
        if not die or not item:
            continue
        d = (cfg.get("dies") or {}).get(die) or {}
        current_plan = d.get("plan_sha256") or d.get("_plan_sha")
        old_plan = row.get("plan_sha")
        if current_plan and old_plan and str(current_plan).lower() != str(old_plan).lower():
            continue
        sp = spec_of(row) if d.get("src") or d.get("src_sha") else {}
        # These paths identify immutable published source trees. Missing old
        # specs keep the legacy verdict in scope.
        if any(d.get(k) and sp.get(k) and d[k] != sp[k] for k in ("src", "src_sha")):
            continue
        bad = row.get("status") == "FAIL" and "sdc_lint" in (
            str(row.get("stage")) + " " + str(row.get("reason")) + " " + str(row.get("class")))
        items = out.setdefault(die, set())
        (items.add if bad else items.discard)(item)
    return out


def compile_hold_records(cfg, is_merged=None, tree_fn=None, marker_fn=None):
    """HOLDGEN-1115 (COORD r223): die.hold_records (typed release terms, bound to a plan sha) compile into hold_items in memory, before
    the legacy hold_release_on pass.  A die without hold_records is untouched."""
    import hold_records as HR
    ctx = hold_ctx(cfg, is_merged, tree_fn, marker_fn)
    try:
        return HR.compile_holds(cfg, ctx)
    except Exception as e:                               # a bad record never stops the wave: legacy hold_items still apply
        cfg["_hold_records_error"] = f"{type(e).__name__}: {e}"
        return []


# F5 (FLOW-OPS-R2 11-22, FABLE-FLOW-0000: 274 S81 + 37 KV rows held with no term; NO-PROGRESS said "no blocker"): a hold_items entry carries its
# term in its text as `owner=<lane> eta=<YYYY-mm-dd[ HH:MM]>`.  Past its ETA it is HOLD-OVERDUE (owner + COORD); with no ETA it is HOLD-NO-TERM, and
# a current-plan row it keeps orphaned (CANCELLED / SUPERSEDED, no successor) for ORPHAN_HOLD_H hours is relaunched (the key is dropped in memory).
HOLD_OWNER_RE = re.compile(r"\bowner\s*[=:]\s*([A-Za-z0-9_.-]+)", re.I)
HOLD_ETA_RE = re.compile(r"\beta\s*[=:]\s*(\d{4}-\d\d-\d\d(?:[ T]\d\d:\d\d)?)", re.I)
ORPHAN_HOLD_H = 2.0


def hold_term(why):
    """(owner or '', eta epoch or None) from a hold_items text"""
    s = str(why or "")
    m, e = HOLD_OWNER_RE.search(s), HOLD_ETA_RE.search(s)
    eta = None
    if e:
        v = e.group(1).replace("T", " ")
        try:
            eta = time.mktime(time.strptime(v, "%Y-%m-%d %H:%M" if " " in v else "%Y-%m-%d"))
            if " " not in v:
                eta += 86399                     # a date-only ETA ends that day
        except ValueError:
            eta = None
    return (m.group(1) if m else ""), eta


def hold_term_findings(cfg, now=None):
    """-> {die: {'overdue': [(key, owner, eta)], 'noterm': [key], 'n': total}} for every enabled, unparked die with hold_items"""
    now = time.time() if now is None else now
    out = {}
    for die, d in (cfg.get("dies") or {}).items():
        if not isinstance(d, dict) or not d.get("enabled") or die_parked(d) or not isinstance(d.get("hold_items"), dict):
            continue
        f = {"overdue": [], "noterm": [], "n": len(d["hold_items"])}
        for key, why in d["hold_items"].items():
            owner, eta = hold_term(why)
            if eta is None:
                f["noterm"].append(key)
            elif eta < now:
                f["overdue"].append((key, owner or die_owner(cfg, die)[0], eta))
        out[die] = f
    return out


def hold_term_step(AP, cfg, st, now=None):
    """one HOLD-TERM line per die per hour; a COORD-REVIEW-QUEUE ALERT HOLD-OVERDUE (owner + COORD) when the overdue set changes"""
    now = time.time() if now is None else now
    found = hold_term_findings(cfg, now)
    for die, f in sorted(found.items()):
        if f["n"]:
            log_hourly(AP, st, f"HOLD-TERM|{die}", f"KIT-WAVE HOLD-TERM {die}: {f['n']} hold(s), {len(f['noterm'])} without owner/eta (HOLD-NO-TERM), "
                       f"{len(f['overdue'])} overdue" + (f": " + "; ".join(f"{k} [owner {o}] eta {time.strftime('%m-%d %H:%M', time.localtime(e))}" for k, o, e in f["overdue"][:5]) if f["overdue"] else ""), now=now)
    od = sorted((die, k, o) for die, f in found.items() for k, o, _e in f["overdue"])
    sig = hashlib.sha1(json.dumps(od).encode()).hexdigest()[:12] if od else ""
    if od and st.get("hold_overdue_sig") != sig:
        AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} ALERT [HOLD-OVERDUE -> " + ", ".join(sorted({o for _d, _k, o in od})) + ", COORD] holds past their ETA: "
                        + "; ".join(f"{d}/{k} [owner {o}]" for d, k, o in od[:20])[:1600] + " -- set a new eta= or delete the key (kit_wave_edit)")
    st["hold_overdue_sig"] = sig
    return found


def orphan_hold_release(cfg, st, now=None, hours=None):
    """F5: a hold_items key with no ETA that keeps a current-plan row orphaned -- CANCELLED (SUPERSEDED / QUEUE-CANCELLED / no class) for >= hours,
    no later attempt of the item -- is dropped in memory so the row relaunches on the current plan (owner rule: never start old-plan kits while
    a current-plan row waits).  A key with an eta= is the owner's kept hold and stays.  Die option orphan_hold_release false = off; parked dies
    are skipped.  -> [(die, key, items)]"""
    now = time.time() if now is None else now
    hours = ORPHAN_HOLD_H if hours is None else hours
    items = list((st.get("items") or {}).values())
    latest = {}
    for r in items:
        k = (r.get("die"), r.get("item"))
        latest[k] = max(latest.get(k, 0.0), float(r.get("started") or 0))
    out = []
    for die, d in (cfg.get("dies") or {}).items():
        if not isinstance(d, dict) or not d.get("enabled") or die_parked(d) or d.get("orphan_hold_release") is False \
                or cfg.get("orphan_hold_release") is False or not isinstance(d.get("hold_items"), dict) or not d.get("event"):
            continue
        orph = [r for r in items if r.get("die") == die and str(r.get("event") or "") == str(d["event"]) and r.get("status") == "CANCELLED"
                and str(r.get("class") or "") in ("SUPERSEDED", "QUEUE-CANCELLED", "") and now - float(r.get("updated") or 0) >= hours * 3600
                and float(r.get("started") or 0) >= latest.get((die, r.get("item")), 0.0)]
        for key in list(d["hold_items"]):
            if hold_term(d["hold_items"][key])[1] is not None:
                continue
            hit = sorted({str(r.get("item")) for r in orph if fnmatch.fnmatchcase(str(r.get("item") or ""), key)})
            if hit:
                del d["hold_items"][key]
                out.append((die, key, hit))
    if out:
        cfg.setdefault("_hold_auto_released", []).extend((die, key, f"F5 orphan relaunch: {len(hit)} current-plan row(s) cancelled > {hours:g} h, hold has no eta")
                                                       for die, key, hit in out)
    return out


def hold_audit_step(AP, cfg, st, t0):
    """HOLDGEN-1115 per-tick audit: held-but-launched, release terms that cannot be reached, holds whose plan sha is superseded,
    patterns that match nothing.  One log line every tick; a COORD-REVIEW-QUEUE ALERT when the finding set changes."""
    import hold_records as HR
    if cfg.get("_hold_records_error"):
        AP.log(f"KIT-WAVE HOLD-AUDIT compile error: {cfg['_hold_records_error']}")
    launched = [(r.get("die"), r.get("item")) for r in (st.get("items") or {}).values()
                if float(r.get("started") or 0) >= t0 and r.get("die") and r.get("item")]
    try:
        hold_term_step(AP, cfg, st)
    except Exception as _e:                           # advisory: never stops the audit
        AP.log(f"KIT-WAVE HOLD-TERM check failed: {type(_e).__name__}: {_e}")
    found = HR.audit(cfg, launched)
    summ = HR.summarize(found)
    AP.log("KIT-WAVE HOLD-AUDIT " + " ".join(f"{c}={summ.get(c, 0)}" for c in
           ("HELD-BUT-LAUNCHED", "HOLD-LEAK", "TERM-UNREACHABLE", "TERM-VARIANT", "HOLD-SUPERSEDED", "HOLD-ZERO-MATCH", "PROOF-HELD", "PILOT-DEADLOCK")))
    for f in found:                                  # H1 (WAVE-OPS-R1): launched rows a hold record names but hold_items does not carry -> a HOLD-LEAK line to the die owner
        if f["code"] == "HOLD-LEAK" and f["n"] > 0:
            _own = ((cfg.get("dies") or {}).get(f["die"]) or {}).get("owner_lane") or "die owner"
            _k = f"hold_leak_sig:{f['die']}:{f['id']}"
            if st.get(_k) != f["n"]:
                st[_k] = f["n"]
                AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} HOLD-LEAK [-> {_own}] {f['die']}/{f['id']}: {f['n']} launched row(s) match a hold record that blocks nothing on this die "
                                f"(stops_off): {f['detail']}; items {','.join(map(str, f['items'][:8]))}. Hold them with dies.{f['die']}.hold_items (kit_wave_edit refuses new records here).")
    # HOLD-FLOW-R 11-16 (FABLE-FLOW-2000): a held release term with no producer for 12 h is a wave alert line
    try:
        _ctx = hold_ctx(cfg)
        _seen = st.setdefault("hold_term_seen", {})
        _al = HR.term_alerts(cfg, _seen, hours=12.0, is_met=lambda term, die, rec: HR.term_met(term, rec, die, "", cfg, _ctx))
        if _al:
            AP.log("KIT-WAVE HOLD-TERMS no producer for 12 h: " + "; ".join(f"{a['die']}/{a['id']} {a['term'][:60]} ({a['why']})" for a in _al)[:1500])
            _sig2 = hashlib.sha1(json.dumps([(a["die"], a["id"], a["term"]) for a in _al]).encode()).hexdigest()[:12]
            if st.get("hold_term_alert_sig") != _sig2:
                st["hold_term_alert_sig"] = _sig2
                AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} ALERT [HOLD-FLOW-R -> COORD, WAVE-HOLDS-1115] hold terms with no producer for 12 h: "
                                + "; ".join(f"{a['die']}/{a['id']} {a['term'][:70]} x{a['n']} held: {a['why']}" for a in _al)[:1700])
        else:
            st.pop("hold_term_alert_sig", None)
    except Exception as _e:
        AP.log(f"KIT-WAVE HOLD-TERMS check failed: {type(_e).__name__}: {_e}")
    sig = hashlib.sha1(json.dumps([(f["code"], f["die"], f["id"], f["detail"], f["n"], sorted(map(str, f["items"]))[:50]) for f in found],
                                  default=str).encode()).hexdigest()[:12]
    if found and st.get("hold_audit_sig") != sig:
        st["hold_audit_sig"] = sig
        lines = [f"{f['code']} {f['die']}/{f['id']} x{f['n']}: {f['detail']}" + (f" items {','.join(map(str, f['items'][:6]))}" if f["items"] else "")
                 for f in found]
        AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} ALERT [HOLDGEN-1115 -> COORD, WAVE-HOLDS-1115] hold audit {summ}: " + "; ".join(lines)[:1800])
    elif not found:
        st.pop("hold_audit_sig", None)
    return found


def _hold_term_met(term, die_cfg, is_merged):
    """one typed release_on term -> True / False.  Auto-checkable types: event_adopt:<name> (the die's current event, or the
    plan_event or plan file name, carries <name> as a whole token; names of 1-2 characters, e.g. 'Event F', are not checkable), merge:<ref>
    (<ref> is an ancestor of origin/main).  lane_ready / lane_result / anything else is a human post: never auto-released."""
    kind, _, val = str(term).strip().partition(":")
    kind, val = kind.strip(), val.strip()
    if kind == "event_adopt":
        name = re.sub(r"^event\s+", "", val, flags=re.I).strip().lower()
        import hold_records as _HR
        if not _HR.event_name_ok(name):                  # r252: one trailing * = prefix (B6gG3* = B6gG3, B6gG3b)
            return False
        return _HR._event_token_in(name, _HR.released_events(die_cfg))
    if kind == "merge":
        ref = val.split()[0] if val else ""
        try:
            return bool(ref) and bool(is_merged(ref))
        except Exception:
            return False
    return False


def _git_is_merged(ref):
    here = os.path.dirname(os.path.abspath(__file__))
    return subprocess.run(["git", "-C", here, "merge-base", "--is-ancestor", ref, "origin/main"],
                          capture_output=True, timeout=20).returncode == 0


def apply_hold_release_on(cfg, is_merged=None):
    """HOLD-RELEASE-ON 11-15 (COORD r152): a die's hold_release_on maps a hold_items key to a typed release condition, 'term + term'
    (every term must be met).  When all terms are auto-checkable and met, the key is dropped from hold_items in memory (the file is
    not edited) and listed in cfg['_hold_auto_released'] as (die, key, release_on).  A key without an entry, an unknown type, or a
    lane_ready / lane_result term stays held."""
    is_merged = is_merged or _git_is_merged
    out = []
    for die, d in (cfg.get("dies") or {}).items():
        ro, hold = d.get("hold_release_on"), d.get("hold_items")
        if not isinstance(ro, dict) or not isinstance(hold, dict):
            continue
        for key, cond in list(ro.items()):
            if key not in hold:
                continue
            terms = [t for t in str(cond).split(" + ") if t.strip()]
            if terms and all(_hold_term_met(t, d, is_merged) for t in terms):
                del hold[key]
                out.append((die, key, str(cond)))
    if out:
        cfg["_hold_auto_released"] = out
    return out


def opt(cfg, die, key):
    """die value > global value > default"""
    d = (cfg.get("dies") or {}).get(die) or {}
    if key in d:
        return d[key]
    return cfg.get(key, DEFAULTS.get(key))


def place_mem_gb(cfg, die, item):
    """PLACE memory (GB) of one item: the first fnmatch pattern of place_mem_gb_by_item (die > global, in insertion
    order) that matches the item, else the die's place_mem_gb.  QC-TYPES-6 11-08: the hc tap-pair kits need >= 96 GB
    for their kit LEC (rc137 OOM at 32 and 48 GB) without raising every kit's budget."""
    x = float((cfg.get("_mem_x") or {}).get(f"{die}|{item}", 1.0))          # REPEAT-STOP: x1.5 after the first OOM kill of the item
    for pat, gb in (opt(cfg, die, "place_mem_gb_by_item") or {}).items():
        if fnmatch.fnmatchcase(str(item), pat):
            return int(gb * x)
    return int(opt(cfg, die, "place_mem_gb") * x)


def pick_charge_gb(cfg, die, item):
    """KIT-OPS-4 11-14 (ADMIT-TUNE-1: epyc8 / epyc10 filled to 39 waiters while epyc9 / epyc2 had 190-215 GB free): GB one new launch
    books on its picked gen host until ot-run reports it.  A launch queues PLACE (place_mem_gb) and its gen / bind / lint stages on
    that host, so the burst charge is the larger of the place memory and the gen + bind + lint peak, times pick_charge_factor
    (die > global option, default 1.5; 1 = old behaviour), so one tick's burst spreads once a host's headroom is used."""
    base = max(place_mem_gb(cfg, die, item),
               int(opt(cfg, die, "gen_mem_gb")) + int(opt(cfg, die, "bind_mem_gb")) + int(opt(cfg, die, "lint_mem_gb")))
    try:
        f = float(opt(cfg, die, "pick_charge_factor") or 1.5)
    except (TypeError, ValueError):
        f = 1.5
    return int(round(base * max(f, 1.0)))


HUB_DISK_PATHS = ("/srv/opentallas-scratch2", "/")


_HUB_STATVFS = os.statvfs            # tests replace this with a fixed host state (conftest), never the live disk


def hub_disk_low(cfg, paths=HUB_DISK_PATHS, statvfs=None):
    """FLOW-HEALTH-1 11-15 (FABLE-FLOW-1200 item 2): '' or why the hub cannot take new work.  A hub ENOSPC killed 28 units at once; the tick
    launches nothing while the hub's scratch2 or root has less than hub_free_min_gb (default 64) free.  Running units are untouched."""
    try:
        floor = float(cfg.get("hub_free_min_gb", 64))
    except (TypeError, ValueError):
        floor = 64.0
    if floor <= 0:
        return ""
    statvfs = statvfs or _HUB_STATVFS
    low = []
    for p in paths:
        try:
            s = statvfs(p)
        except OSError:
            continue                                         # a path this host does not have is not a reason
        free = s.f_bavail * s.f_frsize / 2**30
        if free < floor:
            low.append(f"{p} {free:.0f} GB free < {floor:g} GB")
    return "hub disk low: " + "; ".join(low) if low else ""


HUB_ALERT_TICKS = 2


def hub_top_writers(root="/srv/opentallas-scratch2/claude", n=5, run=None):
    """best effort: the n biggest directories directly under root (du, 40 s cap) as 'path GB, ...'"""
    try:
        p = (run or subprocess.run)(["timeout", "40", "du", "-sk", "--max-depth=1", root], capture_output=True, text=True, timeout=50)
        rows = sorted(((int(a), b) for a, b in (ln.split("\t", 1) for ln in p.stdout.splitlines() if "\t" in ln) if b.strip() != root), reverse=True)
        return ", ".join(f"{b.strip()} {a / 2**20:.0f} GB" for a, b in rows[:n]) or "unknown"
    except Exception:
        return "unknown"


def hub_launch_held(cfg, die, item):
    """'' or the hub-disk reason when this launch writes to the hub: every gen host of the item is the hub (build-host launches never wait on the hub floor)"""
    why = cfg.get("_hub_disk_low")
    if not why:
        return ""
    try:
        hosts = [h for h in gen_hosts(cfg, die, item)]
    except Exception:
        return why
    return why if all(h in ("localhost", "intel2", cfg.get("hub")) for h in hosts) else ""


def hub_disk_gate(AP, cfg, st, now=None):
    """called once per tick: sets cfg['_hub_disk_low'] and posts one STATE line when the condition starts (one more when it ends)"""
    why = hub_disk_low(cfg)
    cfg["_hub_disk_low"] = why
    g = st.setdefault("hub_disk", {})
    if why:
        g["ticks"] = int(g.get("ticks") or 0) + 1
        if g["ticks"] == HUB_ALERT_TICKS and not g.get("alerted") and not getattr(AP, "DRY", False):
            g["alerted"] = time.time()
            AP.log(f"KIT-WAVE HUB-DISK ALERT: hub floor held {g['ticks']} ticks: {why}")
            AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} ALERT [KIT-WAVE -> COORD, FLEET-OPS-R] hub disk floor held {g['ticks']} ticks: {why}. "
                            f"Hub writers only are held (launches whose gen host is the hub); build-host launches continue. Top hub writers: {hub_top_writers()}")
    if why and not g.get("since"):
        g["since"] = time.time() if now is None else now
        AP.log(f"KIT-WAVE HUB-DISK launch refused: {why}")
        AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} STATE [FLOW-HEALTH-1 -> COORD] kit wave launches nothing: {why} "
                        "(a hub ENOSPC killed 28 units on 11-15; running units untouched; free the hub disk, the next tick resumes)")
    elif not why and g.get("since"):
        AP.log("KIT-WAVE HUB-DISK launches resume: hub disk above the floor again")
        AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} STATE [FLOW-HEALTH-1 -> COORD] kit wave launches resume: hub disk above the floor again")
        g.clear()
    return why


def stop_reason(cfg, die, ap_dir=None):
    ap_dir = Path(ap_dir or AP_DIR)
    if cfg.get("error"):
        return cfg["error"]
    if (ap_dir / "kit_wave.stop").exists():
        return "global stop file kit_wave.stop"
    if not cfg.get("enabled"):
        return "wave disabled in kit_wave.json"
    if (ap_dir / f"kit_wave.{die}.stop").exists():
        return f"die stop file kit_wave.{die}.stop"
    d = (cfg.get("dies") or {}).get(die)
    if not d:
        return "no die config"
    if d.get("kill"):
        return f"die kill switch: {d['kill']}"
    return None


def die_parked(d):
    """F4 (FLOW-OPS-R2 11-22, FABLE-FLOW-0000): dies.<die>.parked = {owner, since, reason} (truthy) -> one-line text, else ''.  A parked die is
    skipped by the wave gate, the adopt guard, TOOLS-LAG and the STALE list; removing the key re-arms every check at once."""
    p = (d or {}).get("parked") if isinstance(d, dict) else None
    if not p:
        return ""
    if isinstance(p, dict):
        return "DIE-PARKED owner %s since %s: %s" % (p.get("owner") or "?", p.get("since") or "?", str(p.get("reason") or "")[:160])
    return "DIE-PARKED: %s" % str(p)[:160]


def gate(cfg, die, descends=None):
    """(ok, why).  descends(sha, base) -> bool (git merge-base --is-ancestor on the hub); None = exact match only"""
    d = (cfg.get("dies") or {}).get(die) or {}
    if die_parked(d):
        return False, die_parked(d)
    if not d.get("enabled"):
        return False, "die not enabled"
    if die in COORD_ONLY and not d.get("coord_enable"):
        return False, f"{die} stays OFF until COORD enables it (coord_enable)"
    ev = str(d.get("event") or "")
    rule = GATE_EVENTS.get(die)
    if rule is None and die not in COORD_ONLY:
        return False, f"no plan-of-record rule for {die}"
    if rule:
        # KW-FIX-45 11-11: the accepted event labels come from the die config too (die option gate_events_extra), so a
        # cut label such as hcut1111 does not need a code change; without the option the code list decides as before.
        if "exact" in rule and ev not in rule["exact"] and ev not in (d.get("gate_events_extra") or ()):
            return False, f"event '{ev}' is not a COORD plan of record ({'/'.join(rule['exact'])})"
        if "descends" in rule:
            base = rule["descends"]
            if not re.fullmatch(r"[0-9a-f]{7,40}", ev):
                return False, f"event '{ev}' is not a commit (needs {base} or newer)"
            if not (ev.startswith(base) or base.startswith(ev)):
                dres = descends(ev, base) if descends is not None else False
                if dres is None:
                    # r703/r704: an unresolvable ancestry never turns a die off; the applied event is current by definition (the apply wrote it), a WARN goes out once per tick (plan_dies)
                    d["_descend_warn"] = f"event {ev} is not in the repo mirror: ancestry from {base} unresolvable, treated as current"
                elif not dres:
                    if FG.stops_off_die(cfg, die):
                        d["_descend_warn"] = f"event {ev} does not descend from {base}: ignored under stops_off (r703)"
                    else:
                        return False, f"event {ev} does not descend from {base}"
    g = d.get("gate") or {}
    bad = [k for k in GATE_KEYS if str(g.get(k, "")).upper() != "PASS"]
    # COORD 11-19 (KV D25d applied 12:40, no D25d row for 5 h: "bind not PASS in the config", the apply wrote bind = 'POST-APPLY r712 ...'): under stops_off (r703, not hbm) the bind
    # gate key never blocks a die; the per-item bind preflight / BIND-STALE / bound-tree fallback decide per row
    if bad and "bind" in bad and FG.stops_off_die(cfg, die):
        bad = [k for k in bad if k != "bind"]
    d.pop("_cores_only", None)
    if bad == ["clock"] and d.get("types_before_die_clock"):
        # KW-FIX-32 11-07 (OWNER 17:4x "allow type builds for all dies, including HBM"): die option
        # types_before_die_clock true -> a die whose ONLY non-PASS plan gate is the die clock builds every kind (types
        # too), not just cores; g0c/bind must still PASS.  Default off = the 12.22 item 4 cores-only behaviour below.
        pass
    elif bad == ["clock"] and d.get("core_kit"):
        # AUTOBUILD-PIPE-2 (COORD 10-30 23:5x, owner 12.22 item 4): a hard core does not depend on the die clock (its
        # boundary is the plan pin table + common core latency), so a core-kit die builds its kind=core items before
        # the die clock PASSes; partition types still wait for it (select() skips them)
        d["_cores_only"] = True
    elif bad:
        return False, f"plan event {ev}: {'/'.join(bad)} not PASS in the config"
    for k in ("plan", "gen_host", "src"):
        if not d.get(k):
            return False, f"config lacks {k}"
    return True, f"plan of record {ev} ({g.get('evidence', 'no evidence ref')})"


# ------------------------------------------------------------------------------------------------ selection
OWN_COLS = ["die", "item", "kind", "state", "owner", "live_job", "last_activity", "next_step", "evidence",
            "default_owner", "replicas", "members"]


def parse_owners(text):
    rows = []
    for line in (text or "").splitlines():
        if not line.strip() or line.startswith("#") or line.startswith("die\t"):
            continue
        f = line.split("\t")
        f += [""] * (len(OWN_COLS) - len(f))
        rows.append(dict(zip(OWN_COLS, f)))
    return rows


def age_min(s):
    m = re.fullmatch(r"\s*(\d+(?:\.\d+)?)m\s*", s or "")
    return float(m.group(1)) if m else None


def minimal_profile():
    """OWNER 11-13 R-MINIMAL (PROFILE-1; default) vs OT_SIGNOFF_PROFILE=legacy.  Minimal: kit preflight, the visual verdict
    (route hold / WAIT-FORM / sign-off wait), no-blind-retry, unchanged_fail and FLOW-REPEAT are ADVISORY; a failed row gets
    ONE automatic retry (the generator's R-FLOW defaults) and then waits for a named owner (COORD retry / pending row)."""
    return os.environ.get("OT_SIGNOFF_PROFILE", "minimal").strip().lower() != "legacy"


MINIMAL_RETRY = "minimal_retry"       # state ledger {die|item: failed attempt that got the one automatic retry}


def minimal_auto_retry(state, die, ev, d, retry, plan_types=None, log=print, cfg=None):
    """R-MINIMAL one automatic retry: every FAILED wave row (design FAIL or queue FAIL; INFRA has its own resubmit) of this
    die whose item has not used its automatic retry joins the in-memory retry set; the ledger keeps the failed attempt, so a
    row still waiting to launch stays released and a second failure (a later attempt) waits for its owner.  -> new set"""
    if not minimal_profile():
        return retry
    led = state.setdefault(MINIMAL_RETRY, {})
    out = set(retry)
    # S81-COL-FLOW-1118 (COORD FABLE-FLOW-0600 class B): the die key auto_rearm is gone.  dies.s81.auto_rearm=false (WAVE-HOLDS-1115) kept 398 S81
    # FAIL rows from ever re-arming after their inputs changed (src f2s4/d7w -> d8t, restored view inputs, tool fixes).  A failed row re-arms whenever an
    # input changed since its attempt; an identical relaunch is still refused on the full input hash (fail key / SKIP-SAME-INPUT).
    if isinstance(d.get("src_sha"), str):       # WF-1 11-14: input-change re-arm
        try:
            cand = rearm_candidates(state, cfg or {}, die, d)
            out |= set(cand)
            kinds = {}
            for why in cand.values():
                for w in why:
                    kinds[w.split("+")[0]] = kinds.get(w.split("+")[0], 0) + 1
            sig = f"{len(cand)} " + " ".join(f"{k}={v}" for k, v in sorted(kinds.items()))
            if (state.setdefault("rearm_logged", {})).get(die, "0 ") != sig:       # one line per die and change, never per row
                state["rearm_logged"][die] = sig
                log(f"KW_REARM {die}: {len(cand)} failed attempt(s) with changed inputs since the attempt are re-armed without a "
                    f"retry key ({sig}); select() still applies holds, the plan block, the cap and the resume 'nochange' refusal")
        except Exception as ex:                      # a re-arm failure must never stop the wave
            log(f"KW_REARM {die} failed: {type(ex).__name__}: {ex}")
    for rec in (state.get("items") or {}).values():
        if rec.get("die") != die or not rec.get("item"):
            continue
        failed = rec.get("status") == "FAIL" or (rec.get("status") == "ENQUEUED" and rec.get("q_status") == "FAIL")
        cls = str((rec.get("q_class") if rec.get("q_status") == "FAIL" else "") or rec.get("class") or "")
        if not failed or cls == "INFRA":
            continue
        k, a = f"{die}|{rec['item']}", int(rec.get("attempt") or 0)
        rf = d.get("retry_fix") if isinstance(d.get("retry_fix"), dict) else {}
        used = [int(x.rsplit("@", 1)[1]) for x, why in rf.items() if x.rsplit("@", 1)[0] == rec["item"]
                and x.rsplit("@", 1)[-1].isdigit() and "R-MINIMAL auto retry" in str(why)]
        if led.get(k) is None and used and max(used) < a:
            led[k] = max(used)              # KIT-OPS-2 11-13 config retry (tagged) already was this item's automatic retry
        if led.get(k) is None:
            led[k] = a
            log(f"KW_MINIMAL_RETRY {die}/{rec['item']}@{a}: one automatic retry (R-MINIMAL; R-FLOW generator defaults)")
        if led.get(k) == a:
            out.add(f"{rec['item']}@{a}")
    return out


# WF-1 11-14 (OWNER "remove these process frictions"; EXPERT-REVIEW-6 #2, 66 % of a night's 249 FAILs had no design content):
# every FAIL / queue-FAIL / CANCELLED-HUNG / WAIT-FORM row re-arms by itself when an input of the die changed since THAT attempt:
# the die src_sha, the source content hash (src overlay), the kit-tool digest of this rt tree, or a host added to the die's host
# list.  No retry key.  The kit_resume 'nochange' refusal still stops an identical relaunch; INFRA (own resubmit), the die's
# hold_items, the RETRY_CAP block and the plan-block filter are unchanged and still apply in select().
REARM_LED = "rearm_tools"             # state ledger {die|item: {"a": attempt, "tools": digest at first sight}}
REARM_CLASSES = ("HUNG", "WAIT-FORM", "HELD-STOP")
# S81-COL-FLOW-1118: a row COORD cancelled for an infrastructure cause (retire infra-src: dies.s81 src pointed at a lane run copy;
# infra-clean: gen tree hollowed by a cleanup) or one stopped while a hold stood (HELD-STOP) has no design verdict either.  Their
# block is unchanged on the new tree, so before this they stayed CANCELLED for good (seqhost__t1, ot_s81sl_leaf__t65, ...).
REARM_RETIRE = ("infra-src", "infra-clean")
_TOOLS_DIGEST = {}


def rt_tools_digest():
    """CONTENT digest (path relative to the tree, sha1 of the bytes) of the kit tools of THIS tools tree: tools/die_plan,
    physical/common_flow and the kit_*.py files of tools/autopilot (not kit_wave.py itself nor the scheduler: those never
    change a kit).  MERGE-QUEUE-1 11-14: content, not absolute path + mtime: the wave runs the pinned tree rt/<sha>
    (ot-tools-sync flips rt/current after each main push), so a new version dir whose kit tools are byte-identical must not
    re-arm every failed row (rearm reason rt_tools) nor reset the retry counters (input_digest)"""
    if "v" in _TOOLS_DIGEST:
        return _TOOLS_DIGEST["v"]
    root = Path(__file__).resolve().parents[2]
    h = hashlib.sha1()
    for rel in ("tools/die_plan", "physical/common_flow", "tools/autopilot"):
        base = root / rel
        for dp, dn, fn in os.walk(base):
            dn[:] = sorted(x for x in dn if x not in (".git", "__pycache__"))
            for f in sorted(fn):
                if f.endswith((".pyc", ".orig")) or ".bak" in f:
                    continue
                if rel == "tools/autopilot" and (dp != str(base) or not f.startswith("kit_") or f == "kit_wave.py"):
                    continue
                p = os.path.join(dp, f)
                try:
                    with open(p, "rb") as fh:
                        data = fh.read()
                except OSError:
                    continue
                h.update(f"{os.path.relpath(p, root)}\0{len(data)}\0".encode())
                h.update(hashlib.sha1(data).digest())
    _TOOLS_DIGEST["v"] = h.hexdigest()
    return _TOOLS_DIGEST["v"]


def rearm_changes(state, cfg, die, d, rec):
    """what changed for this failed attempt since it was generated: [] (nothing) or reasons ['src_sha', 'src_overlay', 'rt_tools',
    'hosts+h'].  Compared against the attempt's own spec.json (src_sha, src_overlay, hosts) and the tools digest seen at the
    first tick after the failure (the ledger)."""
    out = []
    # WF-1 11-14: a unit killed from outside (earlyoom / signal 15 / ot-run NOT COMPLETED: class INFRA, reason names the kill) has no
    # design content and the infra budget (infra_attempts) may already be spent by earlier kills: it is re-armed every time
    if str(rec.get("class") or "") == "INFRA" and re.search(r"process terminated|interrupted \(signal|NOT COMPLETED|cancellation requested|"
                                                             r"unit stopped from outside", str(rec.get("reason") or "")):
        out.append("infra_kill")
    try:
        sp = json.loads((Path(rec["dir"]) / "spec.json").read_text())
    except (OSError, ValueError, KeyError, TypeError):
        sp = {}
    if sp.get("src_sha") and d.get("src_sha") and sp["src_sha"] != d["src_sha"]:
        out.append("src_sha")
    if sp.get("src_overlay") and d.get("_src_overlay") and sp["src_overlay"] != d["_src_overlay"]:
        out.append("src_overlay")
    if die_env_stale(d, rec.get("item"), sp):           # WAVE-RECIPE-1 FIX 5: a die flow default changed since the attempt
        out.append("die_gen_env")
    added = sorted(set(opt(cfg, die, "hosts") or []) - set(sp.get("hosts") or [])) if sp.get("hosts") else []
    if added:
        out.append("hosts+" + ",".join(added))
    led = state.setdefault(REARM_LED, {})
    k, a = f"{die}|{rec.get('item')}", int(rec.get("attempt") or 0)
    pin = item_gen_tools_manifest(d, rec.get("item"))
    if sp and (sp.get("gen_tools_manifest_sha") or "") != pin:
        out.append("generator_source")
    if pin and tools_group(rec.get("stage")):
        cur = pin
    else:
        cur = stage_tools_digest()
    seen = led.get(k)
    if not isinstance(seen, dict) or seen.get("a") != a:
        led[k] = {"a": a, "tools": cur}
    elif seen.get("tools") != cur:
        out.append("rt_tools")
    return out


def die_env_stale(d, item, sp):
    """WAVE-RECIPE-1 11-14 (FIX 5): the die_gen_env keys whose value in the attempt's spec differs from the die default now
    (keys the item's own item_env sets are the item's, never stale) -> sorted list, [] = current"""
    if not isinstance(sp, dict) or not isinstance(sp.get("gen_env"), dict):
        return []
    own = (item_env_entry(d, item)) if isinstance(d, dict) else {}
    ge = sp["gen_env"]
    return sorted(k for k, v in ((d.get("die_gen_env") or {}) if isinstance(d, dict) else {}).items()
                  if k not in own and str(ge.get(k)) != str(v))


def flow_regen(AP, cfg, st, notices):
    """WAVE-RECIPE-1 11-14 (FABLE-WAVE-REVIEW FIX 5, COORD-approved: kits still carry gates the owner deleted -- hold stop 28,
    repair time cap 12 -- and miss today's die flow defaults): a RUNNING attempt of the current event whose kit is STALE (a
    die_gen_env default changed since its spec, or the die src_sha moved on) and whose work has not started (its ot-run stage
    never admitted, no PLACE progress) is stopped by its exact unit names and relaunched this tick as a fresh kit (RETRY-INFRA,
    no attempt charged), like an unstarted RESTAGE.  An admitted / running stage is never touched; kits past place keep
    their run (FIX 2's kill_pin / resume handles those).  Option flow_regen (die > global) false = off;
    flow_regen_max_per_tick (default 400).  -> rows regenerated"""
    cap, n = int(cfg.get("flow_regen_max_per_tick", 400)), 0
    for die, d in sorted((cfg.get("dies") or {}).items()):
        if not isinstance(d, dict) or not d.get("enabled") or opt_get(cfg, die, "flow_regen") is False:
            continue
        if stop_reason(cfg, die, cfg.get("_ap_dir")):
            continue
        for r in (st.get("items") or {}).values():
            if n >= cap:
                return n
            if (r.get("die") != die or r.get("status") != "RUNNING" or not r.get("unit") or r.get("arm")
                    or r.get("event") != d.get("event")):
                continue
            try:
                sp = json.loads((Path(r["dir"]) / "spec.json").read_text())
            except (OSError, ValueError, KeyError, TypeError):
                continue
            why = die_env_stale(d, r.get("item"), sp)
            if sp.get("src_sha") and d.get("src_sha") and sp["src_sha"] != d["src_sha"] and not sp.get("kill_pin"):
                why = why + [f"src_sha {str(sp['src_sha'])[:10]}->{str(d['src_sha'])[:10]}"]
            if not why or volume_started(r) or heavy_progress(r):
                continue
            if any(fnmatch.fnmatchcase(r.get("item", ""), pat) for pat in (d.get("hold_items") or {})) \
                    or counted_now(cfg, st, die, r.get("item"), r.get("block_sha")):
                continue                                 # held / counted rows are never stopped here (no relaunch would follow)
            if not AP.DRY:
                AP.sh(["systemctl", "--user", "stop", r["unit"]], timeout=180)
                try:
                    svc = json.loads((Path(r["dir"]) / "place_service.json").read_text())
                    AP.sh(["systemctl", "--user", "stop", svc["unit"]], timeout=180)
                except (OSError, ValueError, KeyError):
                    pass
            r["infra_base"] = int(r.get("infra_base") or 0) + max(1, infra_used(r) - infra_attempts(cfg, die) + 1)
            r.update(status="RETRY-INFRA", **{"class": "INFRA"}, updated=time.time(), no_host_at=0,
                     reason=f"FLOW-REGEN: unstarted stale kit ({', '.join(why)[:200]}) relaunched on the current die flow (WAVE-RECIPE-1 FIX 5)")
            notices.setdefault(die, []).append(f"{r['item']} FLOW-REGEN (stale: {', '.join(why)[:120]})")
            AP.log(f"KIT-WAVE FLOW-REGEN {die}/{r['item']}@{r.get('attempt')} unit {r['unit']}: {', '.join(why)[:200]}")
            n += 1
    return n


def rearm_failed(rec):
    """a row that ended without a verdict worth waiting on: FAIL, queue FAIL, CANCELLED-HUNG / WAIT-FORM / HELD-STOP, or
    CANCELLED with an infrastructure retire mark"""
    if rec.get("status") == "FAIL" or (rec.get("status") == "ENQUEUED" and rec.get("q_status") == "FAIL"):
        return True
    return rec.get("status") == "CANCELLED" and (str(rec.get("class") or "") in REARM_CLASSES
                                                or str(rec.get("retire") or "") in REARM_RETIRE)


def rearm_candidates(state, cfg, die, d, log=None):
    """{'item@attempt': [reasons]} of the die's failed rows whose inputs changed since that attempt"""
    out = {}
    for rec in (state.get("items") or {}).values():
        if rec.get("die") != die or not rec.get("item") or not rearm_failed(rec):
            continue
        why = rearm_changes(state, cfg, die, d, rec)
        if why:
            out[f"{rec['item']}@{int(rec.get('attempt') or 0)}"] = why
    return out


# FLOW-FIX-2045: the flow scripts the wave puts into every kit from rt/current at launch, because a kit copies them at gen time from the die's PINNED snapshot (older than the fixes: the old STAGE-CAP
# watcher, the run_kit.sh whose goal finish skipped the FF GRT step).  (where, name, source): where = "kit" (<kit>/<name>) or "runner" (<work>/gen/<name>, the generated run_kit.sh);
# source = a path under rt/current/tools (verbatim copy) or "gen_phys.RUN_KIT" (the generated runner text).  kit_flow_refresh.py (TOOLS-DECOUPLE) keeps handling the other verbatim kit scripts.
RT_CURRENT = "/srv/opentallas-scratch2/claude/rt/current"       # FLOW-FIX-2045: where the stage refresh takes the flow scripts from (never the launch-pinned tree)
FLOW_REFRESH_FILES = (
    ("kit", "stage_odb_cap.py", "die_plan/stage_odb_cap.py"),
    ("kit", "tt_setup_repair.tcl", "die_plan/tt_setup_repair.tcl"),                          # lever 8: stall / wall-time bound of the TT setup repair
    ("kit", "hold_cap.tcl", "../physical/die_plan/hbm_arch_cores/hold_cap.tcl"),             # lever 8: the same bound for the in-flow repair_timing_helper
    ("runner", "run_kit.sh", "gen_phys.RUN_KIT"),
)
_RUN_KIT_TEXT = {}


def _flow_source_bytes(src):
    here = Path(__file__).resolve()
    if src == "gen_phys.RUN_KIT":
        if "t" not in _RUN_KIT_TEXT:
            import importlib.util as _iu
            dd = here.parents[1] / "die_plan"
            if str(dd) not in sys.path:
                sys.path.insert(0, str(dd))
            spec = _iu.spec_from_file_location("gen_phys", str(dd / "gen_phys.py"))
            mod = sys.modules.get("gen_phys") or _iu.module_from_spec(spec)
            if "gen_phys" not in sys.modules:
                spec.loader.exec_module(mod)
            _RUN_KIT_TEXT["t"] = mod.RUN_KIT
        return _RUN_KIT_TEXT["t"].encode()
    return (here.parents[1] / src).read_bytes()


FLOW_REFRESH_CMD_MAX = 100000      # one argv string: MAX_ARG_STRLEN 131,072 less the bash -c quoting and the ssh options


def flow_files_refresh_cmd(kit, work=None, files=None):
    """FLOW-FIX-2045: ONE shell command that refreshes every FLOW_REFRESH_FILES entry already present in the kit (kit) or beside it (runner: <work>/gen/<name>) from the runtime tools.  Content travels
    in the command (the host needs no matching rt path).  Copy to <file>.new, keep the mode, then mv: a new inode, so a shell or watcher already running the old file keeps it.  A missing target
    is never created; an identical file is left alone."""
    import base64, gzip
    parts = []
    for where, name, src in (files if files is not None else FLOW_REFRESH_FILES):
        if where == "runner" and not work:
            continue
        try:
            # FAIL-CLASS a2e8efcde6 (11-21): the whole command is ONE ssh argument (remote()), and one argument is capped at 131,072 bytes by the kernel.  Plain base64 of the
            # three files was 128,527 chars before the kit path: every launch with a real kit path died with OSError Errno 7.  gzip first (about 4x smaller); mtime 0 keeps the command stable.
            b64 = base64.b64encode(gzip.compress(_flow_source_bytes(src), 9, mtime=0)).decode()
        except Exception:
            continue
        k = shlex.quote((str(kit) if where == "kit" else str(work) + "/gen") + "/" + name)
        parts.append(f"if [ -f {k} ]; then echo {b64} | base64 -d | gzip -dc > {k}.new && [ -s {k}.new ] && {{ cmp -s {k}.new {k} || {{ chmod --reference={k} {k}.new && mv -f {k}.new {k}; }}; }}; rm -f {k}.new; fi")
    cmd = "; ".join(parts) or "true"
    if len(cmd) > FLOW_REFRESH_CMD_MAX:
        raise RuntimeError(f"flow_files_refresh_cmd: command is {len(cmd)} chars, over {FLOW_REFRESH_CMD_MAX} (one ssh argument holds 131,072 bytes): split FLOW_REFRESH_FILES or send it on stdin")
    return cmd


def stage_cap_refresh_cmd(kit):
    return flow_files_refresh_cmd(kit, None, [x for x in FLOW_REFRESH_FILES if x[0] == "kit"])


LOG_HOURLY_S = 3600


def log_hourly(AP, st, key, msg, now=None):
    """FLOW-FIX-2045 (FABLE-FLOW-1949 class 6): one line per key per hour for lines the wave repeats every tick while nothing changed (REPEAT, SKIP-SAME-INPUT, TOOL-SKEW).  The key names what the
    line is about (die / item / kind); a changed message under the same key still waits for the hour, the count of lines held back is added to the next one.  -> True when the line was written"""
    now = time.time() if now is None else now
    seen = st.setdefault("log_hourly", {}) if isinstance(st, dict) else {}
    ent = seen.get(key) or {}
    if ent and now - float(ent.get("t") or 0) < LOG_HOURLY_S:
        ent["n"] = int(ent.get("n") or 0) + 1
        seen[key] = ent
        return False
    held = int(ent.get("n") or 0)
    seen[key] = {"t": now, "n": 0}
    if len(seen) > 4000:
        for k in [k for k, v in seen.items() if now - float(v.get("t") or 0) > 2 * LOG_HOURLY_S]:
            seen.pop(k, None)
    AP.log(msg + (f" [+{held} identical line(s) in the last hour]" if held else ""))
    return True


def item_key(die, event, item, block=None):
    """OWNER 12.20 (plans hard-frozen): a kit is keyed on its plan block sha, so a new event with the same
    block reuses the record (no regeneration); only a changed block makes a new wave item"""
    return f"{die}|{item}|b{block[:12]}" if block else f"{die}|{event}|{item}"


