def prov_on(d):
    """KW-PROV-1 (COORD 11-03 17:50 (C)): die option prov_view, default ON on every die; false = the old WAIT-DEP wait"""
    return (d or {}).get("prov_view", True) is not False


def prov_item(d, item):
    """True when this item launches on PROVISIONAL child views (planned / noview flag and prov_view on)"""
    f = (d.get("_plan_flags") or {}).get(item)
    return prov_on(d) and (f == "noview" or (f == "planned" and not d.get("planned_core_flat")))


KIT_RTL_POST_DIR = Path(__file__).resolve().parent / "kit_rtl_post.d"


def kit_rtl_post_cmd(T, W, plan, steps_dir=None):
    """HARD-S81-SVC-1 / SVC-BAND-3 11-13: shell suffix of the kit_rtl stage in kit_rtl mode "bind" (cwd = wave source
    checkout).  Every tools/autopilot/kit_rtl_post.d/*.sh of the RUNNING kit_wave.py is inlined (bash -c <text>) and
    run on the kit RTL dir just written; each step selects itself from the kit content and leaves any other kit
    untouched (exit 0).  Class: the steps used to be looked up in the wave SOURCE and skipped when absent, so a frozen
    source that predates a step (S81 7073a6b4a5 vs the svc memory closure 3856aafc01) silently lost it and all 16 svc
    types failed GEN_LINT memory_bits.  A step the kit needs must depend neither on the kit_rtl mode nor on the age of
    the wave source.  No step file next to kit_wave.py = broken deployment: the stage fails, never passes silently."""
    q = shlex.quote
    d = Path(steps_dir) if steps_dir else KIT_RTL_POST_DIR
    steps = sorted(d.glob("*.sh")) if d.is_dir() else []
    if not steps:
        return " && { echo " + q(f"KIT_RTL_POST: no step in {d} (kit_wave.py deployment incomplete)") + " >&2; false; }"
    env = f"TYPE={q(T)} OUT={q(W + '/rtl')} PLAN={q(plan)}"
    return "".join(f" && {env} bash -c {q(p.read_text())} {q('kit_rtl_post.d/' + p.name)}" for p in steps)


def kit_rtl_closure_cmd(W, src, mode="inputs", chain=True, guard=False):
    """Run the current closure tool on the actual stage host (pinned generator stays immutable)."""
    code = (Path(__file__).resolve().parent / "kit_rtl_closure.py").read_text()
    return ((" && " if chain else "") + f"python3 - {shlex.quote(W)}/rtl --source {shlex.quote(src)} --mode {mode} <<'KW_CLOSURE_EOF'"
            + (" || exit $?" if guard else "") + "\n" + code + "\nKW_CLOSURE_EOF\n")


def kit_rtl_mode(d):
    """the die's kit-RTL mode (bind / script): the type kit takes the bound partition RTL; None = plan wrapper"""
    kr = d.get("kit_rtl") if isinstance(d.get("kit_rtl"), dict) else {}
    return kr.get("mode") if kr.get("mode") in ("bind", "script") else None


NEEDS_BIND = ("NEEDS-BIND: plan type has buses with no leaf binding and the die has no kit_rtl (bound partition RTL); "
              "gen would fail 'bus ... is not bound to any leaf port'")


def cell_big_note(AP, cfg, st):
    """one CELL-BIG log line per die and set of types per tick-change: plan types estimated over the 400k cell limit that stops_off lets through"""
    seen = st.setdefault("cell_big_logged", {})
    for die, d in (cfg.get("dies") or {}).items():
        if not isinstance(d, dict) or not d.get("_stops_off"):
            continue
        big = sorted(t for t, f in (d.get("_plan_flags") or {}).items() if f == "split")
        sig = ",".join(big)
        if big and seen.get(die) != sig:
            seen[die] = sig
            AP.log(f"KIT-WAVE CELL-BIG {die}: {len(big)} type(s) estimated over the {SPLIT_CELLS} cell limit launch anyway (stops_off): {', '.join(big)[:400]}")
        elif not big:
            seen.pop(die, None)


# FLOW-OPS-0900 11-21 (COORD ruling: CELL-CAP is a report, r703): the floorplan CELL-CAP report of a kit (native_cell_cap.tcl "OT_CELL_CAP REPORT" in the stage live
# log while the kit runs, or the worker's KW_CELL_CAP_REPORT line in unit.log after place) is posted ONCE per die|type to the owning lane and the die plan lane:
# the type must be split.  Live logs are read incrementally (byte offset per row), so a tick reads only what was appended.
CELL_CAP_PLAN_LANES = {"s81": "S81-J6-ASSEMBLY-R4", "qwen_compute": "QC-PLAN-R10", "qwen_kvsys": "KV-PLAN-R3"}   # die option cell_cap_plan_lane overrides
CELL_CAP_RE = re.compile(r"OT_CELL_CAP REPORT stage=floorplan: ([^\n]{0,300})|KW_CELL_CAP_REPORT \S+ (\{[^\n]{0,600}\})")
CELL_CAP_READ_MAX = 4 << 20


def cell_cap_plan_lane(cfg, die):
    d = (cfg.get("dies") or {}).get(die) or {}
    return str(d.get("cell_cap_plan_lane") or CELL_CAP_PLAN_LANES.get(die) or f"{die} plan owner")


def _cell_cap_scan(path, off):
    """-> (new offset, cause text or '') reading path from byte off (at most CELL_CAP_READ_MAX per call)"""
    try:
        with open(path, "rb") as f:
            f.seek(0, os.SEEK_END)
            end = f.tell()
            if end < off:
                off = 0                                  # rewritten log
            f.seek(off)
            data = f.read(CELL_CAP_READ_MAX).decode("utf-8", "replace")
            new = off + len(data.encode("utf-8", "replace"))
    except OSError:
        return off, ""
    m = CELL_CAP_RE.search(data)
    if not m:
        return new, ""
    if m.group(1):
        return new, m.group(1).strip()
    try:
        return new, str(json.loads(m.group(2)).get("why") or "over the cell cap")
    except ValueError:
        return new, "over the cell cap"


def cell_cap_report_step(AP, cfg, st, now=None):
    """one CELL-CAP post per die|type (state cell_cap_reports); -> number of posts this tick"""
    now = time.time() if now is None else now
    seen = st.setdefault("cell_cap_reports", {})
    offs = st.setdefault("cell_cap_offsets", {})
    n = 0
    for key, rec in (st.get("items") or {}).items():
        tk = f"{rec.get('die')}|{rec.get('item')}"
        if tk in seen:
            continue
        if rec.get("status") != "RUNNING" and now - float(rec.get("updated") or 0) > 3 * 3600:
            offs.pop(key, None)
            continue
        jd = Path(str(rec.get("dir") or ""))
        o = offs.setdefault(key, {})
        why = ""
        for nm in ("unit.log", f"{rec.get('stage') or 'place'}.live.log", "place.live.log"):
            o[nm], w = _cell_cap_scan(jd / nm, int(o.get(nm) or 0))
            why = why or w
        if not why:
            continue
        die, item = rec.get("die"), rec.get("item")
        owner = die_owner(cfg, die, item=item)[0]
        plan = cell_cap_plan_lane(cfg, die)
        seen[tk] = {"ts": now, "attempt": rec.get("attempt"), "event": rec.get("event"), "why": why[:300], "owner": owner, "plan_lane": plan}
        offs.pop(key, None)
        AP.log(f"KIT-WAVE CELL-CAP {die}/{item}@{rec.get('attempt')} ({rec.get('event')}): {why[:200]} -> posted to {owner}, {plan}")
        if not AP.DRY:
            AP.coord_append("lanes/posts/KIT-WAVE.md",
                            f"- {now_s()} CELL-CAP [KIT-WAVE -> {owner}; cc {plan}] {die}/{item}@{rec.get('attempt')} on {rec.get('event')}: floorplan count {why[:220]}. "
                            f"The type must be split (OpenROAD closes <= ~400k cells per run, largest closed 517k); report only, the kit keeps running (r703). "
                            f"One post per type; unit {rec.get('unit')}")
        n += 1
    for k in [k for k in offs if k not in (st.get("items") or {})]:
        offs.pop(k, None)
    return n


def plan_entry_block(d, item, kind=None):
    """plan-entry kit preflight from the plan probe flags; hard_wrappers opt a hard type back in"""
    if item in (d.get("_identity_holds") or {}):
        return "plan block identity held: " + d["_identity_holds"][item]
    f = (d.get("_plan_flags") or {}).get(item)
    # DIE-HBM-89-TGEN 11-07 (HBM q_b000/q_b001 + __physical_v1 FAIL @gen 19:0x): a type kit without kit_rtl is the
    # plan wrapper, which binds a bus only via buses[].leaf / contents[].bind.  A type with unbound buses fails gen
    # with certainty, so it is not launched (no FAIL row, no gen slot) until the die config gives it bound RTL
    # (kit_rtl mode bind/script).  Die opt-out: unbound_launch true (old behaviour).  kind=core items (core_kit) and
    # hard types never go through the plan wrapper.
    ub = (d.get("_plan_unbound") or {}).get(item)
    if ub and kind != "core" and f != "hard" and not kit_rtl_mode(d) and not d.get("unbound_launch"):
        return f"{NEEDS_BIND} ({len(ub)} bus(es), e.g. {','.join(ub[:3])})"
    if f == "hard" and item in (d.get("hard_wrappers") or []):
        return None
    if f == "planned" and d.get("planned_core_flat"):
        return None
    if prov_item(d, item):
        return None                 # KW-PROV-1: builds on provisional child views (never counted until re-signed)
    if f == "split" and d.get("_stops_off"):
        return None                      # WAVE-PILOT-FIX 11-18 (r703): stops_off: est. cells over 400k is a CELL-BIG note (see cell_big_note), never a SPLIT-NEEDED launch block
    if PLAN_BLOCK.get(f):
        return PLAN_BLOCK[f]
    li = (d.get("_lint") or {}).get(item)
    # OWNER 11-03 07:0x: the gen-time lint is an ADVISORY report; it never blocks a launch.  The only blocking case,
    # a missing planned core view, is the probe's planned/noview flag above (WAIT-DEP).  die prelint_block true opts
    # a die back into blocking on lint hits (default off).
    if li and d.get("prelint", True) is not False and d.get("prelint_block"):
        return lint_reason(li)
    return None


# ------------------------------------------------------------------------------------------------ KW-FIX-4 gen-time lint
# OWNER 11-03 (COORD 06:11 RE-FORM template, GEN rules): before any kit launches, a lint fails the type on
#   cells   estimated flat std cells > 400k = SPLIT-NEEDED (plan probe, blocks the launch; die_plan/cell_cap.py);
#   memory  a memory over SYNTH_MEMORY_MAX_BITS that is not a macro (the type's GEN_LINT memory_bits verdict on this
#           same plan block; a block change, or a retry row whose fix is named in retry_fix, clears it);
#   view    a planned hard core without a signed view (probe flags planned / noview: these already wait as WAIT-DEP);
#   strap   leaked strap ports (strap_* type ports not declared id_straps/count_straps, duplicate declared names, or the
#           type's gen verdict 'undeclared top-level ID' / 'straps: duplicate names' on this same block).
# OWNER 11-03 07:0x: ADVISORY. A hit is reported as one LINT row (stage prelint, status LINT-ADVISORY) in
# kit_wave_stages.tsv and in the skip-free launch path; it never blocks a launch except a missing planned core view
# (planned/noview flags = WAIT-DEP).  dies.<die>.prelint false: no report; dies.<die>.prelint_block true: block.
PRELINT_HISTORY = (
    ("memory", re.compile(r"memory_bits|SYNTH_MEMORY_MAX_BITS"),
     "memory over SYNTH_MEMORY_MAX_BITS is not a macro (GEN_LINT memory_bits on this block): make it a generated memory macro"),
    ("strap", re.compile(r"undeclared top-level ID|straps: duplicate names"),
     "leaked / duplicate strap ports (gen verdict on this block): declare them in the plan (parent_id_straps)"),
)


COUNT_CACHE = Path.home() / ".local/state/fleet-viz/release_tree_plan_cache.json"
_COUNT_SIGNED = {}


def count_signed_modules(d, die):
    """KW-FIX-35-V 11-08 (COORD: the prelint and the count drifted): the child modules the RELEASE COUNT has signed
    for this die -- the same record source the count uses (release_tree_plan cache: plans[*].signed_cores, matched by
    module name like the counter).  None when the cache is unreadable (no claim either way).  Die option count_cache
    overrides the path."""
    path = Path(d.get("count_cache") or COUNT_CACHE)
    try:
        mt = path.stat().st_mtime
    except OSError:
        return None
    hit = _COUNT_SIGNED.get(str(path))
    if not hit or hit[0] != mt:
        try:
            c = json.loads(path.read_text())
        except (OSError, ValueError):
            return None
        by = {}
        for k, p in (c.get("plans") or {}).items():
            if not isinstance(p, dict):
                continue
            dn = p.get("die") or str(k).split("/", 1)[0]
            for m, recs in (p.get("signed_cores") or {}).items():
                if recs:                     # the count lists only signed records per module
                    by.setdefault(dn, set()).add(m)
        hit = _COUNT_SIGNED[str(path)] = (mt, by)
    return hit[1].get(die, set())


def has_counted_view(d, m):
    """a prov_view_sources candidate of m (die config or the auto-views overlay) is the counted signed view"""
    v = (d.get("prov_view_sources") or {}).get(m)
    return any(prov_counted(c) for c in (v if isinstance(v, list) else [v] if v else []) if isinstance(c, dict))


def count_noview(d, counted):
    """KW-FIX-35-CV 11-08: sorted child modules that prelint reports SIGNED IN COUNT BUT NO WAVE VIEW (children of the
    WAIT types -- same flag rule as prelint -- signed in the count with no counted view in prov_view_sources)"""
    if not counted:
        return []
    out = set()
    for t, f in (d.get("_plan_flags") or {}).items():
        if f in ("planned", "noview") and not (f == "planned" and d.get("planned_core_flat")):
            out |= {m for m in (d.get("_plan_deps") or {}).get(t, []) if m in counted and not has_counted_view(d, m)}
    return sorted(out)


# KW-FIX-35-CV 11-08 (DIE-HBM-92 10:2x: types built on PROVISIONAL child views although every child was signed in the
# count; counted_child_views.py was manual, and its --apply wrote the hub's kit_wave.json, which the tick does not read).
