# KW-FIX-44 11-10 (COORD): src_sha does not name a wave source once files are overlaid in place (LEF overrides, flow tools,
# RTL: 6-16 files per die on 11-10), so unchanged_fail saw "no input change" for a row whose input had changed.  The spec
# now carries a content hash of the parts of the source a kit reads; a real overlay changes it, a re-copy does not.
SRC_OVERLAY_SCOPE = ("tools", "rtl", "physical/die_plan", "physical/common_flow")
SRC_OVERLAY_SCRIPT = r"""
import hashlib, os, sys
H = hashlib.sha256()
for r in %r:
    for dp, dn, fn in os.walk(r):
        dn[:] = sorted(d for d in dn if d not in (".git", "__pycache__"))
        for f in sorted(fn):
            p = os.path.join(dp, f)
            if f.endswith(".pyc") or ".bak" in f or os.path.islink(p) or os.stat(p).st_size > 16 << 20:
                continue
            H.update(p.encode() + b"\0")
            with open(p, "rb") as x:
                H.update(hashlib.sha1(x.read()).digest())
print(H.hexdigest())
""" % (SRC_OVERLAY_SCOPE,)


SRC_OVERLAY_SIG_SCRIPT = r"""
import os, sys
n = 0; m = 0; z = 0
for r in %r:
    for dp, dn, fn in os.walk(r):
        dn[:] = [d for d in dn if d not in (".git", "__pycache__")]
        for f in fn:
            p = os.path.join(dp, f)
            try:
                st = os.lstat(p)
            except OSError:
                continue
            n += 1; z += st.st_size
            if st.st_mtime_ns > m: m = st.st_mtime_ns
print("%%d:%%d:%%d" %% (n, m, z))
""" % (SRC_OVERLAY_SCOPE,)
SRC_OVERLAY_CACHE = {}                 # (host, src) -> (signature, hash); persisted in OVERLAY_CACHE_FILE (a tick is a new process)
OVERLAY_CACHE_FILE = os.environ.get("KW_OVERLAY_CACHE") or os.path.expanduser("~/coord/autopilot/kit_wave_overlay_cache.json")
_OVL_LOADED = [False]


def _overlay_cache_load():
    if _OVL_LOADED[0]:
        return
    _OVL_LOADED[0] = True
    try:
        for k, v in json.loads(open(OVERLAY_CACHE_FILE).read()).items():
            h, _, src = k.partition("|")
            SRC_OVERLAY_CACHE.setdefault((h, src), (v[0], v[1]))
    except (OSError, ValueError, IndexError, TypeError):
        pass


import threading as _thr_ovl
_OVL_LOCK = _thr_ovl.Lock()


def _overlay_cache_save():
    # WAVE-TICK-1119: callable from the merge_src_overlay worker threads: one writer at a time, a snapshot of the dict, a per-thread tmp name
    try:
        with _OVL_LOCK:
            snap = {f"{h}|{s}": list(v) for (h, s), v in list(SRC_OVERLAY_CACHE.items())}
            tmp = f"{OVERLAY_CACHE_FILE}.tmp{os.getpid()}.{_thr_ovl.get_ident()}"
            open(tmp, "w").write(json.dumps(snap))
            os.replace(tmp, OVERLAY_CACHE_FILE)
    except OSError:
        pass
SRC_OVERLAY_TIMEOUT_S = 420            # full content hash of a ~30k-file tree on a loaded gen host (was 90 s: S81 unreadable 27 ticks)
SRC_OVERLAY_SIG_TIMEOUT_S = 150


def _overlay_run(src, host, hub, script, timeout):
    remote = _ssh(host, hub)
    try:
        if remote:
            r = subprocess.run(remote + [f"cd {shlex.quote(src)} && python3 -I -c {shlex.quote(script)}"],
                               capture_output=True, text=True, timeout=timeout)
        else:
            r = subprocess.run(["python3", "-I", "-c", script], cwd=src, capture_output=True, text=True, timeout=timeout)
    except (OSError, subprocess.SubprocessError):
        return None
    return r.stdout.strip() if r.returncode == 0 else None


def src_overlay_hash(src, host, hub, timeout=None):
    """content hash of the source scope on its gen host; '' when it cannot be read.  KW-FIX-45 11-12 (COORD): cached per
    tree (host, path) under a cheap signature (file count, newest mtime_ns, total size over the scope: an in-place edit
    changes it, a top-dir mtime would not) so the full read runs only after a change, with a longer timeout; the caller
    treats '' as CHANGED (never as 'no overlay to compare')."""
    _overlay_cache_load()
    sig = _overlay_run(src, host, hub, SRC_OVERLAY_SIG_SCRIPT, SRC_OVERLAY_SIG_TIMEOUT_S)
    key = (host, src)
    hit = SRC_OVERLAY_CACHE.get(key)
    if sig and hit and hit[0] == sig:
        return hit[1]
    out = _overlay_run(src, host, hub, SRC_OVERLAY_SCRIPT, timeout or SRC_OVERLAY_TIMEOUT_S)
    if out and re.fullmatch(r"[0-9a-f]{64}", out):
        if sig:
            SRC_OVERLAY_CACHE[key] = (sig, out)
            _overlay_cache_save()
        return out
    return ""


def merge_src_overlay(cfg, hub, log=None):
    """set each enabled die's in-memory _src_overlay, once per pass.  WAVE-TICK-1119: the per-die ssh signature probes run in parallel
    (they were serial: 33 s of a 480 s wave step); results are applied in die order, so the log is unchanged."""
    from concurrent.futures import ThreadPoolExecutor
    todo = [(die, d) for die, d in (cfg.get("dies") or {}).items()
            if isinstance(d, dict) and d.get("enabled") and d.get("src") and d.get("gen_host")]
    if not todo:
        return
    _overlay_cache_load()
    with ThreadPoolExecutor(max_workers=min(8, len(todo))) as ex:
        hashes = list(ex.map(lambda x: src_overlay_hash(x[1]["src"], x[1]["gen_host"], hub), todo))
    for (die, d), h in zip(todo, hashes):
        d["_src_overlay"] = h
        if log and not h:
            log(f"KIT-WAVE src_overlay: {die} unreadable on {d['gen_host']}; hold compares without it")


def merge_auto_views(cfg, ap_dir, log=None):
    """overlay the sidecar's counted views FIRST into each die's prov_view_sources (in memory) -> {die: [modules]}"""
    p = Path(ap_dir or AP_DIR) / AUTO_VIEWS_FILE
    try:
        side = json.loads(p.read_text())
    except (OSError, ValueError):
        return {}
    out = {}
    for die, ent in ((side or {}).get("dies") or {}).items():
        d = (cfg.get("dies") or {}).get(die)
        if not isinstance(d, dict) or opt(cfg, die, "auto_child_views") is False:
            continue
        pvs = dict(d.get("prov_view_sources") or {})
        for m, cands in sorted(((ent or {}).get("modules") or {}).items()):
            new = [dict(c, counted=True) for c in cands or [] if isinstance(c, dict) and c.get("host") and c.get("dir")]
            if not new:
                continue
            old = pvs.get(m) or []
            old = old if isinstance(old, list) else [old]
            dirs = {c["dir"] for c in new}
            rest = [c for c in old if not (isinstance(c, dict) and c.get("dir") in dirs)]
            # DIE-HBM-97 11-09: a config entry with a detailed abstract is a proven fix for this module; a sidecar view
            # without detail must not shadow it (ot_wbq_root_g1 and others kept their DRT-0073 LEF that way).
            first = [] if any(c.get("detailed_lef") for c in new) else [
                c for c in rest if isinstance(c, dict) and c.get("detailed_lef")]
            pvs[m] = first + new + [c for c in rest if not any(c is f for f in first)]
            out.setdefault(die, []).append(m)
        if die in out:
            d["prov_view_sources"] = pvs
            d["_auto_views"] = out[die]
    if out and log:
        log("KIT-WAVE AUTO-VIEWS overlay: " + " ".join(f"{k}={len(v)}" for k, v in sorted(out.items())))
    return out


def auto_views_step(AP, cfg, st, ap_dir, now=None):
    """launch counted_child_views.py --export --publish for each die whose plan probe has SIGNED IN COUNT BUT NO WAVE
    VIEW children; at most once per AUTO_VIEWS_PERIOD_S per die and never while the die's previous unit is active.
    -> {die: unit}"""
    now = time.time() if now is None else now
    ap_dir = Path(ap_dir or AP_DIR)
    runs = st.setdefault("auto_views", {})
    tool = Path(__file__).resolve().with_name("counted_child_views.py")
    out = {}
    for die, d in sorted((cfg.get("dies") or {}).items()):
        if not isinstance(d, dict) or "_plan_flags" not in d or opt(cfg, die, "auto_child_views") is False:
            continue
        nv = count_noview(d, count_signed_modules(d, die))
        if not nv:
            continue
        last = runs.get(die) or {}
        if now - float(last.get("t") or 0) < float(opt(cfg, die, "auto_views_period_s") or AUTO_VIEWS_PERIOD_S):
            continue
        if last.get("unit") and hasattr(AP, "unit_active") and AP.unit_active(last["unit"]):
            continue
        unit = f"kw-av-{re.sub(r'[^A-Za-z0-9]', '', die)[:16]}-{int(now) % 100000}"
        jd = ap_dir / "auto_views" / die
        dc = {k: d.get(k) for k in ("gen_host", "plan", "event")}
        argv = ["python3", "-I", str(tool), "--die", die, "--export", "--manifest", str(jd / "manifest.json"),
                "--config", str(jd / "config.json"), "--state", str(ap_dir / STATE_FILE),
                "--counter", str(Path(d.get("count_cache") or COUNT_CACHE)), "--publish", str(ap_dir / AUTO_VIEWS_FILE),
                "--only", *nv]
        if getattr(AP, "DRY", False):
            AP.log(f"KIT-WAVE would AUTO-VIEWS {die}: export {len(nv)} counted children ({' '.join(nv[:6])})")
            continue
        jd.mkdir(parents=True, exist_ok=True)
        (jd / "config.json").write_text(json.dumps({"dies": {die: dc}}, indent=1))
        ok = AP.launch_unit(unit, jd / "unit.log", argv)
        runs[die] = {"t": now, "unit": unit if ok else None, "modules": nv, "ok": bool(ok)}
        AP.log(f"KIT-WAVE AUTO-VIEWS {die}: {'launched ' + unit if ok else 'launch FAILED'} for {len(nv)} counted "
               f"children without a wave view ({' '.join(nv[:6])}{' ...' if len(nv) > 6 else ''})")
        if ok:
            out[die] = unit
    return out


def count_view_note(d, deps, counted):
    """'' or '; count: ...' -- per child: signed in the count AND a counted signed view in prov_view_sources (the kit
    is built on it and is FINAL), signed in the count but NO wave view (export it: counted_child_views.py), unsigned"""
    if counted is None or not deps:
        return ""
    has = lambda m: has_counted_view(d, m)
    sv = [m for m in deps if m in counted and has(m)]
    nv = [m for m in deps if m in counted and not has(m)]
    un = [m for m in deps if m not in counted]
    parts = ([f"signed+view {len(sv)}"] if sv else []) + (
        [f"SIGNED IN COUNT BUT NO WAVE VIEW {len(nv)} ({','.join(nv[:4])})"] if nv else []) + (
        [f"unsigned {len(un)} ({','.join(un[:4])})"] if un else [])
    return "; count: " + ", ".join(parts)


def lint_reason(issues):
    kinds = sorted({str(i).split(":", 1)[0] for i in issues})
    return f"LINT {'+'.join(kinds)}: gen-time lint before launch (no build), see kit_wave_stages.tsv LINT rows"


def prelint(d, die, names, state):
    """-> {item: [issue, ...]} for the current plan of record: probe (plan-static) issues + verdict history on the SAME
    plan block (key) that no named fix released.  names: {type: block_sha} (or a set)."""
    out = {t: list(v) for t, v in (d.get("_plan_lint") or {}).items()}
    counted = count_signed_modules(d, die)
    for t, f in (d.get("_plan_flags") or {}).items():
        if f in ("planned", "noview") and not (f == "planned" and d.get("planned_core_flat")):
            deps = (d.get('_plan_deps') or {}).get(t, [])
            out.setdefault(t, []).append(f"view: planned hard core without a signed view: "
                                         f"{','.join(deps[:4])} "
                                         + ("(launches on PROVISIONAL child views, KW-PROV-1)" if prov_on(d)
                                            else "(waits, WAIT-DEP)") + count_view_note(d, deps, counted))
    fixed = set((d.get("retry_fix") or {}).keys()) if isinstance(d.get("retry_fix"), dict) else set()
    items = (state or {}).get("items") or {}
    blocks = names if isinstance(names, dict) else {}
    for t in (names or ()):
        rec = items.get(item_key(die, d.get("event"), t, blocks.get(t)))
        if not rec or rec.get("status") not in ("FAIL", "CANCELLED") or f"{t}@{rec.get('attempt')}" in fixed:
            continue
        txt = f"{rec.get('reason') or ''}\n{rec.get('errors') or ''}"
        for kind, rx, msg in PRELINT_HISTORY:
            if rx.search(txt):
                out.setdefault(t, []).append(f"{kind}: {msg} (attempt {rec.get('attempt')})")
    return {t: v for t, v in out.items() if v and (not names or t in names)}


def record_lint(st, cfg, die, lint):
    """replace the die's LINT rows (st['lint']) with this tick's verdict"""
    d = cfg["dies"][die]
    L = st.setdefault("lint", {})
    for k in [k for k, v in L.items() if v.get("die") == die]:
        del L[k]
    if d.get("prelint", True) is False:
        return
    blocks = d.get("_lint_blocks") or {}
    for t, issues in lint.items():
        L[f"{die}|{t}"] = dict(die=die, item=t, event=d.get("event"), plan_sha=d.get("_plan_sha"),
                               block_sha=blocks.get(t) if isinstance(blocks, dict) else None,
                               issues=issues, evidence=d.get("plan", ""), updated=time.time())


def _own_wave_unit(r):
    """DIE-QC-63/KITS 11-02: overlay_owners writes the wave's OWN in-flight unit into the parent OWNERS row
    (owner KIT-WAVE-*, live_job 'kit-wave unit ...', newest record of ANY class of that parent).  That is not
    another lane's claim: per-class records already gate in-flight classes ('wave item in flight' / 'all plan
    classes already in the wave').  Treating it as one blocked every sibling class and every released retry of
    the parent while one sibling ran (QC 11-02: 18 parents; GPL-0305 retries x3, slw_stm_v1__cle34a73c3 never
    launched)."""
    if not str(r.get("owner", "")).startswith("KIT-WAVE"):
        return False
    lj = str(r.get("live_job", ""))
    if lj.startswith("kit-wave unit"):
        return True
    # KW-FIX-12 11-05: the queue form 'ap-<id>-a<n> <id>' on a KIT-WAVE row is the wave's own routed kit of one sibling
    # class; it blocked released retries of the other classes (QC 11-05: 26 parents, sle_su_l1).
    # KW-FIX-35-P 11-08: ownership.py lists EVERY live job of the parent, '; '-joined, with ' (+N)' for jobs not shown
    # ('ap-X-a1 X; ap-Y-a1 Y (+2)').  Only the first entry was read, so two of the wave's own route jobs looked like
    # another lane's claim and held sle_stm_v2 / slw_su_l0 classes on 11-08.  Each listed entry must be the wave's own
    # (ap- queue job, or an ot-run job dir of this item / its classes); one foreign entry keeps the claim.
    lj = re.sub(r"\s*\(\+\d+\)\s*$", "", lj)
    parts = [x.strip() for x in lj.split("; ") if x.strip()]
    return bool(parts) and all(_own_wave_entry(x, r["item"]) for x in parts)


def _own_wave_entry(lj, item):
    """one live_job entry of a KIT-WAVE OWNERS row: the wave's own queue job or its own place/geom job of item"""
    if re.fullmatch(r"ap-[0-9a-f]+-a\d+ [0-9a-f]+", lj):
        return True
    # ownership.py form 'ot-run pid N <last 70 chars of the job dir>': the wave's own place/geom job of this item or
    # one of its classes (wave kit dirs end .../items/<class>/[attempt_n/]gen/<class>)
    if not lj.startswith("ot-run pid"):
        return False
    segs = re.split(r"[/\s]+", lj.split(None, 3)[-1]) if len(lj.split(None, 3)) == 4 else []
    return ("gen" in segs or "items" in segs) and any(x == item or x.startswith(item + "_") for x in segs)


def blocked_parents(d):
    """SCHED-1 11-07 (OWNER closure first): {child module: plan types still waiting for its view}, from the plan probe's
    _plan_deps / _prov_deps.  The rows that unlock the most blocked parents launch first."""
    n = {}
    for deps in (d.get("_prov_deps") or d.get("_plan_deps") or {}).values():
        for m in set(deps):
            n[m] = n.get(m, 0) + 1
    return n


WAVE_SRC_CHECK_DIR = "/srv/opentallas-scratch2/claude/wave-ops-1/srccheck"


def wave_src_flag(cfg, die):
    """WAVE-OPS-1 11-10 (COORD URGENT (a)): the FLAGS line for a die whose wave src differs from its declared commit +
    approved overlays, read from WAVE-OPS-1's last check (srccheck/<die>.json on the hub); '' when clean, absent, for
    another src, or unreadable.  ADVISORY (OWNER 11-03 targets, not gates)."""
    d = (cfg.get("dies") or {}).get(die) or {}
    try:
        r = json.loads((Path(cfg.get("wave_src_check_dir") or WAVE_SRC_CHECK_DIR) / f"{die}.json").read_text())
    except (OSError, ValueError):
        return ""
    if not isinstance(r, dict) or r.get("src") != d.get("src") or not r.get("mismatch"):
        return ""
    return (f"FLAGS WAVE-SRC-DRIFT {die}: src {r.get('src')} on {r.get('host')} differs from declared "
            f"{str(r.get('declared') or '?')[:12]} + approved overlays in {r['mismatch']} file(s) "
            f"(stale old git copies {r.get('stale', 0)}, not in git {r.get('undeclared', 0)}; checked {r.get('at', '?')}; "
            f"ADVISORY, WAVE-OPS-1 wave_src_check)")


NO_ROW_SOURCE = "NO-ROW-SOURCE: only_items item with no OWNERS row and no plan_core_items/allowlist row (never launches)"


def no_row_source(rows, d, die, plan_types):
    """WAVE-OPS-1 11-10 (OWNER item A): only_items names the wave can never pick because nothing makes a row for them.
    A row comes from OWNERS.tsv (the item, its class parent '<k>__...', or its core module for '<m>__v<sha12>'), from
    plan_items_from_allowlist (a type in the plan of record) or from plan_core_items (a core in the plan of record).
    18 HBM cores were allowed in only_items but had no OWNERS row and no plan_core_items entry, so they silently never
    launched.  -> sorted list of those items; [] when the plan is unknown (no probe) or there is no allowlist."""
    if plan_types is None or d.get("only_items") is None:
        return []
    known = {r["item"] for r in rows if r["die"] == die}
    cores = set(d.get("plan_core_items") or [])
    out = []
    for item in d.get("only_items") or []:
        if item in known or core_module(item) in known or any(item.startswith(k + "__") for k in known):
            continue
        if item in plan_types and (d.get("plan_items_from_allowlist") or item in cores):
            continue
        out.append(item)
    return sorted(set(out))


PLAN_CORE_NOT_IN_ONLY = ("PLAN-CORE-NOT-IN-ONLY: plan_core_items core in the plan of record but not in only_items "
                         "(its row is dropped as outside configured only_items; never launches)")


def plan_core_not_in_only(d, plan_types):
    """KIT-OPS-1 11-12 (CORE-ROWS-1 17:23 class): select() makes a kind=core row for every plan_core_items name that is a
    plan type, then the only_items filter drops it as "outside configured only_items" with no log line (4 HBM cores with
    item_args/item_env never launched).  -> sorted plan_core_items names that are plan types (all of them when the plan is
    unknown) and are missing from a configured only_items; [] when there is no only_items list."""
    if d.get("only_items") is None:
        return []
    allowed = set(d.get("only_items") or [])
    return sorted({c for c in d.get("plan_core_items") or []
                   if c not in allowed and (plan_types is None or c in plan_types)})


def item_key_matches(key, name):
    """a config key (exact item, fnmatch glob, or a base whose class/instance variants are '<key>__...') names the plan item"""
    key, name = str(key), str(name)
    return key == "*" or key == name or name.startswith(key + "__") or (bool(re.search(r"[*?\[]", key)) and fnmatch.fnmatchcase(name, key))


def env_key_applies(key, name):
    """BUILD-SETTINGS-AUDIT-1900 11-20 (COORD): an item_env key applies to an item exactly as item_env_entry applies it -- the exact
    name or an fnmatch glob, never the '<key>__...' base prefix that hold / only keys use (94 __pv / __pad variants silently missed
    their parent's env while the drift check, matching by prefix, reported nothing)"""
    key, name = str(key), str(name)
    return key == name or (bool(re.search(r"[*?\[]", key)) and fnmatch.fnmatchcase(name, key))


def plan_config_drift(d, names):
    """FLOW-R2 11-17 (COORD, S81 col after D6z): the plan names col_h9_r2__t1 while only_items / item_env / hold keys named the old suffixed
    variants, and the wave dropped the rows as 'outside configured only_items' without a word.  -> {only: [plan items no only_items entry covers],
    env: [item_env keys matching no plan item], hold: [hold key / record key matching no plan item]}; {} when only_items is not a list or the plan is unknown."""
    names = sorted(set(names or []))
    if not names:
        return {}
    out = {}
    only = d.get("only_items")
    if isinstance(only, list):
        out["only"] = [n for n in names if not any(item_key_matches(o, n) for o in only)]
        out["only_unmatched"] = [o for o in only if not any(item_key_matches(o, n) for n in names)]
    out["env"] = sorted(k for k in (d.get("item_env") or {}) if not any(env_key_applies(k, n) for n in names))
    keys = set(k for k in (d.get("hold_items") or {}))
    for rec in d.get("hold_records") or []:
        keys.update(str(x) for f in ("keys", "items", "patterns") for x in rec.get(f) or [])
    out["hold"] = sorted(k for k in keys if not any(item_key_matches(k, n) for n in names))
    return {k: v for k, v in out.items() if v}


def only_items_extend(d, names):
    """die option only_items_extend_families: true -> plan names whose family (text before the first '__') already appears in only_items are
    appended to only_items in memory (the file is not edited).  -> the names added"""
    only = d.get("only_items")
    if not d.get("only_items_extend_families") or not isinstance(only, list):
        return []
    fams = {str(o).split("__")[0] for o in only}
    add = [n for n in sorted(set(names or [])) if n.split("__")[0] in fams and not any(item_key_matches(o, n) for o in only)]
    d["only_items"] = list(only) + add
    return add


def plan_names_from_cache(st, d):
    c = (st.get("plans") or {}).get(f"{d.get('gen_host')}:{d.get('plan')}|{d.get('event')}") or {}
    return list(c.get("types") or [])


def plan_drift_step(AP, cfg, st):
    """after every compile (adopt / tree switch / config edit changes the signature): extend only_items for opted-in dies, post ONE ALERT per
    change listing plan items outside only_items and config keys matching no plan item.  Names come from the plan cache; no probe here."""
    sigs = st.setdefault("plan_drift_sig", {})
    cfg["_plan_item_names"] = {}
    for die, d in (cfg.get("dies") or {}).items():
        if not isinstance(d, dict) or not d.get("enabled"):
            continue
        names = plan_names_from_cache(st, d)
        if not names:
            continue
        cfg["_plan_item_names"][die] = names
        try:
            backfill_norm_blocks(AP, cfg, st, die)
        except Exception as _e:
            AP.log(f"KIT-WAVE NORM-BACKFILL {die} skipped: {type(_e).__name__}: {_e}")
        added = only_items_extend(d, names)
        if added:
            AP.log(f"KIT-WAVE ONLY-ITEMS-EXTEND {die}: {len(added)} plan item(s) of a listed family added in memory: " + " ".join(added[:20]))
        dr = plan_config_drift(d, names)
        sig = hashlib.sha1(json.dumps([d.get("src"), d.get("event"), sorted((k, v[:80]) for k, v in dr.items())]).encode()).hexdigest()[:12] if dr else ""
        if sig == sigs.get(die, ""):
            continue
        if not sig:
            sigs.pop(die, None)
            continue
        sigs[die] = sig
        parts = []
        if dr.get("only"):
            parts.append(f"{len(dr['only'])} plan item(s) outside only_items (rows dropped, never launch): " + " ".join(dr["only"][:25]))
        if dr.get("only_unmatched"):
            parts.append(f"{len(dr['only_unmatched'])} only_items name(s) match no plan item: " + " ".join(dr["only_unmatched"][:15]))
        if dr.get("env"):
            parts.append(f"item_env keys matching no plan item: " + " ".join(dr["env"][:15]))
        if dr.get("hold"):
            parts.append(f"hold keys matching no plan item: " + " ".join(dr["hold"][:15]))
        AP.log(f"KIT-WAVE PLAN-CONFIG-DRIFT {die}: " + "; ".join(parts)[:600])
        AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} ALERT [PLAN-CONFIG-DRIFT -> {d.get('owner_lane') or 'COORD'}] {die} plan {os.path.basename(str(d.get('plan')))} / "
                        f"tree {os.path.basename(str(d.get('src')))}: " + "; ".join(parts)[:1500] + ". Fix: kit_wave_edit only_items / item_env / hold keys to the plan names (or set dies.%s.only_items_extend_families)." % die)


# WF-1 11-14 (COORD friction 7, FABLE-REVIEW-COL step A): S81 col types are mostly duplicate kits.  "pv" is a per-instance ROM image
# parameter: item <base>__pv<hash> kits of one base are byte-identical (netlist, io.tcl, macro_place.tcl, SDC) -> 216 types, about
# 95 distinct kits.  After kit_rtl / gen / lint / preflight the unit hashes the kit identity (io.tcl, macro_place.tcl, constraint.sdc,
# pins.json, config.mk without paths, the item name and the per-instance parameter lines); the first member to claim an identity
# (die|base|hash, registry autopilot/kit_identity.json under a flock) builds, every later member with the SAME hash stops with
# verdict DEDUP and is credited when the owner signs (signed.tsv / unversioned.tsv clones + dedup_members.tsv).  A different
# hash = a distinct kit = built on its own.  Die option kit_dedup [item globs] (default s81: col_h*; [] = off), kit_dedup_cancel
# false = never cancel an in-flight duplicate.
# S81-COL-FLOW-1118 (OWNER r703 / r705: kit dedupe removed): no die dedupes by default; dies.<die>.kit_dedup (a list of item globs)
# opts a die back in.  Legacy DEDUP / DEDUP-WAIT records of a die without dedup are released by dedup_step (DEDUP OFF RELEASE)
# and launch on their own; the per-item fail key (identical full input digest) still refuses an unchanged relaunch.
DEDUP_DEFAULT = {}
PV_RE = re.compile(r"^(?P<base>.+)__pv[0-9a-f]{6,}$")
IDENT_FILE = os.environ.get("KW_IDENT_FILE") or os.path.expanduser("~/coord/autopilot/kit_identity.json")
DEDUP_MEMBERS = "dedup_members.tsv"
KIT_HASH_PY = r"""
import hashlib, os, re, sys
K, T = sys.argv[1].rstrip("/"), sys.argv[2]
h = hashlib.sha256(b"kit-identity-v2"); n = 0
for f in ("io.tcl", "macro_place.tcl", "constraint.sdc", "pins.json", "config.mk"):
    p = os.path.join(K, f)
    if not os.path.isfile(p):
        h.update(f.encode() + b"\0MISSING\0"); continue
    t = open(p, errors="replace").read()
    if f == "config.mk":
        t = "".join(l for l in t.splitlines(True) if not re.search(r"INSTANCE|__pv|OT_PARAM|PARAM_SET", l))
    t = t.replace(K, "<K>").replace(T, "<T>")
    t = re.sub(r"attempt_\d+", "attempt_N", t)
    # v2 (DIE-S81-92): purely per-type names never separate two kits: every token carrying a __pv<hash> parameter-variant label
    # (the collector_tree.type name, type / top labels) and every comment (the type labels in io.tcl / SDC / config.mk comments)
    t = re.sub(r"[A-Za-z0-9_.]*__pv[0-9a-f]{6,}[A-Za-z0-9_.]*", "<PV>", t)
    t = re.sub(r"(?m)[ \t]*;?#.*$", "", t)
    h.update(f.encode() + b"\0" + t.encode()); n += 1
print("KW_KIT_HASH " + h.hexdigest() if n >= 3 else "KW_KIT_HASH_NONE")
"""


def dedup_group(cfg, die, item):
    """'<die>|<base>' of a col-type member (item <base>__pv<hash>) when kit dedup applies to it, else ''"""
    d = (cfg.get("dies") or {}).get(die) or {}
    pats = d["kit_dedup"] if "kit_dedup" in d else DEDUP_DEFAULT.get(die)
    m = PV_RE.match(str(item or ""))
    if not pats or not m or not any(fnmatch.fnmatchcase(item, pt) for pt in pats):
        return ""
    return f"{die}|{m.group('base')}"


def ident_claim(group, h, item, hash_of=None, state_path=None):
    """-> ('owner' | 'member', owner item).  Registry key die|base|hash; the claim is atomic (flock).  A member needs an owner that is
    still alive in the wave state; with no entry, a legacy sibling (already past gen: ENQUEUED / PASS with a kit path) whose kit
    hashes the same becomes the owner (hash_of(host, kit path, item) -> hash or '')"""
    import fcntl
    die = group.split("|", 1)[0]
    key = f"{group}|{h}"
    Path(IDENT_FILE).parent.mkdir(parents=True, exist_ok=True)
    lk = open(IDENT_FILE + ".lock", "w")
    fcntl.flock(lk, fcntl.LOCK_EX)
    try:
        try:
            reg = json.loads(Path(IDENT_FILE).read_text())
        except (OSError, ValueError):
            reg = {}
        try:
            items = (json.loads(Path(state_path or (Path(IDENT_FILE).parent / "kit_wave_state.json")).read_text()).get("items") or {}).values()
        except (OSError, ValueError):
            items = []
        items = list(items)
        alive_st = ("RUNNING", "LAUNCHING", "PASS", "ROUTE-HELD", "ENQUEUED")

        def alive(it):
            best = [r for r in items if r.get("die") == die and r.get("item") == it]
            best = max(best, key=lambda r: float(r.get("updated") or 0), default=None)
            return bool(best) and best.get("status") in alive_st and best.get("q_status") not in ("FAIL", "CANCELLED")
        e = reg.get(key)
        if e and e.get("owner") != item and alive(e["owner"]):
            return "member", e["owner"]
        if not e and hash_of:
            base = group.split("|", 1)[1]
            cands = [r for r in items if r.get("die") == die and r.get("item") != item and PV_RE.match(str(r.get("item")))
                     and PV_RE.match(r["item"]).group("base") == base and r.get("status") in ("ENQUEUED", "PASS") and r.get("kit")
                     and ":" in str(r.get("kit")) and r.get("q_status") not in ("FAIL", "CANCELLED")]
            for r in sorted(cands, key=lambda r: -float(r.get("updated") or 0))[:3]:
                host, _, kp = str(r["kit"]).partition(":")
                if hash_of(host, kp, r["item"]) == h:
                    reg[key] = {"owner": r["item"], "t": time.time(), "hash": h, "legacy": True}
                    Path(IDENT_FILE).write_text(json.dumps(reg, indent=1))
                    return "member", r["item"]
        reg[key] = {"owner": item, "t": time.time(), "hash": h}
        tmp = IDENT_FILE + ".tmp"
        Path(tmp).write_text(json.dumps(reg, indent=1))
        os.replace(tmp, IDENT_FILE)
        return "owner", item
    finally:
        lk.close()


def ident_release(group, h):
    """drop the registry entry of an identity whose owner failed (the next member to start claims it)"""
    import fcntl
    try:
        lk = open(IDENT_FILE + ".lock", "w")
        fcntl.flock(lk, fcntl.LOCK_EX)
        reg = json.loads(Path(IDENT_FILE).read_text())
        if reg.pop(f"{group}|{h}", None) is not None:
            Path(IDENT_FILE).write_text(json.dumps(reg, indent=1))
        lk.close()
    except (OSError, ValueError):
        pass


SIGNED_Q = ("SIGNED", "SIGNED-UNVERSIONED", "ARCHIVED", "WAIT-PARENT", "TRIAL-SIGNED")


_KEY_SOURCES = {}
CONFIG_KEY_SKIP = re.compile(r"^(note|_|\#|comment|hold_note)")


def runtime_key_universe(tools_dir=None):
    """every quoted token of the wave's own sources (kit_wave.py, autopilot.py, flow_guard.py, ...): a die key the runtime reads appears in them as a
    string literal"""
    root = Path(tools_dir) if tools_dir else Path(__file__).resolve().parent
    k = str(root)
    if k not in _KEY_SOURCES:
        toks = set()
        for p in root.glob("*.py"):
            if p.name.startswith("test_"):
                continue
            try:
                toks |= set(re.findall(r"[\"']([A-Za-z_][A-Za-z0-9_]{2,})[\"']", p.read_text(errors="replace")))
            except OSError:
                pass
        _KEY_SOURCES[k] = toks
    return _KEY_SOURCES[k]


def unread_config_keys(cfg, universe=None):
    """FABLE-FLOW-0445 / 0015 class 2 (a config key with no reader): {die: [keys]} of kit_wave.json die keys the runtime source never mentions.  The key is
    silently ignored: QC / S81 trees were rebuilt for a flag nothing read.  Keys of per-item maps (hold_items, item_inputs, retry_fix ...) are values, not keys."""
    uni = runtime_key_universe() if universe is None else universe
    out = {}
    for die, d in (cfg.get("dies") or {}).items():
        if not isinstance(d, dict):
            continue
        bad = sorted(k for k in d if not CONFIG_KEY_SKIP.match(k) and k not in uni)
        if bad:
            out[die] = bad
    return out


def config_key_check(AP, cfg, st):
    """log + one queue line per NEW unread key (state ledger), never every tick"""
    seen = st.setdefault("unread_keys", {})
    for die, keys in unread_config_keys(cfg).items():
        new = [k for k in keys if f"{die}.{k}" not in seen]
        for k in new:
            seen[f"{die}.{k}"] = time.time()
        if new:
            AP.log(f"KIT-WAVE CONFIG-KEY-UNREAD {die}: {' '.join(new)}: no code in tools/autopilot mentions these keys, they have no effect")
            AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} NEEDS-ACTION [FLOW-HEALTH-1 -> COORD] kit_wave.json dies.{die} has key(s) no runtime code "
                            f"reads: {' '.join(new[:12])}; the setting does nothing (delete it or add its reader)")


def retire_superseded_rows(AP, cfg, st, now=None):
    """RETIRE-1116 (COORD r293): an ENQUEUED row on an event that is not the die's current one, whose queue job already ended FAIL, is retired
    (CANCELLED class SUPERSEDED, never relaunched) when its (die, item) has a row on the current event, else it is released for a relaunch on the
    current event (same terminal mark: the wave's select then picks the item on the current event, as it is no longer a live attempt).  SIGNED and RUNNING
    queue rows are never touched.  Returns (retired, relaunched)."""
    now = time.time() if now is None else now
    items = st.get("items") or {}
    have = {(r.get("die"), r.get("item")) for r in items.values()
            if (cfg.get("dies") or {}).get(r.get("die"), {}).get("event") and r.get("event") == cfg["dies"][r.get("die")]["event"]}
    retired = relaunched = 0
    for r in items.values():
        d = (cfg.get("dies") or {}).get(r.get("die")) or {}
        if r.get("status") != "ENQUEUED" or not d.get("event") or not r.get("event") or r.get("event") == d["event"]:
            continue
        if str(r.get("q_status") or "").upper() not in ("FAIL", ""):
            continue
        if (r.get("die"), r.get("item")) in have:
            r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="retired", updated=now,
                     reason=f"SUPERSEDED: retired; event {r.get('event')} is not current ({d['event']}) and the type has a current-event row")
            retired += 1
        else:
            r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="relaunch", updated=now,
                     reason=f"SUPERSEDED: event {r.get('event')} is not current ({d['event']}); relaunched on the current event")
            relaunched += 1
    stale_enq = 0
    for r in items.values():                             # WAVE-PILOT-FIX 11-18 (COORD / FLEET-OPS-R): an ENQUEUED row of a superseded event idle > 24 h whose queue job is not live (SIGNED, FAIL ...) pins its kit dir
        d = (cfg.get("dies") or {}).get(r.get("die")) or {}
        if r.get("status") != "ENQUEUED" or not d.get("event") or not r.get("event") or r.get("event") == d["event"] or not FG.stops_off_die(cfg, r.get("die")):
            continue
        if str(r.get("q_status") or "").upper() in REAP_LIVE_Q or r.get("q_status") in (None, ""):
            continue
        idle_h = (now - max(float(r.get("updated") or 0), float(r.get("started") or 0))) / 3600.0
        if idle_h <= float(d.get("retire_stale_enqueued_h", cfg.get("retire_stale_enqueued_h", 24))):
            continue
        r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="stale-enqueued", updated=now,
                 reason=f"SUPERSEDED: ENQUEUED row of event {r.get('event')} (die is on {d['event']}), queue job {r.get('q_status')}, idle {idle_h:.0f} h: no longer a live attempt, its kit dir is free to delete once exported")
        stale_enq += 1
    dedup = 0
    for r in items.values():                             # DEDUP-RETIRE-1116 (FABLE-FLOW-1113 #8: 173 unowned S81 DEDUP rows from the old plan line)
        d = (cfg.get("dies") or {}).get(r.get("die")) or {}
        if r.get("status") != "DEDUP" or not d.get("event"):
            continue
        old = bool(r.get("event")) and r.get("event") != d["event"]
        owner_gone = any(o.get("die") == r.get("die") and o.get("item") == r.get("dedup_owner") and o.get("event") == r.get("event")
                         and o.get("status") == "CANCELLED" and o.get("class") == "SUPERSEDED" for o in items.values())
        if old or owner_gone:
            r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="dedup", updated=now,
                     reason=f"SUPERSEDED: DEDUP member of {r.get('dedup_owner')} on " + (f"event {r.get('event')} (die is on {d['event']})" if old else "a retired owner row"))
            dedup += 1
    stale = 0
    names_of = {}
    for r in items.values():                             # STALE-PLAN-1117 (COORD, S81 col after D6z): a FAIL row of an item the current plan no longer names, on another plan sha
        die = r.get("die")
        d = (cfg.get("dies") or {}).get(die) or {}
        if r.get("status") != "FAIL" or not d.get("enabled"):
            continue
        if die not in names_of:
            names_of[die] = set(plan_names_from_cache(st, d)) if d.get("plan") and d.get("gen_host") else set()
        cur = str(d.get("plan_sha256") or d.get("_plan_sha") or "").lower()
        old = str(r.get("plan_sha") or "").lower()
        if not names_of[die] or not cur or not old or old == cur or r.get("item") in names_of[die]:
            continue
        r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="stale-plan", updated=now,
                 reason=f"SUPERSEDED: {r.get('item')} is not an item of the current plan ({cur[:12]}) and the row's plan block is {old[:12]}; the type relaunches under its current name")
        stale += 1
    for r in items.values():                             # FABLE-FLOW-0010 H: a ROUTE-HELD row the wave itself parked on an old plan (SKIP-OLDPLAN) is history on the next tick
        d = (cfg.get("dies") or {}).get(r.get("die")) or {}
        if r.get("status") == "ROUTE-HELD" and d.get("enabled") and d.get("event") and r.get("event") and r["event"] != d["event"] \
                and str(r.get("route_hold") or "").startswith("SKIP-OLDPLAN") and _plan_current(cfg, st, r) is False:
            r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="oldplan-route-hold", updated=now,
                     reason=f"SUPERSEDED: ROUTE-HELD on event {r.get('event')} (die is on {d['event']}); was: " + str(r.get("route_hold"))[:160])
            stale += 1
    old_ev = 0
    for r in items.values():                             # STALE-EVENT-1117 (COORD failure_breakdown 22:30): a FAIL row on an event that is not the die's current one is history, not a type failure:
        d = (cfg.get("dies") or {}).get(r.get("die")) or {}          # the item launches on the current event on its own key; the breakdown counted 40+ such rows per die as open failures
        if r.get("status") != "FAIL" or not d.get("enabled") or not d.get("event") or not r.get("event") or r.get("event") == d["event"]:
            continue
        if d.get("retire_stale_event_fails") is False or str(r.get("class")) == "SUPERSEDED":
            continue
        r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="stale-event", updated=now,
                 reason=f"SUPERSEDED: FAIL on event {r.get('event')} (die is on {d['event']}); was: " + str(r.get("reason"))[:200])
        old_ev += 1
    stale += old_ev
    if (retired or relaunched or dedup or stale or stale_enq) and AP is not None:
        AP.log(f"KIT-WAVE RETIRE-SUPERSEDED retired {retired} (type has a current-event row), relaunch-on-current {relaunched}, dedup members {dedup}, stale-plan FAIL rows {stale}, stale ENQUEUED (>24 h, superseded event) {stale_enq}")
    return retired, relaunched


def adopt_rows_tick(AP, cfg, st, now=None, alert_after=2):
    """WAVE-FLOW-R2 11-17 (FABLE-FLOW-1700 item 3): after a die tree switch (apply) account for the current-event rows of every plan type: one ADOPT-ROWS line per tick
    (n/m types have a row; old-event rows that were superseded and have no current row), and one NEEDS-LANE when rows < plan types after `alert_after` ticks, naming the
    missing types, so a switch that leaves 90 superseded rows unlaunched (QC N1B) is seen at once.  -> {die: (n, m, missing list)} for dies still being watched"""
    now = time.time() if now is None else now
    seen = st.setdefault("adopt_seen", {})
    items = list((st.get("items") or {}).values())
    out = {}
    for die, d in (cfg.get("dies") or {}).items():
        if not isinstance(d, dict) or not d.get("enabled") or not d.get("src"):
            continue
        rec, src = seen.get(die), d["src"]
        sig = [d.get("event"), d.get("plan_event")]
        if rec is None:
            seen[die] = dict(src=src, sig=sig, t=now, switched=False)
            continue
        if rec.get("src") != src or (rec.get("sig") is not None and rec.get("sig") != sig):
            seen[die] = dict(src=src, sig=sig, was=rec.get("src"), t=now, switched=True, ticks=0, sup_ticks=0, alerted=False)
            AP.log(f"KIT-WAVE ADOPT-ROWS {die}: tree switched {os.path.basename(str(rec.get('src')))} -> {os.path.basename(str(src))}")
            continue
        if not rec.get("switched") or rec.get("done"):
            continue
        types = set(d.get("_plan_types") or [])
        if not d.get("event"):
            continue
        rec["ticks"] = int(rec.get("ticks") or 0) + 1
        mine = [r for r in items if r.get("die") == die]
        if not types:                                    # FABLE-FLOW-2200 A: a die the wave never probes (OFF: event not a plan of record) still gets the check
            if not any(r.get("event") == d["event"] for r in mine) and rec["ticks"] >= alert_after and not rec.get("alerted") and not AP.DRY:
                rec["alerted"] = True
                try:
                    _ok, _why = gate(cfg, die, None)
                except Exception as _e:
                    _ok, _why = False, f"gate unreadable: {_e}"
                AP.log(f"KIT-WAVE ADOPT-ROWS {die}: no row on the current event {d['event']} {rec['ticks']} ticks after the switch; gate: {_why[:200]}")
                AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} NEEDS-LANE [ADOPT-ROWS -> {d.get('owner_lane') or die}] {die}: {rec['ticks']} ticks after the tree / event switch "
                                f"no item has a row on {d['event']} and the plan is not probed. Gate: {'ok' if _ok else 'OFF'} ({_why[:300]}). If OFF for 'not a COORD plan of record' add the label to "
                                f"dies.{die}.gate_events_extra (the apply tool does this itself since 11-17); else check holds / only_items / pilot")
            continue
        have = {r.get("item") for r in mine if r.get("event") == d["event"]}
        old_only = {r.get("item") for r in mine if r.get("event") != d["event"] and r.get("class") == "SUPERSEDED"} - have
        missing = sorted(types - have)
        n, m = len(types & have), len(types)
        out[die] = (n, m, missing)
        AP.log(f"KIT-WAVE ADOPT-ROWS {die}: {n}/{m} plan types have a row on event {d['event']} (tick {rec['ticks']}); {len(old_only & set(missing))} superseded on the old tree and not relaunched")
        if not missing:
            rec["done"] = True
        elif rec["ticks"] >= alert_after and not rec.get("alerted") and not AP.DRY:
            rec["alerted"] = True
            AP.coord_append("lanes/COORD-REVIEW-QUEUE.md", f"- {now_s()} NEEDS-LANE [ADOPT-ROWS -> {d.get('owner_lane') or die}] {die}: tree switch {rec['ticks']} ticks ago, "
                            f"only {n}/{m} plan types have a row on {d['event']}; missing e.g. {', '.join(missing[:12])}; {len(old_only & set(missing))} of them were superseded "
                            f"on the old tree. Check the pilot hold, the hold records' event terms and the fail keys of these items")
    return out


def signed_equivalent(cfg, st, die, item, cur_norm=None):
    """a SIGNED row of (die, item) whose path-normalized plan block equals the current plan's: the signed record is the answer for this block even though a tree rename gave it another raw
    sha (the wave relaunched signed hd_serdes twice on r3).  -> the row or None"""
    cn = (cur_norm if cur_norm is not None else current_norm_blocks(cfg, st)).get(die, {}).get(item)
    if not cn:
        return None
    for r in (st.get("items") or {}).values():
        if r.get("die") == die and r.get("item") == item and str(r.get("q_status") or "").upper() in ("SIGNED", "SIGNED-LINKED") and r.get("norm_block") == cn:
            return r
    return None


def backfill_norm_blocks(AP, cfg, st, die, max_probes=3):
    """rows launched before norm_blocks existed carry only the raw block sha: probe the plan file each live old-event row was built from (spec.json plan, once per plan path, cached in
    st['plans_norm']) and store the item's normalized sha on the row when the probe's raw sha still equals the row's block_sha"""
    d = (cfg.get("dies") or {}).get(die) or {}
    cache = st.setdefault("plans_norm", {})
    probes = 0
    for r in (st.get("items") or {}).values():
        signed = str(r.get("q_status") or "").upper() in ("SIGNED", "SIGNED-LINKED")
        if r.get("die") != die or (r.get("norm_block") and r.get("norm_v") == PROBE_V and r.get("die_ctx")) or not r.get("block_sha") or not (signed or (r.get("status") in ("RUNNING", "LAUNCHING", "ENQUEUED") and r.get("event") != d.get("event"))):
            continue
        try:
            plan = json.loads((Path(r["dir"]) / "spec.json").read_text()).get("plan")
        except (OSError, ValueError, KeyError, TypeError):
            continue
        if not plan:
            continue
        key = f"{d.get('gen_host')}:{plan}|v{PROBE_V}"
        if key not in cache:
            if probes >= max_probes or AP.DRY:
                continue
            probes += 1
            try:
                p = AP.rpy(d["gen_host"], PROBE_PLAN, {"plan": plan, "core_views": bool(d.get("core_kit")), "cells_max": 0, "block_ignore": d.get("block_ignore")}, timeout=600)
            except Exception:
                p = {}
            cache[key] = ({"blocks": p.get("blocks") or {}, "norm": p.get("norm_blocks") or {}, "ctx": p.get("die_ctx") or {}} if not p.get("error")
                          else {"blocks": {}, "norm": {}, "ctx": {}})
        c = cache[key]
        if c["blocks"].get(r.get("item")) == r.get("block_sha") and c["norm"].get(r.get("item")):
            r["norm_block"] = c["norm"][r["item"]]
            r["norm_v"] = PROBE_V
            if (c.get("ctx") or {}).get(r["item"]):
                r["die_ctx"] = c["ctx"][r["item"]]


def replacement_blocked(st, die, item):
    """FABLE-FLOW-0358 A (S81 d8e -> d8f -> d8g: 196 rows cancelled for replacements that failed KIT_TOPOLOGY_BIND_STALE, 259 held): the bind preflight of the last probe named this item stale, so a
    replacement row on the new tree cannot launch.  The old row keeps running; it is cancelled in the tick where a replacement can launch"""
    return item in set(((st or {}).get("bind_stale_items") or {}).get(die) or ())


def ctx_changed(cur_ctx, die, r):
    """COORD 11-18 (QC N4.2): the row was built on another resolved die-level contract than the current plan gives its item (both known and different)"""
    cc = (cur_ctx or {}).get(die, {}).get(r.get("item"))
    return bool(cc) and bool(r.get("die_ctx")) and r["die_ctx"] != cc


POST_SYNTH_STAGES = ("place", "cts", "grt", "route", "sta", "signoff", "geom")


def finishes_on_old_plan(cfg, die, r, jobs):
    """OWNER 11-19 05:2x (\"do not freeze ... we count types signed off for whichever plan of the die\"): a kit already past synthesis (a wave row in place / cts / grt / route ..., or a queue
    job that is RUNNING) is never cancelled because a newer plan exists, even when its replacement can launch: both run, whichever signs first counts.  Only queued, not-started rows are
    superseded.  Not HBM (parked; keeps its holds).  Memory admission stays the only limit."""
    if not FG.stops_off_die(cfg, die):
        return False
    # COORD 11-19 (S81-OWN: 266+83 queued col geom jobs cancelled when D8 landed): plan_current=no never cancels or stops a queued or running job (any-plan sign-off counts); it only orders
    # priority (superseded last: DEFER-RESIGN, r711).  Explicit lane STRUCT-STOPs / cancel-rows are other paths and still work.
    if r.get("status") in ("RUNNING", "LAUNCHING"):
        return True
    if r.get("status") == "ENQUEUED" and r.get("q_id"):               # a queue job that is gone (done, crashed, orphan) or never existed blocks nothing and is still retired
        return str((jobs.get(r["q_id"]) or {}).get("status") or r.get("q_status") or "").upper() in REAP_LIVE_Q
    return False


def past_place(r, jobs):
    """the row is beyond gen / place: its queue job (route, CTS, sign-off) is running.  A RUNNING wave row is in gen / place by construction; an ENQUEUED row whose job has not started is still waiting"""
    if r.get("status") != "ENQUEUED":
        return False
    j = (jobs or {}).get(r.get("q_id")) or {}
    return str(j.get("status") or r.get("q_status") or "").upper() == "RUNNING"


def ctx_only_keep(cfg, die, r, item, cur_blocks, cur_norm, cur_ctx, jobs):
    """COORD 11-18 (QC N4.2 guard): a die_ctx-only change (the plan block itself unchanged) retires only rows that are ENQUEUED-not-started or in gen / place; a row past place keeps running and
    relaunches on the new block only if it fails (stricter than needed is still valid for R-MINIMAL).  True = keep"""
    return (ctx_changed(cur_ctx, die, r) and past_place(r, jobs)
            and row_inputs_unchanged(cfg, die, r, item, cur_blocks, cur_norm, None))


def row_inputs_unchanged(cfg, die, r, item, cur_blocks, cur_norm=None, cur_ctx=None):
    """OWNER 11-18: a live row keeps running when ITS inputs are unchanged on the new tree: the item's plan block equals the row's (raw sha, or the path-normalized sha with file contents hashed
    in place of tree paths: a tree rename moves the raw hash through clock.sink_bins_file-style absolute paths), and its staged views digest is what a launch would use now.  Tree path,
    tools sha and die-global bind / event keys are not inputs."""
    same = bool(r.get("block_sha")) and cur_blocks.get(die, {}).get(item) == r.get("block_sha")
    if not same:
        cn = (cur_norm or {}).get(die, {}).get(item)
        same = bool(cn) and r.get("norm_block") == cn
    if not same:
        return False
    if ctx_changed(cur_ctx, die, r):
        return False                                   # a die-level value this type consumes changed (seam_hold, tap window, reset ...): the kit was built on the old contract
    try:
        old = kit_digest_parts(cfg, die, r).get("views")
        now = kit_digest_parts(cfg, die, dict(item=item, block_sha=r.get("block_sha"))).get("views")
    except Exception:
        return True
    return (old or "") == (now or "")


def supersede_on_switch(AP, cfg, st, notices, ap_dir=None, window_ticks=3):
    """WAVE-FLOW-R2 11-17 (COORD, HEAD NF15f pilots could not launch: the wave allows ONE live attempt per item and an NF13a hd_lep0N in GRT for 29 h and an NF15d2r1 hd_mesh
    were still running): when a die's tree or event / plan_event switches (apply), every live attempt (wave unit RUNNING / LAUNCHING, queue job of an ENQUEUED row) whose
    kit event is not the die's new event is stopped and marked CANCELLED class SUPERSEDED, for `window_ticks` ticks after the switch, so the new pilots launch on the next tick.
    Kept (logged once): an item in the die's hold_items that protects a running row, and a row whose own plan block is the item's block in the current plan (its result still
    counts).  The stop is the existing one: the unit, then the host scopes of the attempt.  die option supersede_on_switch false = off.  -> number stopped"""
    cur_blocks = current_blocks(cfg, st)
    cur_norm = current_norm_blocks(cfg, st)
    cur_ctx = current_die_ctx(cfg, st)
    jobs = {}
    if ap_dir:
        try:
            jobs = json.loads((Path(ap_dir) / "state.json").read_text()).get("jobs") or {}
        except (OSError, ValueError):
            jobs = {}
    seen = st.get("adopt_seen") or {}
    cap = int(cfg.get("supersede_max_per_tick", DEFAULTS.get("supersede_max_per_tick", 20)))
    n, roots = 0, []
    for die, d in (cfg.get("dies") or {}).items():
        rec = seen.get(die) or {}
        if not isinstance(d, dict) or not rec.get("switched") or d.get("supersede_on_switch") is False or not d.get("event"):
            continue
        if die not in cur_blocks:                       # the new plan's probe is not cached yet: nothing can be judged unchanged, so nothing is cancelled (49 QC / 12 KV rows with an UNCHANGED block were)
            if not rec.get("defer_logged"):
                rec["defer_logged"] = True
                AP.log(f"KIT-WAVE SWITCH-SUPERSEDE {die}: current plan blocks not probed yet, cancelling nothing this tick")
            continue
        rec["sup_ticks"] = int(rec.get("sup_ticks") or 0) + 1
        if rec["sup_ticks"] > window_ticks:
            continue
        backfill_norm_blocks(AP, cfg, st, die)
        for key, r in (st.get("items") or {}).items():
            if r.get("die") != die or r.get("status") not in ("RUNNING", "LAUNCHING", "ENQUEUED") or not r.get("event") or r.get("event") == d["event"]:
                continue
            item = r.get("item") or ""
            held = next((str(w) for pat, w in (d.get("hold_items") or {}).items()
                         if fnmatch.fnmatchcase(item, pat) and hold_protects_running(cfg, d, r, str(w))), None)
            same = row_inputs_unchanged(cfg, die, r, item, cur_blocks, cur_norm, cur_ctx)
            ctxk = (not same) and ctx_only_keep(cfg, die, r, item, cur_blocks, cur_norm, cur_ctx, jobs)
            rbk = (not same) and FG.stops_off_die(cfg, die) and replacement_blocked(st, die, item)
            fin = (not same) and finishes_on_old_plan(cfg, die, r, jobs)
            if held is not None or same or ctxk or rbk or fin:
                why = (f"hold_items: {held[:120]}" if held is not None else
                       "already past synthesis on an older plan: it finishes, whichever plan signs first counts (OWNER 11-19)" if fin else
                       f"die-level contract changed but the row is past place (queue job running): finishes, relaunches on the new block only if it fails" if ctxk else
                       f"its replacement cannot launch (bind preflight: BIND-STALE on the current tree): kept, cancelled when the replacement launches (FABLE-FLOW-0358 A)" if rbk else
                       f"own plan block {str(r.get('block_sha'))[:12]} is the item's block in the current plan")
                if r.get("switch_kept") != why:
                    r["switch_kept"] = why
                    AP.log(f"KIT-WAVE SWITCH-SUPERSEDE-KEEP {die}/{item}@{r.get('attempt')} (event {r.get('event')}): {why}")
                continue
            units = []
            if r.get("status") in ("RUNNING", "LAUNCHING"):
                units.append(r.get("unit"))
                try:
                    units.append(json.loads((Path(r["dir"]) / "place_service.json").read_text())["unit"])
                except (OSError, ValueError, KeyError, TypeError):
                    pass
                what = f"wave {r.get('stage') or r.get('status')}"
            elif r.get("q_id"):
                j = jobs.get(r["q_id"]) or {}
                if j.get("status") != "RUNNING" or not j.get("unit"):
                    continue
                units.append(j["unit"])
                what = f"queue job {r['q_id']}"
            else:
                continue
            if n >= cap:
                AP.log(f"KIT-WAVE SWITCH-SUPERSEDE cap {cap} reached; {die}/{item} waits for the next tick")
                break
            if not AP.DRY:
                for u in units:
                    if u:
                        AP.sh(["systemctl", "--user", "stop", u], timeout=180)
                roots.append(attempt_root(r))
            r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, updated=time.time(),
                     reason=f"{what} on event {r.get('event')}: the die switched to {d['event']} (tree / event apply); one live attempt per item would block the new pilots")
            notices.setdefault(die, []).append(f"{item}@{r.get('attempt')} SUPERSEDED on switch: {what} stopped")
            AP.log(f"KIT-WAVE SWITCH-SUPERSEDE {die}/{item}@{r.get('attempt')} event {r.get('event')} -> {d['event']}: {what} stopped, units {units}")
            n += 1
    if roots:
        res = stop_on_fleet_bg(AP, roots)
        AP.log(f"KIT-WAVE SWITCH-SUPERSEDE remote stop: {' '.join(WJ.stopped_names(res))[:600] or 'queued in background (autopilot/remote_stops.log)'}"
               + "".join(f"; {h} not checked: {v['error']}" for h, v in res.items() if v.get("error")))
    return n


def name_stuck_retry_infra(AP, cfg, st, now=None, grace_s=1200):
    """FABLE-FLOW-0445 #5: a RETRY-INFRA row not relaunched within ~2 ticks takes the name of what stops it: SUPERSEDED (its event is not the die's current
    one: terminal CANCELLED), HELD:<class key> (open breaker class), FAIL-KEY (standing fail key), NO-HOST:<why>, else UNEXPLAINED.  Returns {name: n}."""
    now = time.time() if now is None else now
    out = {}
    for key, r in list((st.get("items") or {}).items()):
        if r.get("status") != "RETRY-INFRA" or now - float(r.get("updated") or 0) < grace_s:
            continue
        die, item = r.get("die"), r.get("item")
        d = (cfg.get("dies") or {}).get(die) or {}
        if d.get("event") and r.get("event") and r.get("event") != d.get("event"):
            name = "SUPERSEDED"
            r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retry_stop=name, updated=now,
                     reason=f"SUPERSEDED: RETRY-INFRA row of event {r.get('event')}; the die is on {d.get('event')}")
        elif any(__import__("fnmatch").fnmatchcase(item or "", pat) for pat in (d.get("hold_items") or {})):
            name = "HOLD-ITEM"        # FLEET-WATCH-R4 11-21: a die hold_items entry (infra_relaunch_due honours it) is the stop, not an older flow class of the item
        elif r.get("class") != "INFRA" and FG.held_key(st, die, item):      # an INFRA attempt (cancelled, no design result) inherits no older class hold (FLEET-WATCH-R4 11-21)
            name = "HELD:" + FG.held_key(st, die, item)[:60]
        elif fail_key_gate(cfg, st, die, item, r.get("block_sha"))[0]:
            name = "FAIL-KEY"
        elif r.get("no_host_at"):
            name = "NO-HOST"
        else:
            name = "UNEXPLAINED"
        if r.get("retry_stop") != name:
            r["retry_stop"] = name
            if AP is not None:
                AP.log(f"KIT-WAVE RETRY-INFRA-STOP {die}/{item}@{r.get('attempt')}: {name}")
        out[name.split(":")[0]] = out.get(name.split(":")[0], 0) + 1
    return out


def dedup_step(AP, cfg, st, notices, ap_dir):
    """DEDUP members: credit them when their owner signs (signed.tsv / unversioned.tsv clone of the owner row with the member type +
    a dedup_members.tsv record), release them (back to the normal launch path) when the owner failed; cancel in-flight legacy
    duplicates of an advanced sibling when both kits hash the same (exact unit, at most 8 hash probes per pass)"""
    items = st.get("items") or {}
    try:
        jobs = json.loads((Path(AP.AP_DIR) / "state.json").read_text()).get("jobs") or {}
    except (OSError, ValueError):
        jobs = {}
    now = time.time()
    for key, rec in list(items.items()):
        if rec.get("status") not in ("DEDUP", "DEDUP-WAIT"):
            continue
        die, owner = rec.get("die"), rec.get("dedup_owner")
        orecs = [r for r in items.values() if r.get("die") == die and r.get("item") == owner and r is not rec]
        orec = max(orecs, key=lambda r: float(r.get("updated") or 0), default=None)
        group, h = f"{die}|{PV_RE.match(rec['item']).group('base')}" if PV_RE.match(rec.get("item", "")) else "", rec.get("dedup_hash")
        if not dedup_group(cfg, die, rec.get("item")) and not (orec is not None and (orec.get("q_status") in SIGNED_Q or orec.get("status") in SIGNED_Q)):
            # S81-COL-FLOW-1118 (OWNER r703 / r705): dedup is off for this item: a held member (DEDUP behind a live owner, DEDUP-WAIT behind a failed one)
            # goes back to the normal launch path at once; a member whose owner already signed off keeps the credit path below
            AP.log(f"KIT-WAVE DEDUP OFF RELEASE {die}/{rec['item']}: was {rec.get('status')} behind {owner}; kit dedup removed (r703/r705), launches on its own inputs")
            (st.get("dedup_released") or {}).pop(f"{die}|{rec['item']}", None)
            if group and h:
                ident_release(group, h)
            items.pop(key, None)
            continue
        if orec is not None and (orec.get("status") in ("FAIL", "CANCELLED") or orec.get("q_status") in ("FAIL", "CANCELLED")):
            # FABLE-FLOW-0015 (c): 23 S81 col members were released every tick (12,776 DEDUP RELEASE lines): the owner failed on a stored fail key, the member
            # relaunched into the same kit identity, got DEDUP again and was released again.  Terminal state DEDUP-WAIT until the owner's key can change.
            blocked, _why, _chg = fail_key_gate(cfg, st, die, owner, orec.get("block_sha"))
            if blocked:
                if rec.get("status") != "DEDUP-WAIT":
                    rec.update(status="DEDUP-WAIT", updated=now, reason=f"DEDUP-WAIT: owner {owner} failed and its fail key stands ({_why[:160]}); waits for an input change")
                    AP.log(f"KIT-WAVE DEDUP-WAIT {die}/{rec['item']}: owner {owner} failed with a standing fail key; no release until its inputs change")
                continue
        if orec is None or orec.get("status") in ("FAIL", "CANCELLED") or orec.get("q_status") in ("FAIL", "CANCELLED"):
            sig = f"{(orec or {}).get('status')}/{(orec or {}).get('q_status')}/{(orec or {}).get('attempt')}"
            led = st.setdefault("dedup_released", {})
            if dedup_owner_not_a_verdict(orec):                  # WAVE-PILOT-FIX 11-18: a CANCELLED / INFRA owner is no design verdict: no hold, release at once
                led.pop(f"{die}|{rec['item']}", None)
                if group and h:
                    ident_release(group, h)
                items.pop(key, None)
                continue
            if (led.get(f"{die}|{rec['item']}") or {}).get("sig") != sig:        # FABLE-FLOW-0445 #5: logged once per owner state, not every tick
                AP.log(f"KIT-WAVE DEDUP RELEASE {die}/{rec['item']}: owner {owner} did not sign off (status "
                       f"{(orec or {}).get('status')}/{(orec or {}).get('q_status')}); relaunches on the normal path")
            led[f"{die}|{rec['item']}"] = {"sig": sig, "owner": owner, "t": now}
            if group and h:
                ident_release(group, h)
            items.pop(key, None)
            continue
        if orec.get("q_status") not in SIGNED_Q and orec.get("status") not in SIGNED_Q:
            continue
        j = jobs.get(orec.get("q_id")) or {}
        cid = f"dd{str(orec.get('q_id') or '')[:8]}-{hashlib.sha1(rec['item'].encode()).hexdigest()[:6]}"
        if not AP.DRY and j:
            j2 = dict(j, id=cid, type=rec["item"])
            so = j.get("signoff") if isinstance(j.get("signoff"), dict) else {}
            if j.get("status") == "ARCHIVED" and j.get("src_commit") and j.get("flow_tag"):
                AP.tsv_append("signed.tsv", cid, [j2["die"], j2["type"], j2.get("src", ""), j2.get("host", ""), j2.get("kit", ""),
                                                   j2.get("archive", ""), j2.get("mirror", ""), so.get("tt_wns"), so.get("ff_wns"),
                                                   j2.get("lane", ""), j2["src_commit"], j2["flow_tag"]])
            elif j.get("status") == "SIGNED-UNVERSIONED":
                AP.tsv_append("unversioned.tsv", cid, [j2["die"], j2["type"], j2.get("src", ""), j2.get("host", ""), j2.get("kit", ""),
                                                        j2.get("archive", ""), so.get("tt_wns"), so.get("ff_wns"),
                                                        f"DEDUP of {owner}", j2.get("lane", "")])
            p = Path(ap_dir) / DEDUP_MEMBERS
            new = not p.exists()
            with open(p, "a") as f:
                if new:
                    f.write("time\tdie\tmember\towner\towner_job\tcredit_id\tkit_identity\n")
                f.write(f"{now_s()}\t{die}\t{rec['item']}\t{owner}\t{orec.get('q_id')}\t{cid}\t{(h or '')[:16]}\n")
        rec.update(status="DEDUP-CREDITED", q_status="SIGNED-LINKED", credited_via=orec.get("q_id"), credit_id=cid, updated=now,
                   reason=f"DEDUP-CREDITED: kit identical to {owner}; signed record {orec.get('q_id')} credited")
        notices.setdefault(die, []).append(f"{rec['item']} DEDUP-CREDITED via {owner}")
        AP.log(f"KIT-WAVE DEDUP CREDIT {die}/{rec['item']} <- {owner} job {orec.get('q_id')} ({cid})")
    def _enq_hash(r):                                    # hash of an enqueued member's kit on its host
        host, _, kp = str(r.get("kit") or "").partition(":")
        if not kp:
            return ""
        rc, o, _ = AP.sh(remote_argv(host, AP.HUB_NAME, f"python3 -I -c {shlex.quote(KIT_HASH_PY)} {shlex.quote(kp)} {shlex.quote(r['item'])}"), timeout=120)
        m = re.search(r"KW_KIT_HASH ([0-9a-f]{64})", o or "")
        return m.group(1) if m else ""
    try:
        dedup_enqueued(AP, cfg, st, notices, jobs, _enq_hash)
    except Exception as e:
        AP.log(f"KIT-WAVE DEDUP enqueued pass skipped: {type(e).__name__}: {e}")
    # in-flight legacy duplicates: running wave rows of one group, no identity file yet
    probes = 0
    groups = {}
    for key, rec in items.items():
        if rec.get("status") in ("RUNNING", "LAUNCHING") and not rec.get("arm"):
            g = dedup_group(cfg, rec.get("die"), rec.get("item"))
            if g and ((cfg.get("dies") or {}).get(rec["die"]) or {}).get("kit_dedup_cancel", True) is not False:
                groups.setdefault(g, []).append(rec)
    for g, recs in groups.items():
        if len(recs) < 2 or probes >= 8:
            continue
        recs.sort(key=lambda r: float(r.get("started") or 0))
        keeper = recs[0]                                  # the most advanced running member (started first)

        def khash(r):
            try:
                sp = json.loads((Path(r["dir"]) / "spec.json").read_text())
            except (OSError, ValueError, KeyError):
                return ""
            Kp = f"{sp['work']}/gen/{r['item']}"
            rc, o, _ = AP.sh(remote_argv(sp.get("gen_host"), AP.HUB_NAME, f"python3 -I -c {shlex.quote(KIT_HASH_PY)} {shlex.quote(Kp)} {shlex.quote(r['item'])}"), timeout=120)
            m = re.search(r"KW_KIT_HASH ([0-9a-f]{64})", o or "")
            return m.group(1) if m else ""
        kh = khash(keeper)
        probes += 1
        if not kh:
            continue
        for r in recs[1:]:
            if probes >= 8:
                break
            probes += 1
            if khash(r) == kh:
                stop_attempt(AP, r)
                r.update(status="DEDUP", dedup_owner=keeper["item"], dedup_hash=kh, updated=now,
                         reason=f"DEDUP: in-flight duplicate of {keeper['item']} (same kit identity {kh[:12]}); stopped by exact unit")
                notices.setdefault(r["die"], []).append(f"{r['item']} DEDUP cancelled (same kit as {keeper['item']})")
                AP.log(f"KIT-WAVE DEDUP CANCEL {r['die']}/{r['item']}@{r.get('attempt')}: same kit identity as running {keeper['item']}")


def dedup_enqueued(AP, cfg, st, notices, jobs, hash_fn, max_probes=16):
    """WF-1 11-14 (COORD: 11 of 12 col_h9_r0_p6 pv variants, one identity, sat as queued route jobs): ENQUEUED members of a dedup
    group whose kit hashes like a sibling's are cancelled by the exact autopilot unit of their queue job (ap-<job>-a1: the ot-run
    client, queued or running; the route container under the attempt root too) and marked DEDUP -> credited when the kept member
    signs.  Kept per identity: the registry owner when it is among them, else the most advanced (running before queued, then
    earliest).  hash_fn(rec) -> kit hash or ''.  Returns the number cancelled."""
    items = st.get("items") or {}
    groups = {}
    for rec in items.values():
        if rec.get("status") != "ENQUEUED" or rec.get("q_status") in ("SIGNED", "FAIL", "CANCELLED", "SIGNED-LINKED"):
            continue
        g = dedup_group(cfg, rec.get("die"), rec.get("item"))
        if g and ((cfg.get("dies") or {}).get(rec["die"]) or {}).get("kit_dedup_cancel", True) is not False and rec.get("kit"):
            groups.setdefault(g, []).append(rec)
    try:
        reg = json.loads(Path(IDENT_FILE).read_text())
    except (OSError, ValueError):
        reg = {}
    n = probes = 0
    for g, recs in groups.items():
        if len(recs) < 2:
            continue
        byh = {}
        for r in recs:
            h = r.get("kit_hash")
            if not h and probes < max_probes:
                probes += 1
                h = hash_fn(r) or ""
                if h:
                    r["kit_hash"] = h
            if h:
                byh.setdefault(h, []).append(r)
        for h, rs in byh.items():
            if len(rs) < 2:
                continue
            own = (reg.get(f"{g}|{h}") or {}).get("owner")
            rs.sort(key=lambda r: (r.get("item") != own, r.get("q_status") != "RUNNING", float(r.get("started") or 0)))
            keeper = rs[0]
            for r in rs[1:]:
                j = own_job(r, jobs)
                units = [j.get("unit") or (f"ap-{r['q_id']}-a1" if r.get("q_id") else None)]
                if not AP.DRY:
                    for u in units:
                        if u:
                            AP.sh(["systemctl", "--user", "stop", u], timeout=180)
                    root = attempt_root(r)
                    if root:
                        WJ.stop_on_fleet(AP.sh, AP.HUB_NAME, [root])
                r.update(status="DEDUP", dedup_owner=keeper["item"], dedup_hash=h, updated=time.time(),
                         reason=f"DEDUP: enqueued duplicate of {keeper['item']} (same kit identity {h[:12]}); queue job "
                                f"{r.get('q_id')} stopped by exact unit {units[0]}")
                notices.setdefault(r["die"], []).append(f"{r['item']} DEDUP: queued route job stopped (same kit as {keeper['item']})")
                AP.log(f"KIT-WAVE DEDUP CANCEL-ENQUEUED {r['die']}/{r['item']}@{r.get('attempt')} job {r.get('q_id')} unit {units[0]}: "
                       f"same kit identity {h[:12]} as {keeper['item']}")
                n += 1
    return n


def stop_attempt(AP, rec):
    """stop an attempt by its exact units (wave unit + PLACE service) and the containers under its attempt root"""
    units = [rec.get("unit")]
    try:
        units.append(json.loads((Path(rec["dir"]) / "place_service.json").read_text())["unit"])
    except (OSError, ValueError, KeyError, TypeError):
        pass
    for u in units:
        if u:
            AP.sh(["systemctl", "--user", "stop", u], timeout=180)
    r = attempt_root(rec)
    if r:
        WJ.stop_on_fleet(AP.sh, AP.HUB_NAME, [r])


# WF-1 11-14 (COORD friction 5, structural): a plan adds hard cores and nothing built them: every parent type parked as WAIT-CHILD
# (prov_require_cands) for days (QC s29q103S: 29 cores without a view, about 30 types).  Now a WAIT-CHILD records the child
# modules it waits on (state wait_child[die][module]); select() turns each one that has no OWNERS row, no running build and no
# die-owner hold into a kind=core wave row (the same gen / place / sign-off path as any plan core); the signed DRC-0 sign-off is a
# prov_sources candidate, so the parents release by themselves.  Die options: auto_core_build false = off, auto_core_hold [modules]
# = being built by hand (never requested), auto_core_min_wait_h (default 0.5) = how long a module waits before the first request.
CORE_INFLIGHT_STATUS = ("RUNNING", "QUEUED", "ROUTING", "WAIT-GEOM", "WAIT-CANARY", "ENQUEUED", "SUBMITTED")


def core_in_flight(jobs, die, module):
    """an autopilot queue job of the die that builds `module` (type = module or <module>__v<sha12>) and has not finished"""
    for j in (jobs or {}).values():
        if j.get("die") != die:
            continue
        if prov_job_module(j, {module}) and (str(j.get("status")) in CORE_INFLIGHT_STATUS or str(j.get("status")).startswith("REVIEW-")):
            return j.get("id") or True
    return None


def note_wait_child(AP, st, die, parent, modules):
    """record the child modules a WAIT-CHILD parent waits on (called by launch)"""
    wc = st.setdefault("wait_child", {}).setdefault(die, {})
    now = time.time()
    for m in modules:
        e = wc.setdefault(m, {"first": now, "parents": []})
        e["seen"] = now
        if parent not in e["parents"]:
            e["parents"] = (e["parents"] + [parent])[-60:]


def auto_core_rows(cfg, state, die, d, rows, plan_types):
    """kind=core rows for the WAIT-CHILD modules of this die that nothing builds yet (see above)"""
    if d.get("auto_core_build", True) is False or plan_types is None:
        return []
    wc = (state.get("wait_child") or {}).get(die) or {}
    if not wc:
        return []
    known = {r["item"] for r in rows if r["die"] == die}
    hold = set(d.get("auto_core_hold") or [])
    min_wait = float(d.get("auto_core_min_wait_h", 0.5)) * 3600.0
    now = time.time()
    out = []
    for m, e in sorted(wc.items()):
        if now - float(e.get("seen") or 0) > 3 * 3600 or now - float(e.get("first") or now) < min_wait:
            continue                         # no longer waited on, or not waiting long enough to need a request
        if m in known or m in hold or any(fnmatch.fnmatchcase(m, pat) for pat in (d.get("hold_items") or {})):
            continue
        if not any(x == m or core_module(x) == m for x in plan_types):
            continue                         # the plan of record has no such core: nothing to build
        out.append(dict(die=die, item=m, kind="core", state="NEEDS-KIT", owner="KIT-WAVE", live_job="none", last_activity="",
                        next_step="auto core build (WAIT-CHILD)", evidence=d.get("plan", ""), default_owner=d.get("owner_lane", ""),
                        replicas="1", members=m, _auto_core=True))
    return out


WAIT_CHILD_SUMMARY_S = 3600


def wait_child_summary(AP, cfg, st):
    """one queue line per die and hour: parents waiting on child cores without a view, and what happens to each core"""
    wc_all = st.get("wait_child") or {}
    posted = st.setdefault("wait_child_posted", {})
    now = time.time()
    try:
        jobs = json.loads((Path(AP.AP_DIR) / "state.json").read_text()).get("jobs") or {}
    except (OSError, ValueError):
        jobs = {}
    for die, wc in sorted(wc_all.items()):
        live = {m: e for m, e in wc.items() if now - float(e.get("seen") or 0) <= 3 * 3600}
        for m in [m for m in wc if m not in live]:
            wc.pop(m, None)
        if not live or now - float(posted.get(die) or 0) < WAIT_CHILD_SUMMARY_S:
            continue
        d = (cfg.get("dies") or {}).get(die) or {}
        hold = set(d.get("auto_core_hold") or [])
        items = st.get("items") or {}
        cats = {"building": [], "wave-queued": [], "held-by-hand": [], "requested": [], "waiting": []}
        for m, e in sorted(live.items()):
            rec = next((r for r in items.values() if r.get("die") == die and core_module(r.get("item")) == m
                        and r.get("status") in ("RUNNING", "LAUNCHING", "ENQUEUED", "ROUTE-HELD")), None)
            if rec:
                cats["wave-queued"].append(m)
            elif core_in_flight(jobs, die, m):
                cats["building"].append(m)
            elif m in hold:
                cats["held-by-hand"].append(m)
            elif d.get("auto_core_build", True) is not False and now - float(e.get("first") or now) >= float(d.get("auto_core_min_wait_h", 0.5)) * 3600:
                cats["requested"].append(m)
            else:
                cats["waiting"].append(m)
        parents = sorted({x for e in live.values() for x in e.get("parents", [])})
        posted[die] = now
        if AP.DRY:
            continue
        AP.coord_append("lanes/COORD-REVIEW-QUEUE.md",
                        f"- {now_s()} STATE [KIT-WAVE -> COORD, {d.get('owner_lane', die + ' owner')}] WAIT-CHILD {die}: {len(parents)} parent type(s) "
                        f"wait on {len(live)} child core(s) without a routed view: " + "; ".join(
                            f"{k} {len(v)} ({' '.join(v[:12])}{' ...' if len(v) > 12 else ''})" for k, v in cats.items() if v)
                        + ". requested = the wave builds it as a core row; building = an autopilot job already runs it (no second build); "
                          "held-by-hand = dies.%s.auto_core_hold." % die)


_LIVE_PRIV_CACHE = {"t": 0.0, "txt": ""}


def _live_private_job(item):
    """KIT-OPS-4 11-14 (COORD/OWNER parallel forms, first pass wins): a coord mention alone is not a claim.  A lane defers the wave
    only while it has a LIVE private job for the item: an ot-run / ot-job / docker process on this hub whose command line names the
    item outside the wave's own kit-wave dirs.  On a ps failure the old behaviour (defer) stands."""
    try:
        if time.time() - _LIVE_PRIV_CACHE["t"] > 60:
            out = subprocess.run(["ps", "-eo", "args"], capture_output=True, text=True, timeout=20).stdout
            _LIVE_PRIV_CACHE["txt"] = "\n".join(l for l in out.splitlines()
                                                 if ("ot-run" in l or "ot-job" in l or "ot-heavy" in l or "docker" in l)
                                                 and "/kit-wave/" not in l)
            _LIVE_PRIV_CACHE["t"] = time.time()
        return item in _LIVE_PRIV_CACHE["txt"]
    except Exception:
        return True


def only_items_has(d, item):
    oi = d.get("only_items")
    return not isinstance(oi, (list, tuple, set)) or item in oi or any(item.startswith(x + "__") for x in oi)


SIGNED_Q = ("SIGNED", "SIGNED-LINKED")


def signed_block_index(state, die):
    """OWNER r711: {item: {block sha[:12]}} of the rows of `die` the queue signed off (a SIGNED record on that plan block)"""
    idx = {}
    for r in (state.get("items") or {}).values():
        if r.get("die") == die and r.get("q_status") in SIGNED_Q and r.get("block_sha"):
            idx.setdefault(r.get("item"), set()).add(str(r["block_sha"])[:12])
    return idx


def is_superseded_signed(idx, item, block):
    """a SIGNED record exists on another plan block of the item and none on the block in question (superseded-signed)"""
    signed = idx.get(item)
    return bool(signed) and bool(block) and str(block)[:12] not in signed


def superseded_signed_items(cfg, st):
    """{die: [items]}: items of the current plan of record whose only SIGNED records sit on older plan blocks (per-die count for the r711 post)"""
    out = {}
    cb = current_blocks(cfg, st)
    for die, blocks in cb.items():
        idx = signed_block_index(st, die)
        mine = sorted(i for i, b in blocks.items() if is_superseded_signed(idx, i, b))
        if mine:
            out[die] = mine
    return out


def defer_resign(AP, st, per_die, cfg):
    """OWNER r711 (global, after every die's picks are known): superseded-signed picks (tag _resign) launch only when NO other pick of any die is eligible this pass (spare capacity);
    otherwise they are dropped from this pass and logged once per item and plan block (DEFER-RESIGN <die> <item>).  -> per_die"""
    others = any(not r.get("_resign") for q in per_die for _, r in q)
    if others:
        logged = st.setdefault("defer_resign_logged", {})
        for q in per_die:
            for die, r in q:
                if r.get("_resign"):
                    k = f"{die}|{r['item']}|b{str(r.get('block_sha') or '')[:12]}"
                    if k not in logged:
                        logged[k] = time.time()
                        (AP.log if AP else log)(f"KIT-WAVE DEFER-RESIGN {die} {r['item']}")
        return [[(die, r) for die, r in q if not r.get("_resign")] for q in per_die]
    return per_die


def retire_resign_unstarted(AP, cfg, st):
    """OWNER r711: an ENQUEUED row of a superseded-signed type whose queue job has not started is retired (CANCELLED SUPERSEDED, withdrawn) while the plan is not frozen; RUNNING rows finish.
    stops_off dies only.  -> number retired"""
    n = 0
    sidx = {}
    for key, r in (st.get("items") or {}).items():
        die = r.get("die")
        d = (cfg.get("dies") or {}).get(die) or {}
        if r.get("status") != "ENQUEUED" or r.get("q_status") in SIGNED_Q or d.get("plan_frozen") or not FG.stops_off_die(cfg, die):
            continue
        if str(r.get("q_status") or "").upper() not in ("QUEUED", "STARTING", "WAITING", "WAIT-GEOM", ""):
            continue
        if die not in sidx:
            sidx[die] = signed_block_index(st, die)
        if not is_superseded_signed(sidx[die], r.get("item"), r.get("block_sha")):
            continue
        note = ""
        if r.get("kit") and not AP.DRY and str(r.get("q_status") or "").upper() in ("QUEUED", "STARTING", "WAITING", "WAIT-GEOM"):
            note = " " + grt_arm_withdraw(AP, cfg, r, "superseded-signed, plan not frozen (r711)")
        r.update(status="CANCELLED", **{"class": "SUPERSEDED"}, retire="resign-defer", updated=time.time(),
                 reason=f"SUPERSEDED: not started (queue {r.get('q_status') or '-'}); the type is signed on an older plan block and runs only on spare capacity until the plan is frozen (OWNER r711){note}"[:300])
        AP.log(f"KIT-WAVE RETIRE-RESIGN {die}/{r.get('item')}@{r.get('attempt')} not started{note}")
        n += 1
    return n


PLAN_ROW_EXCLUDE = ("ot_sram_*", "ot_rom_*", "ot_regfile_*")      # generated memory / ROM macro masters: no kit of their own (die option plan_row_exclude replaces the list)


_FAM_TAIL = re.compile(r"(_t\d+|_v\d+[a-z]*|_p\d+|_n\d+|_[we]\d+)$")


def family_key(item):
    """OWNER 11-20 (#8, FABLE-CONVERGE-0215 move 3): the family of a wave type = its generator family / template: the name before the first '__' (class / param-variant suffixes
    __cl<hash>, __pv<hash>, __t<n>), minus one trailing instance token (_t12, _v3n, _p4, _n9, _e2).  col_h9_r1__t1__cl..__pv.. -> col_h9_r1; ot_s81sl_leaf__t56 -> ot_s81sl_leaf"""
    head = str(item).split("__")[0]
    return _FAM_TAIL.sub("", head) or head


FAMILY_TABLE_PATH = os.environ.get("OT_FAMILY_TABLE") or os.path.expanduser("~/coord/lanes/handoff/FABLE-SUPERSET-0415-classes.json")
FAMILY_TABLE_DIE = {"s81": "s81", "qwen_compute": "qc", "qwen_kvsys": "kv"}
_FAMILY_CACHE = {}


def landing_variants(classes_path):
    """FABLE-SUPERSET 10.6: the landing-variant groups of the S81 col_h9_r1 / col_h9_r2 classes from the unify file next to the classes file (role_rows: member -> pins, edges, reset)
    -> {member: "s81:<class>:v<k>"}; variants numbered by size (largest first, then signature).  Missing or unreadable -> {}"""
    up = os.environ.get("OT_FAMILY_UNIFY") or os.path.join(os.path.dirname(classes_path), "FABLE-SUPERSET-0415-unify.json")
    out = {}
    try:
        for e in json.load(open(up)).get("classes") or []:
            if e.get("die") != "s81" or str(e.get("cls")) not in ("col_h9_r1", "col_h9_r2"):
                continue
            rows = [r for r in (e.get("role_rows") or []) if isinstance(r, dict) and r.get("member")]
            sig = {r["member"]: json.dumps([r.get("pins"), r.get("edges"), r.get("reset")], sort_keys=True) for r in rows}
            order = sorted(set(sig.values()), key=lambda g: (-sum(1 for v in sig.values() if v == g), g))
            for m, g in sig.items():
                out[m] = f"s81:{e['cls']}:v{order.index(g) + 1}"
    except (OSError, ValueError, TypeError, AttributeError):
        return {}
    return out


def family_table(path=None):
    """COORD 11-20: the real family table (FABLE-SUPERSET-0415-classes.json), cached by mtime -> {die: {"types": {type: class id}, "stems": [stem, ...] longest first}}.  s81: the explicit member lists of the
    leaf / station / serdes / kvleaf class sets (leaf_cap7786 is an alternative cut of the same leaves and is ignored); qc / kv: the per-stem lists (a type belongs to the longest stem it equals or
    extends with '_' / '__').  Unreadable -> {} (callers fall back to the name key)"""
    path = path or FAMILY_TABLE_PATH
    try:
        mt = os.stat(path).st_mtime
    except OSError:
        return {}
    up = os.environ.get("OT_FAMILY_UNIFY") or os.path.join(os.path.dirname(path), "FABLE-SUPERSET-0415-unify.json")
    try:
        mt = (mt, os.stat(up).st_mtime)
    except OSError:
        pass
    c = _FAMILY_CACHE.get(path)
    if c and c[0] == mt:
        return c[1]
    out = {}
    try:
        d = json.load(open(path))
        types = {}
        s81 = d.get("s81") or {}
        ng = any(str(k).endswith("_nogrowth_j4e") for k in s81)            # COORD 11-20: the no-growth cut (33 leaf classes at the 4,500-bit cap) replaces the growth cut
        for sec, v in s81.items():
            if not isinstance(v, dict) or sec in ("leaf_cap7786", "leaf_site_slack_j4e") or (ng and not str(sec).endswith("_nogrowth_j4e")):
                continue
            cls_ = v.get("classes")
            if cls_ is None and isinstance(v.get("by_cap_bits"), dict):          # leaf_nogrowth_j4e: {cap_bits: [classes]}: the 4,500-bit cap (33 classes), COORD 11-20
                cls_ = v["by_cap_bits"].get("4500") or []
            for cl in cls_ or []:
                for m in cl.get("members") or []:
                    types.setdefault(str(m[0]), f"s81:{cl.get('id')}")
        for m, cid in landing_variants(path).items():                       # COORD 11-20: col_h9_r1 / r2 -> one family per landing variant (FABLE-SUPERSET 10.6), over the whole-class entry
            types[m] = cid
        out["s81"] = {"types": types, "stems": []}
        for key in ("qc", "kv"):
            stems = sorted({str(e.get("stem")) for e in (d.get(key) or []) if isinstance(e, dict) and e.get("stem")}, key=lambda x: (-len(x), x))
            out[key] = {"types": {}, "stems": stems}
    except (OSError, ValueError, TypeError, AttributeError):
        out = {}
    _FAMILY_CACHE[path] = (mt, out)
    return out


def family_of(die, item, table=None):
    """the family of a type: the real class (table) when the type is in it, else the name key"""
    t = (table if table is not None else family_table()).get(FAMILY_TABLE_DIE.get(die, ""))
    if t:
        if item in t["types"]:
            return t["types"][item]
        for stem in t["stems"]:
            if item == stem or item.startswith(stem + "__") or item.startswith(stem + "_"):
                return f"{FAMILY_TABLE_DIE[die]}:{stem}"
    return family_key(item)


def family_plan(cfg, st, die, picks):
    """OWNER 11-20 (#8): representatives first.  Per die, the picked type rows are grouped by family_key; ONE representative per family (the most-failed type, then the name) launches at
    high priority (ot-run --crit via spec crit); siblings launch after every representative (spare capacity, default priority).  When the representative of a family FAILED on the current
    event with a design / flow class (not INFRA) its siblings are HELD (they stay in the queue) until the representative has a newer attempt (the family's fix landed) or signs.
    Old-plan kits already running are never touched.  -> (ordered picks, {item: hold reason}, {"families": n, "reps": [..], "siblings": n})"""
    d = cfg["dies"][die]
    fails = collections.Counter(r.get("item") for r in (st.get("items") or {}).values() if r.get("die") == die and r.get("status") == "FAIL")
    fam = collections.defaultdict(list)
    for r in picks:
        if (r.get("kind") or "type") == "type":
            fam[family_of(die, r["item"])].append(r)
    reps, held, sibs = {}, {}, set()
    ev = d.get("event")
    for k, members in fam.items():
        rep_row = max(members, key=lambda r: (fails.get(r["item"], 0), r["item"]))
        _named = next((r for r in members if r["item"] == (d.get("family_reps") or {}).get(k)), None)
        if _named is not None:                       # FLEET-WATCH-R4 11-21: a family lane's own representative (die config family_reps {family: item}) wins
            rep_row = _named
        reps[k] = rep_row["item"]
        for r in members:
            if r is rep_row:
                continue
            sibs.add(r["item"])
        # the representative's latest record on the current event
        recs = [x for x in (st.get("items") or {}).values() if x.get("die") == die and x.get("item") == rep_row["item"] and str(x.get("event") or "") == str(ev or "")]
        last = max(recs, key=lambda x: (float(x.get("started") or 0), int(x.get("attempt") or 0)), default=None)
        if last and last.get("status") == "FAIL" and not is_infra_fail(last):
            for r in members:
                if r is not rep_row:
                    held[r["item"]] = f"FAMILY-HOLD {k}: representative {rep_row['item']} failed ({last.get('class') or '?'} @{last.get('stage') or '?'}) on this plan; its siblings wait for the family fix"
    # FLEET-WATCH-R4 11-21 (FABLE-FLOW-0200 b, OWNER "reps first"): a family with a type estimated over the 400k cell cap admits ONE representative; its siblings are held (SIBLING-BIG)
    # until a representative of the family has PASSED (CTS-clean geom) on the current event.  A representative already running / queued (not a pick) holds every pick of the family.
    # Die opt-out: big_reps_first false.
    if d.get("big_reps_first") is not False:
        _big = {t for t, f in (d.get("_plan_flags") or {}).items() if f == "split"}
        _rows = list((st.get("items") or {}).values())
        for k, members in fam.items():
            _cur = [x for x in _rows if x.get("die") == die and str(x.get("event") or "") == str(ev or "") and family_of(die, x.get("item") or "") == k]
            if not any(m["item"] in _big for m in members) and not any(x.get("item") in _big for x in _cur):
                continue
            if any(x.get("status") in ("PASS", "ROUTE-HELD") for x in _cur):
                continue
            _alive = [x for x in _cur if x.get("status") in ("RUNNING", "LAUNCHING", "ENQUEUED", "RETRY-INFRA") and x.get("item") not in {m["item"] for m in members}]
            for r in members:
                if (_alive or r["item"] != reps[k]) and r["item"] not in held:
                    held[r["item"]] = (f"SIBLING-BIG {k}: representative {_alive[0]['item'] if _alive else reps[k]} (family has a type over {SPLIT_CELLS} cells) has not passed CTS yet; "
                                       f"siblings wait")
    rep_set = set(reps.values())
    ordered = [r for r in picks if r["item"] in rep_set and r["item"] not in held] + [r for r in picks if r["item"] not in rep_set and r["item"] not in held]
    meta = {"families": len(fam), "reps": sorted(rep_set), "siblings": len(sibs), "held": len(held)}
    return ordered, held, meta


def plan_type_rows(cfg, die, d, rows, plan_types):
    """COORD 11-19 (HEAD-CROSSING: variant types hd_ctl_e, hd_spn_eshim_rx, hd_st_n3_turn ... 18 rows never relaunched on a new event, the HEAD builder took types only from the ownership table
    that lists base names): under stops_off (not hbm) EVERY type of the current plan (partition_types) is a wave row, whether or not OWNERS names it.  Not rows already known (an OWNERS row, or a
    parent that expands into <parent>__<class> variants), not plan cores, not template members (they share a representative's kit).  The synthesized rows are exempt from the owner's only_items
    list (_plan_row).  Die option rows_from_plan false opts out.  -> [row]"""
    if not isinstance(plan_types, dict) or d.get("rows_from_plan") is False or not FG.stops_off_die(cfg, die):
        return []
    known = {r["item"] for r in rows if r["die"] == die}
    cores = set(d.get("plan_core_items") or [])
    part = d.get("_plan_part_types")                    # the plan's real partition types: names / blocks that are not partition types (kv_cland_*, bound children, macros) get no row
    out = []
    for item in sorted(plan_types):
        if item in known or item in cores or any(item.startswith(k + "__") for k in known):
            continue
        if not part or item not in part:                 # FLOW-2155 class 2: ONLY the plan's partition-type table decides; no table read (probe failed) = no synthesized rows, never a name guess
            continue
        if template_member(d, item):
            continue
        # 20:31 first tick: HEAD synthesized rows for the generated memory macros (ot_sram_* : 8 FLOW kit_rtl fails): a macro master is a plan block with no kit of its own
        if any(fnmatch.fnmatchcase(item, g) for g in (d.get("plan_row_exclude") or PLAN_ROW_EXCLUDE)):
            continue
        out.append(dict(die=die, item=item, kind="type", state="NEEDS-KIT", owner="KIT-WAVE", live_job="none", last_activity="",
                        next_step="plan type with no OWNERS row (rows_from_plan)", evidence=d.get("plan", ""),
                        default_owner=d.get("owner_lane", ""), replicas="1", members="", _plan_row=True))
    d["_plan_rows_n"] = len(out)
    return out


def select(rows, cfg, die, state, plan_types=None):
    """-> (picked rows in launch order, {reason: [items]})"""
    d = cfg["dies"][die]
    ev = d["event"]
    states = set(opt(cfg, die, "take_states"))
    # WF-1 11-14 (EXPERT-REVIEW-6 #7): take_states "*" (the default) = every OWNERS state except RETIRED, so a row never drops out
    # of selection because its state is not on a hand list (t40 rows lost on WAIT-PARENT).  An explicit list still narrows.
    take_all = "*" in states
    only_plan = isinstance(d.get("only_items"), str) or d.get("only_items_from_plan") is True
    if only_plan:                                    # only_items "plan": derived = the plan's items minus hold_items, no hand list
        d = dict(d, only_items=None)
    kinds = set(opt(cfg, die, "kinds"))
    claim_m = float(opt(cfg, die, "live_claim_h")) * 60
    generic = set(opt(cfg, die, "generic_owner_labels") or [])
    retry = set(d.get("retry") or [])                 # "item@attempt": COORD released that failed attempt
    retry = minimal_auto_retry(state, die, ev, d, retry, cfg=cfg)   # R-MINIMAL: + one automatic retry per failed item
    skip = {}
    picked = []
    orphans = no_row_source(rows, d, die, plan_types)
    if orphans:
        skip[NO_ROW_SOURCE] = orphans                   # plan_dies() logs it loudly every tick
    not_only = plan_core_not_in_only(d, plan_types)
    if not_only:
        skip[PLAN_CORE_NOT_IN_ONLY] = not_only          # plan_dies() logs it once per run (KIT-OPS-1)
    if (d.get("plan_items_from_allowlist") or d.get("plan_core_items")) and plan_types is not None:
        # Adopted plans may split types before the ownership census catches up.
        # Explicit die-owned allowlists select those real plan types; retain every
        # existing ownership/live-job claim and the normal retry/geometry gates.
        rows = list(rows)
        known = {r["item"] for r in rows if r["die"] == die}
        for item in (d.get("only_items") or []) if d.get("plan_items_from_allowlist") else []:
            # Existing parent rows already expand into these plan classes,
            # including their live-job claims; do not synthesize a second owner.
            if item in known or item not in plan_types or any(item.startswith(k + "__") for k in known):
                continue
            if item in (d.get("plan_core_items") or []):     # KW-FIX-45 11-11: a plan core is a kind=core row (below), never a type row
                continue
            rows.append(dict(die=die, item=item, kind="type", state="NEEDS-KIT",
                             owner="KIT-WAVE", live_job="none", last_activity="",
                             next_step="adopted plan allowlist", evidence=d.get("plan", ""),
                             default_owner=d.get("owner_lane", ""), replicas="1", members=""))
        # A plan-of-record hard core the ownership census cannot see yet (OWNERS reads the older HBM plan): a kind=core
        # row for the names the die lists, and only those.
        for item in d.get("plan_core_items") or []:
            if item in known or item not in plan_types:
                continue
            rows.append(dict(die=die, item=item, kind="core", state="NEEDS-KIT",
                             owner="KIT-WAVE", live_job="none", last_activity="",
                             next_step="adopted plan core allowlist", evidence=d.get("plan", ""),
                             default_owner=d.get("owner_lane", ""), replicas="1", members=item))
    rows = list(rows) + plan_type_rows(cfg, die, d, rows, plan_types)                # COORD 11-19 (HEAD-CROSSING): every plan type gets a row
    rows = list(rows) + auto_core_rows(cfg, state, die, d, rows, plan_types)       # WF-1 11-14: WAIT-CHILD cores with no builder
    for r in rows:
        if r["die"] != die:
            continue
        why = None
        # Die owners may park a measured failing class while its structural fix
        # is built. Explicit holds only affect new picks; active jobs are intact.
        import fnmatch
        held = next((why for pat, why in (d.get("hold_items") or {}).items()
                     if fnmatch.fnmatchcase(r["item"], pat)), None)
        if held:
            skip.setdefault("die-owned hold: " + held, []).append(r["item"])
            continue
        blk = lambda t: plan_types.get(t) if isinstance(plan_types, dict) else None
        if counted_now(cfg, state, die, r["item"], blk(r["item"])):
            skip.setdefault("counted by the sign-off counter", []).append(r["item"])
            continue
        if template_member(d, r["item"]):
            skip.setdefault(TYPE_TEMPLATE_MEMBER, []).append(r["item"])
            continue
        rec = (state.get("items") or {}).get(item_key(die, ev, r["item"], blk(r["item"])))
        bw = blocked_why(cfg, state, die, r["item"], blk(r["item"]))
        if bw:
            skip.setdefault(bw.split(":", 1)[0] + ": same failure signature at the retry cap (kit_wave_blocked.tsv)", []).append(r["item"])
            continue
        only_retry = False
        if r["state"] not in states and not (take_all and r["state"] != "RETIRED"):
            # KW-RELAUNCH-1 11-05: the parent row of a class-split item carries the state of the wave's OWN running class
            # (ROUTING / QUEUED ...).  That hid every released retry of its sibling classes (S81 slice_station t29 / t40 /
            # t6: retry @6 / @8 / @9 set, never launched).  Such a parent still expands, but only into released retries.
            if (r["state"] in ("SIGNED", "SIGNED-UNVERSIONED") and plan_types is not None
                    and r["item"] not in plan_types and any(t.startswith(r["item"] + "__") for t in plan_types)):
                # The ownership row summarizes the base type. Check each current class's own signoff and holds below.
                pass
            elif not (str(r.get("owner", "")).startswith("KIT-WAVE") and _own_wave_unit(r)
                      and plan_types is not None and r["item"] not in plan_types
                      and any(x.split("@", 1)[0].startswith(r["item"] + "__") for x in retry)):
                # never silent: the SKIP line names the state
                if only_items_has(d, r["item"]):
                    skip.setdefault(f"SKIP state {r['state']} not in take_states", []).append(r["item"])
                continue
            else:
                only_retry = True
        if r["kind"] not in kinds:
            why = f"kind {r['kind']} not in wave"
        elif d.get("_cores_only") and r["kind"] != "core":
            why = "die clock not PASS: cores only (core_kit, 12.22 item 4)"
        elif rec and rec.get("status") in ("RUNNING", "LAUNCHING", "ROUTE-HELD"):
            why = "wave item in flight"
        elif prov_predecessor(d, die, state, r["item"], rec):
            why = ("PROV-RESIGN: the PROVISIONAL kit of this type re-signs (STA only, no re-route) on the signed child "
                   "views (KW-PROV-1)")
        elif not rec and signed_equivalent(cfg, state, die, r["item"]):
            why = "signed off on an equivalent plan block (same path-normalized block; a tree rename only moved the raw sha)"
        elif rec and rec.get("q_status") in ("SIGNED", "SIGNED-LINKED"):
            # SIGNED-TERMINAL-1115: a signed R-MINIMAL record on this plan block is terminal, flow tag or not, retry key or not
            why = "signed off on this plan block (terminal; a missing flow tag is bookkeeping, never a build)"
        elif rec and unclassified_hold(cfg, die, r, rec, retry):
            why = (f"UNCLASSIFIED: attempt {rec.get('attempt')} failed with an error no rule or OT_CLASS marker names ({str(rec.get('reason'))[:120]}); it gets ONE automatic relaunch once rt or the die tree "
                   f"changed, then stays FAIL as a NEEDS-LANE row (owners_sweep flag UNCLASSIFIED); a lane may classify it: kit_wave.py classify-fail --die {die} --item {r['item']} --class PLAN|FLOW|RTL|INFRA|STRUCTURAL")
        elif struct_stop_gate(None, cfg, state, die, r["item"], blk(r["item"])):
            why = struct_stop_gate(None, cfg, state, die, r["item"], blk(r["item"]))
        elif rec and FG.stops_off_die(cfg, die) and so_failed(rec) and f"{r['item']}@{rec.get('attempt')}" not in retry and so_same_input(cfg, die, r, rec):
            why = "SKIP-SAME-INPUT: full input hash equals the attempt that failed (rt sha, design snapshot, spec digest, env keys); any code / plan / env change releases it"
        elif rec and rec.get("status") == "ENQUEUED" and not (
                rec.get("q_status") == "FAIL" and (f"{r['item']}@{rec.get('attempt')}" in retry or (FG.stops_off_die(cfg, die) and so_failed(rec)))):
            # KIT-TRIAGE-1 11-01: a kit that FAILED in the autopilot queue (route / sign-off) stays ENQUEUED in the
            # wave; once a class fix lands, COORD (retry) or a merged kit_wave_pending.tsv row releases that attempt
            # and the wave builds a fresh kit (attempt + 1) on the current source -- the batch relaunch path
            why = "wave kit enqueued" + (" (queue FAIL; relaunch = retry item@attempt)" if rec.get("q_status") == "FAIL" else "")
        elif rec and rec.get("status") == "CANCELLED" and rec.get("volume") and (
                rec["volume"] in pilot_classes_state(d, die, state)[0]
                or pilot_fail_times(d, die, state, d.get("src_sha") or "").get(rec["volume"], 0.0) <= float(rec.get("started") or 0)):
            pass        # queued volume cancelled by a failed pilot: class now proven, or no class FAIL stands any more
        elif rec and is_wait_dep(rec) and not rec.get("provisional") and prov_item(d, r["item"]):
            pass        # KW-PROV-1: a gen-time WAIT-DEP stop (child view missing) relaunches on provisional child views
        elif rec and f"{r['item']}@{rec.get('attempt')}" not in retry and not (FG.stops_off_die(cfg, die) and (so_failed(rec) or stale_cancel(rec, d))):
            why = f"wave {rec.get('status')} {rec.get('class', '')} on this plan block (no blind retry)".replace("  ", " ")
        elif rec and not FG.stops_off_die(cfg, die) and needs_lane(cfg, state, die, r["item"], rec, r.get("parent_item"), r.get("kind")):
            why = NEEDS_LANE                         # WAVE-RECIPE-1: design FAIL, same kit inputs -> a lane, not a re-key
        elif rec and not FG.stops_off_die(cfg, die) and cfg.get("hold_unchanged") and not minimal_profile() and unchanged_fail(cfg, state, die, r["item"], rec, r.get("parent_item"), r.get("kind")):
            why = HOLD_UNCHANGED
        elif rec and not FG.stops_off_die(cfg, die) and cfg.get("form_gate", True) and not minimal_profile() and form_wait(cfg, state, die, r["item"], rec, r.get("parent_item"), r.get("kind")):
            why = WAIT_FORM
        elif rec and not FG.stops_off_die(cfg, die) and cfg.get("flow_repeat_gate", True) and not minimal_profile() and flow_repeat(cfg, state, die, r["item"], rec, r.get("parent_item"), r.get("kind")):
            why = FLOW_REPEAT
        elif r["live_job"] not in ("", "none") and not _own_wave_unit(r):
            why = "live job (another lane)"
        elif age_min(r["last_activity"]) is not None and age_min(r["last_activity"]) < claim_m \
                and not str(r["owner"]).startswith("KIT-WAVE") \
                and not (r["kind"] == "type" and r["owner"] in generic) \
                and _live_private_job(r["item"]):
            # a recent coord line by another lane naming the item is a claim; the wave's own notices never count
            # (any KIT-WAVE-<n> runner lane: the wave's lane name changes with each successor)
            why = f"lane activity < {claim_m / 60:g} h ({r['owner']})"
        elif plan_types is not None and r["item"] not in plan_types:
            # the plan of record may split an item into classes (<item>__cl<hash>): each class is one wave item
            if r["kind"] == "core":                  # AUTOBUILD-PIPE-2: per pin-table views of a core module
                mv = re.fullmatch(r"(.+)_([0-9a-f]{12})", r["item"])
                cls = (sorted(t for t in plan_types if t != r["item"] and core_module(t) == r["item"])
                       or ([f"{mv.group(1)}__v{mv.group(2)}"] if mv and f"{mv.group(1)}__v{mv.group(2)}" in plan_types else []))
            else:
                cls = sorted(t for t in plan_types if t.startswith(r["item"] + "__"))
            its = state.get("items") or {}
            blocked = [c for c in cls if plan_entry_block(d, c, r.get("kind"))]
            for c in blocked:
                skip.setdefault(plan_entry_block(d, c, r.get("kind")), []).append(c)
            for c in cls:                    # DIE-QC-63/KITS 11-02: hold_items naming a class hold that class
                hc = next((w for pat, w in (d.get("hold_items") or {}).items() if fnmatch.fnmatchcase(c, pat)), None)
                if hc and c not in blocked:
                    skip.setdefault("die-owned hold: " + hc, []).append(c)
                    blocked.append(c)
            for c in cls:
                if c not in blocked and counted_now(cfg, state, die, c, blk(c)):
                    skip.setdefault("counted by the sign-off counter", []).append(c)
                    blocked.append(c)
            for c in cls:
                if c not in blocked and template_member(d, c):
                    skip.setdefault(TYPE_TEMPLATE_MEMBER, []).append(c)
                    blocked.append(c)
            cls = [c for c in cls if c not in blocked]
            # KW-FIX-8 11-04: a class in flight is never picked again.  Without this a retry row naming the live attempt
            # relaunched a RUNNING class (QC 11:30: 12 classes launched twice in one pass, a2 then a3)
            cls_live = lambda c: (its.get(item_key(die, ev, c, blk(c))) or {}).get("status") in ("RUNNING", "LAUNCHING")
            released = lambda c: f"{c}@{(its.get(item_key(die, ev, c, blk(c))) or {}).get('attempt')}" in retry
            todo = [c for c in cls if not cls_live(c) and (not only_retry or released(c))
                    and (not its.get(item_key(die, ev, c, blk(c)))
                    or f"{c}@{its[item_key(die, ev, c, blk(c))].get('attempt')}" in retry
                    or (FG.stops_off_die(cfg, die) and stale_cancel(its[item_key(die, ev, c, blk(c))], d))
                    or (is_wait_dep(its[item_key(die, ev, c, blk(c))]) and not its[item_key(die, ev, c, blk(c))].get("provisional")
                        and prov_item(d, c)))]
            nlh = [c for c in todo if needs_lane(cfg, state, die, c, its.get(item_key(die, ev, c, blk(c))), r["item"], r.get("kind"))]
            if nlh:                                  # WAVE-RECIPE-1: design FAIL, same kit inputs -> a lane, not a re-key
                skip.setdefault(NEEDS_LANE, []).extend(nlh)
                todo = [c for c in todo if c not in nlh]
            if cfg.get("hold_unchanged"):
                same = [c for c in todo if unchanged_fail(cfg, state, die, c, its.get(item_key(die, ev, c, blk(c))), r["item"], r.get("kind"))]
                if same:
                    skip.setdefault(HOLD_UNCHANGED, []).extend(same)
                    todo = [c for c in todo if c not in same]
            capped = [c for c in todo if blocked_why(cfg, state, die, c, blk(c))]
            for c in capped:
                skip.setdefault(blocked_why(cfg, state, die, c, blk(c)).split(":", 1)[0]
                                + ": same failure signature at the retry cap (kit_wave_blocked.tsv)", []).append(c)
            todo = [c for c in todo if c not in capped]
            if cfg.get("flow_repeat_gate", True):
                rep = [c for c in todo if flow_repeat(cfg, state, die, c, its.get(item_key(die, ev, c, blk(c))), r["item"], r.get("kind"))]
                if rep:
                    skip.setdefault(FLOW_REPEAT, []).extend(rep)
                    todo = [c for c in todo if c not in rep]
            if not cls and blocked:
                continue
            if not cls:
                why = "not in plan of record"
            elif not todo:
                why = "all plan classes already in the wave"
            else:
                picked += [dict(r, item=c, parent_item=r["item"], block_sha=blk(c)) for c in todo]
                continue
        if not why:
            why = plan_entry_block(d, r["item"], r.get("kind"))
        if why:
            skip.setdefault(why, []).append(r["item"])
            continue
        picked.append(dict(r, block_sha=blk(r["item"])) if blk(r["item"]) else r)

    # An allowlist class may also be expanded from its OWNERS parent. Both
    # rows name one producer, not parallel forms; retain its first eligible row.
    unique, seen = [], set()
    for row in picked:
        key = item_key(die, ev, row["item"], row.get("block_sha"))
        if key in seen:
            skip.setdefault("same plan item already selected this tick", []).append(row["item"])
            continue
        seen.add(key)
        unique.append(row)
    picked = unique

    # Optional exact plan-class allowlist: enable safe canaries while other
    # classes await their die-owned hard views.  Never infer parameter variants.
    if d.get("only_items") is not None:
        allowed = set(d["only_items"])
        for r in picked:
            if r["item"] not in allowed and not r.get("_auto_core") and not r.get("_plan_row"):
                skip.setdefault("outside configured only_items", []).append(r["item"])
        picked = [r for r in picked if r["item"] in allowed or r.get("_auto_core") or r.get("_plan_row")]

    def rep(r):
        try:
            return int(r["replicas"])
        except ValueError:
            return 0
    unlocks = blocked_parents(d)
    if not d.get("plan_frozen"):                                  # OWNER r711: a type signed on an older plan block whose current block differs goes last; plan_frozen: normal priority, one batch
        _sidx = signed_block_index(state, die)
        for r in picked:
            if is_superseded_signed(_sidx, r["item"], r.get("block_sha")):
                r["_resign"] = True
    picked.sort(key=lambda r: (1 if r.get("_resign") else 0, -unlocks.get(core_module(r["item"]), 0), 0 if r["kind"] == "core" else 1, -rep(r), r["item"]))
    if not FG.stops_off_die(cfg, die):                           # OWNER 11-18: no pilot gating (hbm excluded)
        picked = pilot_gate(picked, skip, d, die, state)
    return picked, skip


# ------------------------------------------------------------------------------------------------ OWNER 12.27a pilot first
def pilot_key(d, die, item, kind="type"):
    """OWNER 12.27a die x kit class of a wave item: die config pilot_classes [{class, items: [glob ...]}] (COORD override)
    wins, else AUTOBUILD-PIPE-4 kit_class() '<die>|<kind>|<family>'"""
    import fnmatch
    for g in d.get("pilot_classes") or []:
        if isinstance(g, dict) and g.get("class") and any(fnmatch.fnmatchcase(item or "", pt) for pt in g.get("items") or []):
            return str(g["class"])
    return kit_class(die, item, kind)


def pilot_classes_state(d, die, state):
    """-> (signed classes, {class: in-flight count}) over every wave record of the die (all events): a class is proven
    once one of its kits SIGNED OFF through the queue (route + STA + LEC + GEOM) or COORD lists it in pilot_signed"""
    signed = set(d.get("pilot_signed") or [])
    live = {}
    for r in (state.get("items") or {}).values():
        if r.get("die") != die:
            continue
        c = pilot_key(d, die, r.get("item"), r.get("kind") or "type")
        if r.get("q_status") == "SIGNED":
            signed.add(c)
        elif r.get("status") in ("RUNNING", "LAUNCHING") or r.get("enqueue_pending") or (
                r.get("status") == "ENQUEUED" and r.get("q_status") not in ("FAIL", "SIGNED")):
            live[c] = live.get(c, 0) + 1
    return signed, live


def pilot_queue_mode(d, cfg=None):
    """OWNER 11-01 / COORD 05:3x (1): pilot_mode 'queue' (die or global) = unproven-class volume is queued behind its
    pilots instead of held out of the queue; anything else = the 12.27a hold"""
    return str(d.get("pilot_mode") or (cfg or {}).get("pilot_mode") or "") == "queue"


PILOT_PARALLEL = 3          # WAVE-PILOT-FIX 11-17: a class launches 3 pilots in parallel; the first sign-off releases the volume


def pilot_gate(picked, skip, d, die, state):
    """OWNER 12.27a PILOT FIRST (default on): a die x kit class with no signed-off kit has at most pilot_max (default 2,
    the 12.17 parallel variants) kits in flight, counting the ones already running; new launches past that wait.  Classes
    with a signed pilot keep full volume.  In-flight kits are never touched.  pilot_gate false only by COORD ruling."""
    if d.get("pilot_gate") is False:
        return picked
    cap = int(d.get("pilot_max", PILOT_PARALLEL))
    signed, live = pilot_classes_state(d, die, state)
    out, volume = [], []
    for r in picked:
        c = pilot_key(d, die, r["item"], r.get("kind") or "type")
        if c in signed:
            out.append(r)
        elif live.get(c, 0) < cap:
            live[c] = live.get(c, 0) + 1
            out.append(r)
        elif pilot_queue_mode(d):
            # OWNER 11-01 (COORD 05:3x (1)): volume of an unproven class is queued too, BEHIND every pilot of the tick
            # (launched last; ot-run waiters); cancel_class_volume() stops it while queued if a pilot of its class fails
            volume.append(dict(r, volume=c))
        else:
            skip.setdefault(f"PILOT-FIRST 12.27a: class {c} unproven, {cap} pilot(s) in flight", []).append(r["item"])
    out += volume
    return out


# ------------------------------------------------------------------------------------------------ capacity
def parse_otrun_status(text):
    """ot-run --status -> {host: {"admit": GB, "run": n, "load": x, "cores": n}}"""
    out = {}
    for part in (text or "").split("|"):
        # KIT-WAVE-10 10-31: a negative admission ("admits -29 GB") and fields between load and run ("waiters 1:200 GB")
        # must not drop the host (intel1 with a waiter vanished from the status, so the wave launched nothing there)
        m = re.search(r"([A-Za-z0-9_.-]+) admits (-?\d+) GB.*?load (\d+(?:\.\d+)?)/(\d+)\b.*?\brun (\d+)", part)
        if m:
            out[m.group(1)] = {"admit": int(m.group(2)), "load": float(m.group(3)), "cores": int(m.group(4)),
                               "run": int(m.group(5))}
            # KW-FIX-4 11-03 (COORD 12:1x FLEET): the queued demand 'waiters N:G GB' -> wait_n / wait_gb
            w = re.search(r"\bwaiters (\d+):(\d+) GB", part)
            if w:
                out[m.group(1)].update(wait_n=int(w.group(1)), wait_gb=int(w.group(2)))
            # KW-FIX-24 11-06 (COORD 16:2x): the scratch disk's free GB ('scratch 44 GB') -> scratch_gb (gen_disk_low)
            sc = re.search(r"\bscratch (\d+) GB", part)
            if sc:
                out[m.group(1)]["scratch_gb"] = int(sc.group(1))
    return out


SCRATCH_REFUSE_GB = {"localhost": 150}      # ot-run's per-host scratch floor (default 50, localhost 150): a host below it is refused for new jobs


FALL_MAX_GB_H = 50.0         # WAVE-DISK-CAP 11-17 (COORD / FLEET-OPS-R): a host whose scratch falls faster than this is not preferred


def place_prefer_live(pref, stt, mem_gb, hub="intel2", floors=None, fall=None, fall_max=FALL_MAX_GB_H):
    """FABLE-FLOW-1500 (E2): place_prefer is an ORDER from the config, but a host that ot-run would REFUSE right now (its scratch free is under its floor) or cannot admit the job
    is dropped from it, computed from the live status each time (intel1 at 21 GB, epyc10 at 44 GB and localhost kept being preferred and placing on them).  -> [host]"""
    floors = SCRATCH_REFUSE_GB if floors is None else floors
    out = []
    for h in pref:
        row = stt.get("localhost" if h == hub else h) or {}
        if row.get("admit", 0) < mem_gb:
            continue
        sc = row.get("scratch_gb")
        if sc is not None and sc < floors.get("localhost" if h == hub else h, 50):
            continue
        if fall and float((fall or {}).get(h) or (fall or {}).get("localhost" if h == hub else h) or 0) > fall_max:
            continue                                   # disk_eta shows a fall faster than fall_max GB/h
        out.append(h)
    return out


def inflight(state, die=None):
    return sum(1 for r in (state.get("items") or {}).values()
               if r.get("status") in ("RUNNING", "LAUNCHING") and (die is None or r.get("die") == die))


def capacity(cfg, die, state, status, hub="intel2", launched_now=0):
    """number of items this die may launch now"""
    hosts = [("localhost" if h == hub else h) for h in opt(cfg, die, "hosts")]
    mem = int(opt(cfg, die, "place_mem_gb"))
    # OWNER 11-01 (COORD 05:3x): queue_fill keeps the ot-run queue full (waiters > 0 on every host): launch whether or
    # not a host admits the place request now; the item waits in ot-run (memory admission) instead of in the planner
    if not cfg.get("queue_fill") and not any((status.get(h) or {}).get("admit", 0) >= mem for h in hosts):
        return 0
    n = min(int(cfg.get("max_inflight", DEFAULTS["max_inflight"])) - inflight(state) - launched_now,
            int(opt(cfg, die, "die_max_inflight")) - inflight(state, die))   # LAUNCH-ALL-1116: no per-tick launch cap (OWNER 11-13); max_launch_per_tick is ignored
    return max(0, n)


# ------------------------------------------------------------------------------------------------ kit class (12.27a)
# OWNER 12.27 (a) PILOT FIRST: one pilot kit per die x kit class reaches sign-off before volume launches of that class.
# Kit class key (AUTOBUILD-PIPE-4 10-31) = '<die>|<kind>|<family>': family = the wave item with its replica/variant
# suffixes dropped (S81 '__t<n>', '__cl<hash>'; HBM '__v<hash>', '__canon_<hash>') and every digit run as '#', so the
# 50+ ot_s81sl_leaf__t<n> types are one class and col_h9_r0_p3 / col_h10_r0_p4 are one class, while differently
# structured cores (hnx_rp3lp3h_n vs _s, sfu split3 pieces) stay apart.
_KC_SUFFIX = re.compile(r"__(?:t\d+|cl[0-9a-f]{6,}|v[0-9a-f]{6,}|canon_[0-9a-f]{6})(?=__|$)")


def kit_class(die, item, kind="type"):
    fam = item or ""
    while True:
        f2 = _KC_SUFFIX.sub("", fam)
        if f2 == fam:
            break
        fam = f2
    fam = re.sub(r"\d+", "#", fam.rstrip("_"))
    return f"{die}|{kind or 'type'}|{fam}"


# ------------------------------------------------------------------------------------------------ classification
# DIE-HBM-97 11-10 (COORD ruling, gplcap-classifier): this OpenROAD build caps each Nesterov pass at 5,000 iterations.
# At the cap it prints [WARNING GPL-1010], writes the placement anyway and the flow goes on: kv_line vC stopped at row
# 4,990 with overflow 0.370, repair_design then inserted 459k buffers and DPL-0038 failed at 153% utilisation.
# Converging peers end under 1,000 iterations at overflow <= 0.1 (q_b100pv1 957, q_b011 468, q_b012 441, q_spu1 463).
# A capped pass at overflow <= 0.1 is not this class.  Routability / timing-driven runs restart the Nesterov table
# many times (vB 225,900 iterations): each GPL-1010 closes one pass, and the first capped pass above the limit decides.
GPL_CAP_OVERFLOW = 0.1
GPL_CAP_MARK = "GPL-1010"
GPL_ROW = re.compile(r"^\s*(\d+) \|\s+([0-9.]+) \|")                       # 'Iteration | Overflow | HPWL ...' table
GPL_ROW_OLD = re.compile(r"Iter:\s*(\d+)\s+overflow:\s*([0-9.]+)", re.I)   # older [NesterovSolve] form
GPL_PROBE_PREFIX = "KW_GPL "                                                  # probe lines (after_place / PROBE_CLASSIFY)


def gpl_cap_noconverge(text, limit=GPL_CAP_OVERFLOW):
    """a 3_3_place_gp log (or the probe's KW_GPL lines: the last table row before each GPL-1010 and the warning) ->
    'GPL-1010 ... iteration N overflow X > 0.1 ...' for the first Nesterov pass that stopped at the iteration cap with
    overflow above limit, else None.  A pass whose last row is <= limit, or a log without GPL-1010, gives None."""
    last, capped = None, 0
    for ln in (text or "").splitlines():
        if ln.startswith(GPL_PROBE_PREFIX):
            ln = ln[len(GPL_PROBE_PREFIX):]
        if GPL_CAP_MARK in ln:
            capped += 1
            if last is not None and last[1] > limit:
                return (f"{GPL_CAP_MARK} Nesterov pass cap hit at iteration {last[0]} with overflow {last[1]:.3f} > "
                        f"{limit:g} (capped pass {capped}): placement did not converge; resizer/DPL would run on it")
            last = None
            continue
        m = GPL_ROW.search(ln) or GPL_ROW_OLD.search(ln)
        if m:
            last = (int(m.group(1)), float(m.group(2)))
    return None


# probe shell (gen host): the last table row before each GPL-1010 of the kit's global-place logs, prefixed KW_GPL
GPL_PROBE_AWK = (r"""awk '/GPL-1010/{print "KW_GPL " l; print "KW_GPL " $0; l=""; next} """
                 r"""/^ *[0-9]+ \| +[0-9.]+ \|/ || /Iter: *[0-9]+ +overflow:/{l=$0}'""")


# (class, stage regex or None, text regex, reason).  First match wins; stage-specific rules first.
PLACE_NO_ODB_WHY = "infra (place RC=0 but no 3_place.odb on the probed hosts: ot-run moved the job, no copy-back record; not a design failure)"


def place_rc0_no_odb(text):
    """WAVE-COPYBACK-1115 (FABLE-PD-PLACE-0830 class A): the place stage log ends RC=0 (or the wave's own KW_PLACE_NO_ODB marker) and the
    place stage still failed = the odb was not where the probe looked.  -> a reason line that quotes no log banner, or ''"""
    t = text or ""
    rcs = re.findall(r"(?m)^KW_PLACE_RC=(\d+)\s*$", t)
    if "KW_PLACE_NO_ODB" in t or (rcs and rcs[-1] == "0"):
        return "KW_PLACE_RC=0, 3_place.odb not found by the probe"
    return ""


DIE_TOOL_EXC_RE = re.compile(r"^(ValueError|KeyError): (.+)$", re.M)


def die_tool_exception(s):
    """the 'ValueError: ...' / 'KeyError: ...' line of a Traceback whose frames are in a die tool (tools/die_plan, tools/...), else None"""
    if "Traceback (most recent call last)" not in (s or ""):
        return None
    ms = list(DIE_TOOL_EXC_RE.finditer(s))
    if not ms or not re.search(r'File "[^"]*(?:die_plan|/tools/)[^"]*"', s):
        return None
    m = ms[-1]
    return f"{m.group(1)}: {m.group(2)[:260]}"


